window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0085", [{"word":"progeny","ipa_uk":"/ˈprɒdʒəni/","ipa_us":"/ˈprɑːdʒəni/","definition_zh":"后代；子女；子孙；（事物的）产物、成果","definition_en":"the young or offspring of a person, animal or plant, or the product that something brings forth","core_image":"一株母本植物在温室内分出整齐的幼苗行列，每一行都接着上一代的性状","scene":"温室里，育种者把同一母株的后代逐代排开，记录性状如何分离。Seedlings raised from a single parent plant form one visible progeny.","sceneCN":"这里 progeny 指「同一亲本繁育出的后代群体」（第 1 个义项：人或动植物的后代）；句意为温室里由单一母株育出的幼苗排成一行行，构成一个可见的后代群体。可辨识物件：育苗盘、幼苗、手写标签、温室玻璃。","pos":[{"tag":"n.","zh":"后代；子女；子孙（集合名词）"},{"tag":"n.","zh":"产物；成果（抽象义）"}],"collocations":[{"phrase":"progeny testing","zh":"后代测验"},{"phrase":"viable progeny","zh":"能存活的后代"},{"phrase":"hybrid progeny","zh":"杂交后代"},{"phrase":"numerous progeny","zh":"众多后代"},{"phrase":"produce progeny","zh":"产生后代"},{"phrase":"the progeny of","zh":"……的后代"}],"forms":[{"label":"复数（集合名词，形式不变）","form":"progeny"},{"label":"所有格","form":"progeny's"}],"derivatives":[{"word":"progenitor","pos":"n.","zh":"祖先；先驱"},{"word":"progenitive","pos":"adj.","zh":"有生殖力的；能生育的"},{"word":"progeniture","pos":"n.","zh":"生育；后代（罕见）"}],"senses":[{"no":"01","title":"Offspring of a living thing","titleCN":"人或动物的后代","definition":"the young produced by a person, animal or plant","definitionCN":"人或动物繁育出的幼体","example":"The mare's progeny all inherited her calm temperament.","exampleCN":"这匹母马的后代都继承了她沉静的性情。","why":"Progeny is a mass noun for what is brought forth, so it treats the young as a collective result rather than counting them one by one.","whyCN":"progeny 是把「被生出来之物」当作整体的集合名词，因此把幼体视作一个总的结果，而不是逐个计数。"},{"no":"02","title":"A line of descendants","titleCN":"一脉相承的子孙世系","definition":"the whole line of descendants from an ancestor","definitionCN":"从某一祖先延续下来的整条世系","example":"The estate passed through his progeny for four generations.","exampleCN":"这座庄园在他的子孙中传了四代。","why":"The Latin noun named a line of descent, so English progeny can mean the whole chain, not only the immediate young.","whyCN":"拉丁名词本指一条世系，因此英语 progeny 可以指整条链，而不只是眼前的幼体。"},{"no":"03","title":"Offspring of a plant","titleCN":"植物的子代","definition":"the seedlings or bulbs produced by a parent plant","definitionCN":"由母株繁育出的幼苗或球茎","example":"Gardeners sell the progeny of that famous rose.","exampleCN":"园艺师出售那株名贵月季的子代。","why":"Because plants also beget, the word applies to seedlings and bulbs without any change of form.","whyCN":"植物同样会繁育，因此这个词不加任何词形变化就可用于幼苗与球茎。"},{"no":"04","title":"A product of a cause","titleCN":"某事物的产物、成果","definition":"something produced as a result of another thing or process","definitionCN":"由另一事物或过程产生的结果","example":"The theory is the progeny of two older debates.","exampleCN":"这套理论是两场更早争论的产物。","why":"The metaphor treats an idea as a child: what comes forth from a cause is its progeny.","whyCN":"这个隐喻把观念当作孩子：从原因中产出的东西就是它的后代。"},{"no":"05","title":"Successors or followers","titleCN":"继承衣钵的后来者","definition":"the people who continue a tradition or institution","definitionCN":"延续某一传统或机构的人","example":"The movement's progeny now run several publishing houses.","exampleCN":"这场运动的后来者如今经营着几家出版社。","why":"People who continue a tradition are pictured as its descendants, so the word covers institutional heirs.","whyCN":"延续传统的人被想象成它的子孙，因此这个词也涵盖机构意义上的继承者。"},{"no":"06","title":"Progeny testing in breeding","titleCN":"育种中的后代测验","definition":"the practice of judging a parent by the performance of its offspring","definitionCN":"以后代的表现来评判亲本优劣的做法","example":"Progeny testing decides which bull is kept for breeding.","exampleCN":"后代测验决定哪头公牛留作种用。","why":"In animal breeding the word is fixed in the phrase progeny testing, where the offspring's performance is the evidence.","whyCN":"在畜牧育种中，这个词固定于 progeny testing 这一短语，以子代的表现作为证据。"},{"no":"07","title":"A group taken collectively","titleCN":"作为一个整体看待的后代群","definition":"the offspring of one parent considered as a single group","definitionCN":"把同一亲本的后代视作一个整体","example":"The whole progeny was raised in the same nursery.","exampleCN":"整批后代都在同一间育苗室中育成。","why":"The noun often takes a singular verb because it names a group; this collective reading is why a plural in -ies is unusual.","whyCN":"这个名词常接单数动词，因为它命名的是一个群体；这种集合用法正是它少用 -ies 复数的原因。"},{"no":"08","title":"A legacy carried forward","titleCN":"延续下来的遗产（作品、影响）","definition":"the lasting work or influence that survives its source","definitionCN":"在源头之后仍然存续的作品或影响","example":"Her progeny is a school of composers who still use her method.","exampleCN":"她留下的传承是一批至今仍用她方法的作曲家。","why":"The figurative sense can outlast biology: what survives is not a child but a body of work.","whyCN":"抽象义可以超出生物学：存续下来的不是孩子，而是一整套作品。"}],"etymology":{"intro":{"en":"Progeny came into English through Old French from Latin progenies 'line of descent, offspring', a derivative of progignere 'bring forth', itself pro- 'forth' plus gignere 'beget'.","cn":"progeny 经古法语进入英语，源自拉丁 progenies「世系、后代」，由 progignere「向前生出」派生，而后者是 pro-「向前」加 gignere「生育」。"},"items":[{"era":"LATIN GIGNERE","en":"Gignere 'to beget, bring forth' is the source of genitor and generate. Its pre-Latin form is reconstructed as PIE *ǵenh₁-, so the starred form is a reconstruction rather than a recorded word.","cn":"gignere「生育、产生」是 genitor 与 generate 的来源。它在拉丁语之前的形式被重构为原始印欧语 *ǵenh₁-，带星号的形式属于重构形式，并非有记录的词。"},{"era":"LATIN PROGENIES","en":"Pro- 'forth' plus gignere produced progignere 'bring forth'; its noun progenies named the line of descent rather than a single child.","cn":"pro-「向前」加 gignere 构成 progignere「向前生出」；其名词 progenies 指一条世系，而非单个孩子。"},{"era":"OLD FRENCH","en":"Old French progenie carried the noun into English in the fourteenth century; the exact first citation is uncertain.","cn":"古法语 progenie 在 14 世纪把这个名词带入英语；确切的最早书证年代不确定。"},{"era":"FIGURATIVE WIDENING","en":"By the sixteenth and seventeenth centuries progeny was applied to works, results and successors, not only living offspring.","cn":"到 16、17 世纪，progeny 已被用于作品、结果与后继者，不再仅指活着的后代。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper root): the internal structure of the PIE root is reconstructed, and competing reconstructions exist, so no single form should be treated as settled.","cn":"来源不确定（更深词根）：该原始印欧词根的内部结构属于重构，且存在互相竞争的多种重构，因此不应把任何单一形式当作定论。"}]},"similar":{"note":{"en":"Group one holds words that look like progeny or share its root; group two holds the ordinary words for offspring and descendants.","cn":"第一组是与 progeny 形近或同根的词；第二组是表示后代与子孙的常用近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"progenitor","ipa":"/prəˈdʒenɪtə/","tag":"same root, the one who begets","definition":"The agent noun from the same Latin stem: a forefather or precursor, not the offspring itself.","definitionCN":"同一拉丁词干的施事名词：指祖先或先驱，而不是后代本身。"},{"word":"progenitive","ipa":"/prəˈdʒenɪtɪv/","tag":"same root, a capacity","definition":"An adjective built on the Latin stem, meaning capable of producing offspring; it describes a capacity, not the young.","definitionCN":"由同一拉丁词干构成的形容词，意为有生育能力；它描述能力，而非幼体。"},{"word":"progeniture","ipa":"/prəˈdʒenɪtʃə/","tag":"same root, rare noun","definition":"A rare noun for the act of bringing forth or the offspring produced; it survives mostly in older legal and literary writing.","definitionCN":"罕见名词，指生育行为或所生后代；主要残存于较早的法律与文学文本。"},{"word":"prodigy","ipa":"/ˈprɒdɪdʒi/","tag":"different root","definition":"From Latin prodigium 'portent', not from gignere: a marvel or a child of exceptional talent. The resemblance is only in sound.","definitionCN":"来自拉丁 prodigium「预兆」，并非出自 gignere：指奇观或天才儿童。相似仅是读音上的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"offspring","ipa":"/ˈɒfsprɪŋ/","tag":"the neutral general word","definition":"The everyday term for the young of a person or animal; it counts individuals more readily than progeny.","definitionCN":"指人或动物幼体的日常通称；比 progeny 更容易逐个计数。"},{"word":"descendant","ipa":"/dɪˈsendənt/","tag":"one link in a line","definition":"A person or group descended from an ancestor, often used for distant generations rather than the immediate young.","definitionCN":"指某一祖先传下的人或群体，常用于较远的世代而非眼前的幼体。"},{"word":"issue","ipa":"/ˈɪʃuː/","tag":"legal and formal","definition":"In law and formal writing, issue means offspring or descendants, especially in wills and genealogies.","definitionCN":"在法律与正式文体中，issue 指后代或子嗣，尤见于遗嘱与族谱。"},{"word":"brood","ipa":"/bruːd/","tag":"all young of one hatch","definition":"The whole set of young hatched or born at one time, usually birds; it stresses the group, not the lineage.","definitionCN":"指一次孵化或出生的一整窝幼体，多用于鸟类；强调群体而非世系。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"pro- 'forth' + gignere 'beget': what is brought forth.","cn":"pro-「向前」+ gignere「生育」：被生出来之物。"},{"en":"The family runs progeny, progenitor, progenitive and progeniture.","cn":"同族词包括 progeny、progenitor、progenitive 与 progeniture。"},{"en":"Breeding fixes progeny in the phrase progeny testing.","cn":"畜牧育种把 progeny 固定在后代测验这一短语中。"},{"en":"The same Latin stem yields generate, generation and genesis.","cn":"同一拉丁词干还产生 generate、generation 与 genesis。"},{"en":"Progeny is a mass noun, so it usually takes a singular verb.","cn":"progeny 是集合名词，因此通常接单数动词。"}],"abstract":[{"en":"Picture a tree dropping seeds in rings around itself, each ring a generation.","cn":"想象一棵树在自己周围一圈圈落种，每一圈就是一代。"},{"en":"Picture a book that keeps being rewritten by students who never met the author.","cn":"想象一本书被从未见过作者的学生不断改写。"},{"en":"Picture a river splitting into channels that all carry the same water.","cn":"想象一条河分成多股水道，却都带着同样的水。"}]},"examples":[{"en":"The plant's progeny were replanted on the far side of the valley.","cn":"这株植物的子代被移栽到山谷另一侧。"},{"en":"Progeny testing takes years because the offspring must first grow up.","cn":"后代测验需要数年，因为子代必须先长大。"},{"en":"His progeny in the profession still cite the same handbook.","cn":"他在这一行里的后继者仍在引用同一本手册。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"pro（向前）+ gen（生）——向前生出来的一群 → 后代；注意别与 prodigy（奇才、预兆）混。","word":"progeny"},"root":"拉丁 progenies「世系、后代」← pro-（向前）+ gignere（生育）；gignere 与 generate、gene 同出原始印欧语 *ǵenh₁-（重构形式），更深来源不确定。","sensesIntro":{"en":"Eight senses follow one gesture: something is brought forth, and that bringing-forth is then read as offspring, lineage, plant young, a product, successors, a breeding test, a collective group and finally a surviving body of work.","cn":"八个义项沿同一个动作展开：某物被生出，这一「生出」随后被读作后代、世系、植物子代、产物、后继者、育种测验、集合群体，最后是存续下来的作品整体。"},"semanticMap":{"core":{"en":"CORE IMAGE: a parent plant sending up a row of seedlings, each carrying part of the same pattern.","cn":"核心意象：一株母本植物顶出一排幼苗，每一株都带着同一格局的一部分。"},"chain":["BRING FORTH","OFFSPRING","LINE OF DESCENT","PRODUCT OF A CAUSE","SUCCESSORS","SURVIVING WORK"],"branches":[{"senses":"S1 · S3","en":"LIVING OFFSPRING: animals and plants both bring forth young, and the noun covers either.","cn":"活着的后代：动物与植物都会繁育幼体，这个词两者都覆盖。"},{"senses":"S2 · S7","en":"LINE AND GROUP: the same noun names a chain of generations or one parent's whole brood.","cn":"世系与群体：同一个名词既指代代相连的链，也指某一亲本的整批子代。"},{"senses":"S4","en":"PRODUCT: an idea or result is pictured as what a cause gives birth to.","cn":"产物：观念或结果被想象成原因所生之物。"},{"senses":"S5 · S8","en":"SUCCESSORS AND WORK: people who carry on a tradition, and the work that outlives its maker.","cn":"后继者与作品：延续传统的人，以及比作者活得更久的作品。"},{"senses":"S6","en":"BREEDING TEST: the offspring's performance becomes the evidence for judging the parent.","cn":"育种测验：子代表现成为评判亲本的证据。"}]},"affixes":{"intro":{"en":"Progeny is a Latin noun whose prefix and root also build several English words, so the family can be read morpheme by morpheme.","cn":"progeny 是一个拉丁名词，其前缀与词根还构成若干英语词，因此这个词族可以按语素逐个读出。"},"latinIntro":{"en":"Latin gignere gives generate, generation, genitor and progeny; pro- adds the sense of bringing something forward.","cn":"拉丁 gignere 衍生 generate、generation、genitor 与 progeny；pro- 增添「向前带出」的意思。"},"items":[{"word":"pro-","structure":"pro- (Latin prefix, 'forth, forward')","meaning":"forward; forth","meaningCN":"向前；往外","example":"The prefix sends the action outward from a source.","exampleCN":"这个前缀把动作从源头往外送出。"},{"word":"gignere","structure":"gignere (Latin verb, third conjugation)","meaning":"to beget, bring forth","meaningCN":"生育；产生","example":"The root names the act of bringing something into being.","exampleCN":"这个词根命名「使某物进入存在」的动作。"},{"word":"progenies","structure":"pro- + gignere, noun of result","meaning":"offspring, line of descent","meaningCN":"后代；世系","example":"Progenies named the whole line rather than one child.","exampleCN":"progenies 指整条世系，而非单个孩子。"},{"word":"progeny","structure":"English noun from progenies","meaning":"offspring; product","meaningCN":"后代；产物","example":"The mare's progeny were sold at auction.","exampleCN":"这匹母马的后代在拍卖会上售出。"},{"word":"progenitor","structure":"progenit- + -or (one who acts)","meaning":"forefather; precursor","meaningCN":"祖先；先驱","example":"The progenitor of the family arrived in 1700.","exampleCN":"这个家族的祖先于 1700 年到来。"},{"word":"progenitive","structure":"progenit- + -ive (tending to)","meaning":"capable of producing offspring","meaningCN":"有生殖力的","example":"Progenitive cells divide throughout the season.","exampleCN":"具生殖能力的细胞在整个季节不断分裂。"},{"word":"generate","structure":"generare (same PIE family)","meaning":"to produce, beget","meaningCN":"产生；生成","example":"The reactor generates heat steadily.","exampleCN":"反应堆稳定地产生热量。"},{"word":"generation","structure":"generate + -ion (action or result)","meaning":"the act of producing; a cohort","meaningCN":"产生；一代人","example":"Each generation inherited the same orchard.","exampleCN":"每一代人都继承了同一片果园。"},{"word":"gene","structure":"Greek genos (same PIE family, not a derivative)","meaning":"unit of heredity","meaningCN":"基因","example":"One gene codes for one product.","exampleCN":"一个基因编码一种产物。"},{"word":"genesis","structure":"Greek genesis 'origin'","meaning":"origin, coming into being","meaningCN":"起源；创生","example":"The genesis of the project was a single note.","exampleCN":"这个项目起源于一张便条。"}],"latinEntries":[{"word":"gignere","structure":"gigno, gignere, genui, genitum (verb, third conjugation)","meaning":"to beget, produce","meaningCN":"生育；产生"},{"word":"progenies","structure":"progenies, progeniei (f., fifth declension)","meaning":"line of descent, offspring","meaningCN":"世系；后代"},{"word":"progenitor","structure":"progenitor, progenitoris (m., third declension)","meaning":"forefather, founder","meaningCN":"祖先；创立者"},{"word":"genitura","structure":"genitura, geniturae (f., first declension)","meaning":"birth, generation","meaningCN":"出生；生育"}]}},{"word":"inheritance","ipa_uk":"/ɪnˈherɪtəns/","ipa_us":"/ɪnˈherɪtəns/","definition_zh":"继承（物）；遗产；遗传；（文化）传承；继承权","definition_en":"property or a right received from someone who has died, or the transmission of traits and traditions from one generation to the next","core_image":"一只旧木匣装着钥匙与地契，从一双手递到另一双手，匣盖上的封蜡已经裂开","scene":"老宅的钥匙和地契被装进同一个木匣，交到下一代手里。The eldest daughter received the farm as her inheritance.","sceneCN":"这里 inheritance 指「从去世的亲人那里接下的财产」（第 1 个义项：继承所得的财物）；句意为长女把这座农场作为遗产接了下来。可辨识物件：木匣、黄铜钥匙、地契、裂开的封蜡。","pos":[{"tag":"n.","zh":"继承（物）；遗产；继承权"},{"tag":"n.","zh":"遗传；传承（抽象义）"}],"collocations":[{"phrase":"inheritance tax","zh":"遗产税"},{"phrase":"receive an inheritance","zh":"得到遗产"},{"phrase":"leave an inheritance","zh":"留下遗产"},{"phrase":"genetic inheritance","zh":"遗传"},{"phrase":"cultural inheritance","zh":"文化传承"},{"phrase":"right of inheritance","zh":"继承权"}],"forms":[{"label":"复数（可用，但常作不可数）","form":"inheritances"},{"label":"所有格","form":"inheritance's"},{"label":"形容词","form":"inheritable"}],"derivatives":[{"word":"inherit","pos":"v.","zh":"继承；遗传"},{"word":"inheritor","pos":"n.","zh":"继承人"},{"word":"inheritable","pos":"adj.","zh":"可继承的；可遗传的"},{"word":"disinherit","pos":"v.","zh":"剥夺继承权"}],"senses":[{"no":"01","title":"Property received after a death","titleCN":"从逝者那里接下的财产","definition":"money or property passed to an heir after someone dies","definitionCN":"某人去世后传给继承人的钱财或财产","example":"She used her inheritance to buy the workshop.","exampleCN":"她用继承来的钱买下了那间作坊。","why":"The word names what is handed over at death, so the first sense is the concrete estate rather than the act of receiving it.","whyCN":"这个词指在死亡时被交出的东西，因此第一个义项是具体的遗产，而不是领取的动作。"},{"no":"02","title":"The act or right of inheriting","titleCN":"继承行为或继承权","definition":"the legal act or right by which an heir receives an estate","definitionCN":"继承人取得遗产的法定行为或权利","example":"The inheritance of the land was disputed for years.","exampleCN":"这片土地的继承权争了多年。","why":"Because the noun covers both the thing and the legal relation, English can speak of an inheritance and of the right of inheritance.","whyCN":"因为这个名词同时涵盖财物与法律关系，英语既能说「一份遗产」，也能说「继承权」。"},{"no":"03","title":"Genetic transmission","titleCN":"遗传传递","definition":"the passing of traits from parents to offspring through genes","definitionCN":"性状经基因由亲代传给子代","example":"Eye colour shows a simple pattern of inheritance.","exampleCN":"眼睛颜色呈现出简单的遗传模式。","why":"Nineteenth-century biology borrowed the legal word because traits seemed to be handed down like property.","whyCN":"19 世纪的生物学借用了这个法律词，因为性状看起来像财产一样被传下去。"},{"no":"04","title":"Cultural heritage","titleCN":"文化传承","definition":"the traditions, language or art received from earlier generations","definitionCN":"从更早世代接下的传统、语言或艺术","example":"The city claims the inheritance of three empires.","exampleCN":"这座城市自称承袭了三个帝国的遗产。","why":"The legal frame widened to anything received from the past, so a city can inherit an empire's habits of building.","whyCN":"法律框架被拓宽到任何从过去接下的东西，因此一座城市可以继承一个帝国的建造习惯。"},{"no":"05","title":"A burden or condition passed on","titleCN":"一并接下的负担或状况","definition":"a debt, problem or condition that comes with what is received","definitionCN":"随所得之物一起到来的债务、问题或状况","example":"He carries an inheritance of debt from the previous owner.","exampleCN":"他背上了前任业主留下的一身债务。","why":"What is inherited is not always a gift; the word can name the liabilities that arrive with the property.","whyCN":"被继承的不总是礼物；这个词也能指随财产一起到来的负担。"},{"no":"06","title":"Class inheritance in computing","titleCN":"计算机中的类继承","definition":"the mechanism by which one class or module takes properties from a parent","definitionCN":"一个类或模块从父级取得属性的机制","example":"Class inheritance lets one module reuse another's methods.","exampleCN":"类继承让一个模块可以复用另一个模块的方法。","why":"Programming borrowed the family metaphor: a child class receives behaviour from its parent, just as an heir receives property.","whyCN":"编程借用了家庭隐喻：子类从父类取得行为，正如继承人取得财产。"},{"no":"07","title":"Inheritance tax and legal thresholds","titleCN":"遗产税与法定起征点","definition":"the tax charged on an estate before or after it passes to heirs","definitionCN":"遗产传给继承人之前或之后所征的税","example":"Inheritance tax applies above a fixed threshold.","exampleCN":"遗产税适用于超过固定起征点的部分。","why":"Once the state began taxing transfers at death, the noun became fixed in the compound inheritance tax.","whyCN":"当国家开始对死亡时的财产转移征税后，这个名词就固定于遗产税这一复合词中。"},{"no":"08","title":"A legacy of consequences","titleCN":"留下的后果与影响","definition":"the lasting effects that one period or action leaves to those who follow","definitionCN":"某一时期或行动留给后来者的持久影响","example":"The reform left an inheritance of distrust.","exampleCN":"这场改革留下了一份不信任的遗产。","why":"The metaphor treats consequences as an estate: later people receive them whether they want them or not.","whyCN":"这个隐喻把后果当作一份产业：后来者不管愿不愿意都得接收。"}],"etymology":{"intro":{"en":"Inheritance comes from Anglo-French enheritance, from enheriter 'to make an heir', from Late Latin inhereditare, built on heres (hered-) 'heir'.","cn":"inheritance 来自盎格鲁-法语 enheritance，源自动词 enheriter「立为继承人」，再上溯为晚期拉丁 inhereditare，其词干是 heres（hered-）「继承人」。"},"items":[{"era":"LATIN HERES","en":"Heres (genitive heredis) meant 'heir'. Its deeper origin is not established; suggestions linking it to other Indo-European words are hypotheses, and any PIE form offered for it is a reconstruction.","cn":"heres（属格 heredis）意为「继承人」。其更深来源未得到确证；把它与其他印欧语词联系起来的说法只是假说，凡为其给出的原始印欧语形式均属重构形式。"},{"era":"LATIN HEREDITAS","en":"Hereditas 'inheritance, heirship' and hereditarius 'of an heir' were formed on the hered- stem.","cn":"hereditas「继承、继承权」与 hereditarius「继承人的」都建立在 hered- 词干上。"},{"era":"LATE LATIN INHEREDITARE","en":"In- 'in, into' plus hereditare 'to inherit' gave inhereditare 'to appoint as heir'.","cn":"in-「进入」加 hereditare「继承」构成 inhereditare「立为继承人」。"},{"era":"ANGLO-FRENCH","en":"Enheriter and its noun enheritance reached English in the fourteenth century; legal use came first, and the exact first citation is uncertain.","cn":"enheriter 及其名词 enheritance 在 14 世纪进入英语；法律用法最先出现，确切的最早书证不确定。"},{"era":"BIOLOGICAL SENSE","en":"In the nineteenth century the word was extended to the transmission of traits, alongside the new science of heredity.","cn":"19 世纪，随着遗传学兴起，这个词被扩展到性状传递。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper root): first dates for the biological sense are approximate, and the pre-Latin origin of heres remains uncertain.","cn":"来源不确定（首见年代与更深词根）：生物学义项的首见年代只是约数，heres 在拉丁语之前的来源仍不确定。"}]},"similar":{"note":{"en":"Group one holds words built on the same hered- stem or that merely look similar; group two holds the legal and everyday words for what is left to heirs.","cn":"第一组是同出 hered- 词干或仅形近的词；第二组是法律与日常语境中表示「留给继承人的东西」的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"heritage","ipa":"/ˈherɪtɪdʒ/","tag":"same root, what is handed down","definition":"The same Latin hered- stem, but heritage usually names cultural or family possessions rather than a legal share.","definitionCN":"同一拉丁 hered- 词干，但 heritage 通常指文化或家族传承物，而非法定份额。"},{"word":"heredity","ipa":"/həˈredəti/","tag":"same root, the process","definition":"The biological transmission of traits, not the property received; the two words split in the nineteenth century.","definitionCN":"指性状的生物传递，而非所收财产；两个词在 19 世纪分化。"},{"word":"inheritor","ipa":"/ɪnˈherɪtə/","tag":"same family, the person","definition":"The person who receives, not the thing received; the suffix -or marks the agent.","definitionCN":"指接收的人，而非所收之物；后缀 -or 标记施事者。"},{"word":"inherence","ipa":"/ɪnˈhɪərəns/","tag":"different root","definition":"From inhaerere 'to stick in', not heres: the state of being inherent or built into something. The resemblance is accidental.","definitionCN":"来自 inhaerere「黏附于内」，并非 heres：指内在于某物的状态。相似只是偶然。"}]},{"heading":"NEAR MEANING","entries":[{"word":"legacy","ipa":"/ˈleɡəsi/","tag":"a gift left by will","definition":"A specific gift left in a will; inheritance can also mean the whole estate or the right to it.","definitionCN":"遗嘱中留下的具体馈赠；inheritance 还可指全部遗产或继承权。"},{"word":"bequest","ipa":"/bɪˈkwest/","tag":"personal property by will","definition":"Property given by a will, usually personal items; narrower and more legal than inheritance.","definitionCN":"遗嘱赠予的财产，通常为个人物品；比 inheritance 更窄、更法律化。"},{"word":"estate","ipa":"/ɪˈsteɪt/","tag":"the whole property","definition":"The total property a person leaves, before it is divided among heirs.","definitionCN":"某人留下的全部财产，在分配给继承人之前。"},{"word":"endowment","ipa":"/ɪnˈdaʊmənt/","tag":"a lasting fund or gift","definition":"Money or property given to an institution, often to produce income; it stresses the lasting gift rather than the heir.","definitionCN":"捐给机构的钱或财产，常用来产生收益；强调持续的馈赠而非继承人。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"in- 'in' + heres 'heir': being put into the heir's place.","cn":"in-「进入」+ heres「继承人」：被放进继承人的位置。"},{"en":"The family runs inherit, inheritance, inheritor, inheritable, hereditary and heredity.","cn":"同族词包括 inherit、inheritance、inheritor、inheritable、hereditary 与 heredity。"},{"en":"Legal use came first; the biological use is a nineteenth-century extension.","cn":"法律用法最先出现，生物学用法是 19 世纪的扩展。"},{"en":"In computing, inheritance means a subclass takes methods from its parent.","cn":"在计算机中，inheritance 指子类从父类取得方法。"},{"en":"Fixed phrase: inheritance tax.","cn":"固定搭配：遗产税。"}],"abstract":[{"en":"Picture a house key passed from hand to hand until the first hand is forgotten.","cn":"想象一把房门钥匙被一双手传一双手，直到最初那双手被遗忘。"},{"en":"Picture a recipe card whose stains are inherited along with the recipe.","cn":"想象一张食谱卡，油渍和做法一起被继承下来。"},{"en":"Picture a debt that arrives with the furniture and has no invoice.","cn":"想象一笔债务随家具一起到来，却没有账单。"}]},"examples":[{"en":"The inheritance was divided equally among the four children.","cn":"遗产在四个孩子之间平均分配。"},{"en":"Researchers traced the inheritance of the trait across five generations.","cn":"研究者追踪了这一性状在五代人中的遗传。"},{"en":"Class inheritance reduced the amount of code the team had to write.","cn":"类继承减少了团队需要编写的代码量。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"in（进入）+ herit（继承人）——进入继承人的位置 → 继承（物）；同根的 heritage 是「传承物」。","word":"inheritance"},"root":"拉丁 hereditas「继承、继承权」← heres（hered-）「继承人」；经古法语 enheritance 进入英语；heres 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one handover: a box passes at death and becomes property, a right, a biological trait, a culture, a burden, a piece of code, a tax and finally a set of consequences.","cn":"八个义项沿同一次交接展开：一只匣子在死亡时被递出，成为财产、权利、生物性状、文化、负担、代码、税，最后成为一整套后果。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wooden box of keys and deeds passing from one hand to the next.","cn":"核心意象：一只装着钥匙与地契的木匣，从一双手递到另一双手。"},"chain":["HAND OVER","LEGAL SHARE","RIGHT TO RECEIVE","TRAIT TRANSMISSION","CULTURAL HANDING DOWN","CONSEQUENCE LEFT BEHIND"],"branches":[{"senses":"S1 · S2","en":"PROPERTY AND RIGHT: the estate itself and the legal power to receive it.","cn":"财产与权利：遗产本身，以及取得它的法定资格。"},{"senses":"S3 · S5","en":"WHAT IS TRANSMITTED: a trait can arrive like property, and so can a debt.","cn":"被传递之物：性状可以像财产一样到来，债务也可以。"},{"senses":"S4","en":"CULTURE: buildings, language and habits are received from earlier generations.","cn":"文化：建筑、语言与习惯从更早世代接下。"},{"senses":"S6","en":"COMPUTING: a child class receives behaviour from its parent class.","cn":"计算机：子类从父类取得行为。"},{"senses":"S7 · S8","en":"TAX AND CONSEQUENCE: the state takes a share, and later people receive the effects.","cn":"税与后果：国家取走一份，后来者接收影响。"}]},"affixes":{"intro":{"en":"Inheritance is built from a Latin prefix and the hered- stem, and the same pieces form a large legal and biological family.","cn":"inheritance 由拉丁前缀与 hered- 词干构成，这些成分组成了一个庞大的法律与生物词族。"},"latinIntro":{"en":"Latin heres (hered-) gives hereditas, hereditarius, inherit and inheritance; in- adds the sense of entering a position.","cn":"拉丁 heres（hered-）衍生 hereditas、hereditarius、inherit 与 inheritance；in- 增添「进入某一位置」的意思。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'in, into')","meaning":"in; into","meaningCN":"进入；在内","example":"The prefix places the receiver inside the heir's position.","exampleCN":"这个前缀把接收者放进继承人的位置。"},{"word":"heres","structure":"heres, heredis (Latin noun, third declension)","meaning":"heir","meaningCN":"继承人","example":"The stem names the person who receives.","exampleCN":"这个词干命名接收者。"},{"word":"hereditare","structure":"hereditare (Latin verb, first conjugation)","meaning":"to inherit; to leave as an inheritance","meaningCN":"继承；遗赠","example":"Hereditare turned the heir into an action.","exampleCN":"hereditare 把「继承人」变成了动作。"},{"word":"inhereditare","structure":"in- + hereditare (Late Latin verb)","meaning":"to appoint as heir","meaningCN":"立为继承人","example":"The Late Latin verb added the legal act of naming an heir.","exampleCN":"晚期拉丁动词增添了指定继承人的法律动作。"},{"word":"inherit","structure":"English verb from Old French enheriter","meaning":"to receive by succession","meaningCN":"继承；承袭","example":"She inherited the house from her aunt.","exampleCN":"她从姑妈那里继承了这所房子。"},{"word":"inheritance","structure":"inherit + -ance (state or result)","meaning":"the estate or the act of receiving it","meaningCN":"遗产；继承","example":"The inheritance was divided among the children.","exampleCN":"遗产在孩子们之间分配。"},{"word":"inheritor","structure":"inherit + -or (one who acts)","meaning":"a person who inherits","meaningCN":"继承人","example":"The inheritor signed the deed.","exampleCN":"继承人在契据上签了字。"},{"word":"inheritable","structure":"inherit + -able (can be)","meaning":"able to be inherited","meaningCN":"可继承的；可遗传的","example":"The trait is inheritable in a simple pattern.","exampleCN":"这一性状以简单模式可遗传。"},{"word":"hereditary","structure":"hereditarius + -ary (adjective suffix)","meaning":"of inheritance; transmitted by succession","meaningCN":"继承的；世袭的；遗传的","example":"The title was hereditary.","exampleCN":"这个爵位是世袭的。"},{"word":"heredity","structure":"hereditas (Latin noun)","meaning":"the transmission of traits","meaningCN":"遗传","example":"Heredity and environment interact.","exampleCN":"遗传与环境相互作用。"},{"word":"disinherit","structure":"dis- 'away' + inherit","meaning":"to cut an heir out of a will","meaningCN":"剥夺继承权","example":"The old man disinherited his nephew.","exampleCN":"老人剥夺了侄子的继承权。"},{"word":"heritage","structure":"Old French heritage (same hered- stem)","meaning":"what is handed down","meaningCN":"传承物；文化遗产","example":"The city protects its heritage.","exampleCN":"这座城市保护自己的文化遗产。"}],"latinEntries":[{"word":"heres","structure":"heres, heredis (m./f., third declension)","meaning":"heir","meaningCN":"继承人"},{"word":"hereditas","structure":"hereditas, hereditatis (f., third declension)","meaning":"inheritance, heirship","meaningCN":"继承；继承权"},{"word":"hereditarius","structure":"hereditarius, hereditária, hereditarium (adj.)","meaning":"of an inheritance","meaningCN":"继承的"},{"word":"inhereditare","structure":"inhereditare, inhereditavi, inhereditatum (verb, first conjugation)","meaning":"to appoint as heir","meaningCN":"立为继承人"}]}},{"word":"inherit","ipa_uk":"/ɪnˈherɪt/","ipa_us":"/ɪnˈherɪt/","definition_zh":"继承（财产、权利）；经遗传获得（性状）；接过（传统、问题）","definition_en":"to receive property, a right or a trait from someone who came before, especially after that person's death","core_image":"一只年轻的手接过一把旧钥匙，钥匙上还挂着上一代人的标签","scene":"父亲去世后，兄妹在律师面前分割田产。The younger son will inherit the orchard and the debts that come with it.","sceneCN":"这里 inherit 指「因他人去世而承接财产」（第 1 个义项：依法承接逝者的财物）；句意为小儿子将继承果园，也继承随之而来的债务。可辨识物件：遗嘱、钢笔、果园平面图、债务清单。","pos":[{"tag":"vt.","zh":"继承（财产、权利、头衔）"},{"tag":"vt.","zh":"经遗传获得（性状、特征）"},{"tag":"vt.","zh":"接过（传统、问题、代码）"}],"collocations":[{"phrase":"inherit property","zh":"继承财产"},{"phrase":"inherit a trait","zh":"遗传某种性状"},{"phrase":"inherit the throne","zh":"继承王位"},{"phrase":"inherit a tradition","zh":"承接传统"},{"phrase":"inherit a problem","zh":"接过一个难题"},{"phrase":"inherit from","zh":"从……继承"}],"forms":[{"label":"三单（he/she/it）","form":"inherits"},{"label":"过去式","form":"inherited"},{"label":"过去分词","form":"inherited"},{"label":"现在分词","form":"inheriting"},{"label":"名词（继承；遗产）","form":"inheritance"},{"label":"名词（继承人）","form":"inheritor"}],"derivatives":[{"word":"inheritance","pos":"n.","zh":"继承；遗产；遗传"},{"word":"inheritor","pos":"n.","zh":"继承人"},{"word":"inheritable","pos":"adj.","zh":"可继承的；可遗传的"},{"word":"disinherit","pos":"v.","zh":"剥夺继承权"}],"senses":[{"no":"01","title":"Receive property by will or law","titleCN":"依法承接逝者的财物","definition":"to receive money or property from someone who has died","definitionCN":"在某人去世后取得其钱财或财产","example":"She inherited the house from her aunt.","exampleCN":"她从姑妈那里继承了这所房子。","why":"The verb starts in the legal world: a death opens a transfer, and the heir steps into the place of the dead.","whyCN":"这个动词起于法律世界：死亡开启一次转移，继承人走进逝者的位置。"},{"no":"02","title":"Receive a genetic trait","titleCN":"经遗传获得性状","definition":"to receive a physical or behavioural trait through genes","definitionCN":"通过基因获得身体或行为特征","example":"Children inherit half their genes from each parent.","exampleCN":"孩子从父母各继承一半基因。","why":"Biology extended the legal verb because genes are passed down in a line, much as property is.","whyCN":"生物学扩展了这个法律动词，因为基因也沿一条线传下，很像财产。"},{"no":"03","title":"Receive a quality or tendency","titleCN":"承接性格或倾向","definition":"to receive a quality, habit or tendency from a parent or ancestor","definitionCN":"从父母或祖先那里得到某种品质、习惯或倾向","example":"He inherited his father's patience.","exampleCN":"他继承了父亲的耐心。","why":"The biological sense widened to character: what runs in a family need not be a gene, only a pattern learned or shared.","whyCN":"生物义又扩展到性格：家族中流传的不一定是基因，也可能只是习得或共享的模式。"},{"no":"04","title":"Succeed to a title or office","titleCN":"承袭头衔或职位","definition":"to take over a title, throne or office from a predecessor","definitionCN":"从前任那里接过头衔、王位或职位","example":"The eldest son will inherit the throne.","exampleCN":"长子将继承王位。","why":"Because titles pass by succession, the verb covers political and ceremonial positions, not only goods.","whyCN":"由于头衔按世袭传递，这个动词也涵盖政治与礼仪职位，而不只是财物。"},{"no":"05","title":"Take over a problem or situation","titleCN":"接过问题或局面","definition":"to receive responsibility for a situation created by someone else","definitionCN":"对他人造成的局面承担责任","example":"The new manager inherited a demoralized team.","exampleCN":"新经理接手了一支士气低落的团队。","why":"A successor receives the whole situation along with the job, so the verb can name unwelcome conditions.","whyCN":"继任者连同职位一起接收整个局面，因此这个动词也能指不受欢迎的状况。"},{"no":"06","title":"Receive a tradition or language","titleCN":"承接传统或语言","definition":"to receive a tradition, language or body of knowledge from earlier people","definitionCN":"从更早的人那里接过传统、语言或知识体系","example":"Every generation inherits the language of its parents.","exampleCN":"每一代人都继承父母的语言。","why":"Culture is transmitted without wills or genes, and the same verb covers that third kind of handover.","whyCN":"文化既无遗嘱也无基因，这个动词同样覆盖这第三种交接。"},{"no":"07","title":"Derive from a parent class","titleCN":"从父类派生","definition":"in computing, to take properties or methods from a parent class","definitionCN":"在计算机中，从父类取得属性或方法","example":"Subclasses inherit methods from their superclass.","exampleCN":"子类从超类继承方法。","why":"Programming reused the family image: a child class stands in the same relation to its parent as an heir to an ancestor.","whyCN":"编程复用了家庭意象：子类与父类的关系，正如继承人与祖先的关系。"},{"no":"08","title":"Receive a name or identity","titleCN":"承袭名字或身份","definition":"to receive a name, role or identity that belonged to an earlier person","definitionCN":"承接属于先前某人的名字、角色或身份","example":"She inherited her grandmother's name along with her recipes.","exampleCN":"她继承了祖母的名字，也继承了她的食谱。","why":"Names and roles can be handed down like property, so identity itself becomes something one inherits.","whyCN":"名字与角色能像财产一样传下，因此身份本身也成了可以继承之物。"}],"etymology":{"intro":{"en":"Inherit comes from Old French enheriter, from Late Latin inhereditare 'to appoint as heir', built on in- 'in' and heres (hered-) 'heir'.","cn":"inherit 来自古法语 enheriter，再上溯为晚期拉丁 inhereditare「立为继承人」，由 in-「进入」与 heres（hered-）「继承人」构成。"},"items":[{"era":"LATIN HERES","en":"Heres (genitive heredis) meant 'heir'. Its deeper origin is not established; any PIE form proposed for it is a reconstruction, and competing explanations remain hypotheses.","cn":"heres（属格 heredis）意为「继承人」。其更深来源未得到确证；为其提出的任何原始印欧语形式均属重构，互相竞争的解释仍只是假说。"},{"era":"LATIN HEREDITARE","en":"Hereditare 'to inherit, to leave as an inheritance' turned the noun into a verb and produced hereditas and hereditarius.","cn":"hereditare「继承、遗赠」把名词变成动词，并产生 hereditas 与 hereditarius。"},{"era":"LATE LATIN INHEREDITARE","en":"In- 'in, into' plus hereditare gave inhereditare 'to appoint as heir', the form behind the French verb.","cn":"in-「进入」加 hereditare 构成 inhereditare「立为继承人」，也就是法语动词背后的形式。"},{"era":"OLD FRENCH","en":"Old French enheriter reached English in the fourteenth century as inherit; the first legal citations are not precisely dated.","cn":"古法语 enheriter 在 14 世纪以 inherit 进入英语；最早的法律书证年代并不精确。"},{"era":"LEGAL TO GENERAL","en":"The legal sense 'receive property' came first; 'receive a trait' followed in the nineteenth century, and the computing sense in the twentieth.","cn":"「接收财产」的法律义最先出现；「接收性状」在 19 世纪跟上，计算机义则在 20 世纪出现。"},{"era":"UNCERTAIN DETAILS","en":"The pre-Latin origin of heres is uncertain, and the date at which the biological sense became standard is approximate.","cn":"heres 在拉丁语之前的来源不确定，生物学义成为标准用法的年代也只是约数。"}]},"similar":{"note":{"en":"Group one separates inherit from look-alikes with a different root; group two separates it from verbs of acquiring and succeeding.","cn":"第一组把 inherit 与词根不同的形近词分开；第二组把它与「取得」「继任」类动词区分。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"inhere","ipa":"/ɪnˈhɪə/","tag":"different root","definition":"From inhaerere 'to stick in', not heres: to exist as a permanent quality. It looks close but shares no root with inherit.","definitionCN":"来自 inhaerere「黏附于内」，并非 heres：指作为固有性质而存在。看似相近，但与 inherit 并无同根关系。"},{"word":"inheritance","ipa":"/ɪnˈherɪtəns/","tag":"same family, the thing","definition":"The noun for what is received; inherit is the act of receiving it.","definitionCN":"指所收之物的名词；inherit 是接收的动作。"},{"word":"inheritor","ipa":"/ɪnˈherɪtə/","tag":"same family, the person","definition":"The person who receives; the verb and the agent noun differ only in grammatical role.","definitionCN":"指接收的人；动词与施事名词只差语法角色。"},{"word":"hereditary","ipa":"/hɪˈredɪtəri/","tag":"same root, the adjective","definition":"The adjective describing what is transmitted by inheritance, especially in law and biology.","definitionCN":"描述经继承传递之物的形容词，尤用于法律与生物学。"}]},{"heading":"NEAR MEANING","entries":[{"word":"succeed","ipa":"/səˈsiːd/","tag":"take a position after another","definition":"To take over an office or throne; it stresses the position rather than the property.","definitionCN":"指接任职位或王位；强调职位而非财产。"},{"word":"acquire","ipa":"/əˈkwaɪə/","tag":"get by effort or purchase","definition":"To obtain something actively; inherit is passive, coming by law or death.","definitionCN":"指主动取得；inherit 是被动的，因法律或死亡而到来。"},{"word":"receive","ipa":"/rɪˈsiːv/","tag":"general taking in","definition":"The broad verb for getting what is given or sent; it lacks the legal and generational frame.","definitionCN":"表示收到所给或所寄之物的宽泛动词；缺少法律与代际框架。"},{"word":"assume","ipa":"/əˈsjuːm/","tag":"take on a role or burden","definition":"To take up a duty or role, often without legal succession.","definitionCN":"指承担职责或角色，常不涉及法定继承。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"in- 'into' + heres 'heir': to enter the heir's place.","cn":"in-「进入」+ heres「继承人」：走进继承人的位置。"},{"en":"The family runs inherit, inheritance, inheritor, inheritable, hereditary and heredity.","cn":"同族词包括 inherit、inheritance、inheritor、inheritable、hereditary 与 heredity。"},{"en":"Biology fixes inherit a trait; monarchy fixes inherit the throne.","cn":"生物学固定搭配「遗传性状」；君主制固定搭配「继承王位」。"},{"en":"A successor can inherit a problem as easily as a fortune.","cn":"继任者接手一个难题，和接手一笔财富一样容易。"},{"en":"Subclasses inherit methods from their superclass.","cn":"子类从超类继承方法。"}],"abstract":[{"en":"Picture a coat that fits you because it was cut for someone else.","cn":"想象一件外套正好合身，因为它是照别人的尺寸裁的。"},{"en":"Picture a language arriving with no vocabulary list.","cn":"想象一门语言到来时没有附词汇表。"},{"en":"Picture a team's problems waiting at the desk before you sit down.","cn":"想象团队的问题在你坐下之前就等在桌边。"}]},"examples":[{"en":"The sisters inherited the shop and ran it together.","cn":"姐妹俩继承了这家店，一起经营。"},{"en":"Some disorders are inherited in a dominant pattern.","cn":"有些疾病以显性模式遗传。"},{"en":"The new director inherited a budget already spent.","cn":"新主任接手了一份已经花完的预算。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"in（进入）+ herit（继承人）——进入继承人的身份 → 继承；继承的不只是财物，也可能是债务和问题。","word":"inherit"},"root":"拉丁 inhereditare「立为继承人」= in-（进入）+ heres（hered-）「继承人」；经古法语 enheriter 进入英语；heres 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one entry into another's place: property, genes, character, title, someone else's problems, a tradition, a parent class and finally a name.","cn":"八个义项沿「走进他人位置」这一动作展开：财产、基因、性格、头衔、别人的难题、传统、父类，最后是名字。"},"semanticMap":{"core":{"en":"CORE IMAGE: a young hand taking an old key that still carries the previous owner's tag.","cn":"核心意象：一只年轻的手接过旧钥匙，钥匙上还挂着前任主人的标签。"},"chain":["ENTER A PLACE","RECEIVE AT DEATH","TRAIT FROM PARENTS","QUALITY FROM FAMILY","TAKE OVER A SITUATION","CODE FROM A PARENT CLASS"],"branches":[{"senses":"S1 · S8","en":"WHAT IS HANDED OVER: an estate, a right, a name or an identity.","cn":"被交出的东西：产业、权利、名字或身份。"},{"senses":"S2 · S3","en":"BODY AND CHARACTER: genes pass down, and so do habits that look like genes.","cn":"身体与性格：基因传下去，看似基因的习惯也传下去。"},{"senses":"S4 · S6","en":"OFFICE AND TRADITION: thrones and languages both pass to a successor.","cn":"职位与传统：王位与语言都传给后继者。"},{"senses":"S5","en":"SITUATION: the successor receives the problems that come with the post.","cn":"局面：继任者接收随职位而来的问题。"},{"senses":"S7","en":"COMPUTING: a child class enters the relation its parent defines.","cn":"计算机：子类进入父类所定义的关系。"}]},"affixes":{"intro":{"en":"Inherit is a Latin verb made of a prefix and the hered- stem, and the same pieces build the whole legal and biological family.","cn":"inherit 是由前缀与 hered- 词干构成的拉丁动词，这些成分构成整个法律与生物词族。"},"latinIntro":{"en":"Latin heres (hered-) gives hereditare, inhereditare, inherit, inheritance and heredity; in- adds entry into a position.","cn":"拉丁 heres（hered-）衍生 hereditare、inhereditare、inherit、inheritance 与 heredity；in- 增添「进入某一位置」的意思。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'in, into')","meaning":"in; into","meaningCN":"进入；在内","example":"The prefix puts the receiver inside the heir's place.","exampleCN":"这个前缀把接收者放进继承人的位置。"},{"word":"heres","structure":"heres, heredis (Latin noun, third declension)","meaning":"heir","meaningCN":"继承人","example":"The stem names the person who receives.","exampleCN":"这个词干命名接收者。"},{"word":"hereditare","structure":"hereditare (Latin verb, first conjugation)","meaning":"to inherit; to leave as an inheritance","meaningCN":"继承；遗赠","example":"Hereditare turned the heir into an action.","exampleCN":"hereditare 把「继承人」变成动作。"},{"word":"inhereditare","structure":"in- + hereditare (Late Latin verb)","meaning":"to appoint as heir","meaningCN":"立为继承人","example":"The Late Latin verb named the legal act of naming an heir.","exampleCN":"晚期拉丁动词命名指定继承人的法律动作。"},{"word":"inherit","structure":"English verb from Old French enheriter","meaning":"to receive by succession","meaningCN":"继承；承袭","example":"She inherited the house from her aunt.","exampleCN":"她从姑妈那里继承了这所房子。"},{"word":"inheritance","structure":"inherit + -ance (state or result)","meaning":"the estate or the act of receiving it","meaningCN":"遗产；继承","example":"The inheritance was divided among the children.","exampleCN":"遗产在孩子们之间分配。"},{"word":"inheritor","structure":"inherit + -or (one who acts)","meaning":"a person who inherits","meaningCN":"继承人","example":"The inheritor signed the deed.","exampleCN":"继承人在契据上签了字。"},{"word":"inheritable","structure":"inherit + -able (can be)","meaning":"able to be inherited","meaningCN":"可继承的；可遗传的","example":"The trait is inheritable in a simple pattern.","exampleCN":"这一性状以简单模式可遗传。"},{"word":"disinherit","structure":"dis- 'away' + inherit","meaning":"to cut an heir out of a will","meaningCN":"剥夺继承权","example":"The old man disinherited his nephew.","exampleCN":"老人剥夺了侄子的继承权。"},{"word":"hereditary","structure":"hereditarius + -ary (adjective suffix)","meaning":"of inheritance; transmitted by succession","meaningCN":"继承的；世袭的；遗传的","example":"The title was hereditary.","exampleCN":"这个爵位是世袭的。"},{"word":"heredity","structure":"hereditas (Latin noun)","meaning":"the transmission of traits","meaningCN":"遗传","example":"Heredity and environment interact.","exampleCN":"遗传与环境相互作用。"}],"latinEntries":[{"word":"heres","structure":"heres, heredis (m./f., third declension)","meaning":"heir","meaningCN":"继承人"},{"word":"hereditas","structure":"hereditas, hereditatis (f., third declension)","meaning":"inheritance, heirship","meaningCN":"继承；继承权"},{"word":"hereditarius","structure":"hereditarius, hereditária, hereditarium (adj.)","meaning":"of an inheritance","meaningCN":"继承的"},{"word":"inhereditare","structure":"inhereditare, inhereditavi, inhereditatum (verb, first conjugation)","meaning":"to appoint as heir","meaningCN":"立为继承人"}]}},{"word":"hereditary","ipa_uk":"/hɪˈredɪtəri/","ipa_us":"/həˈredɪtəri/","definition_zh":"遗传的；世袭的；继承的","definition_en":"passed from parents to offspring through genes, or transmitted by legal succession from one generation to the next","core_image":"家族相册里，几代人的手形几乎一模一样，连指节的弯度都对得上","scene":"家族相册里，几代人的手形几乎一模一样。A hereditary trait ran through every generation of the family.","sceneCN":"这里 hereditary 指「由上一代经遗传传下来的」（第 1 个义项：经基因传递的）；句意为一种遗传性状贯穿了这个家族的每一代。可辨识物件：相册、放大的手部照片、家谱线、铅笔标记。","pos":[{"tag":"adj.","zh":"遗传的；经基因传递的"},{"tag":"adj.","zh":"世袭的；依法继承的"}],"collocations":[{"phrase":"hereditary disease","zh":"遗传性疾病"},{"phrase":"hereditary trait","zh":"遗传性状"},{"phrase":"hereditary predisposition","zh":"遗传易感性"},{"phrase":"hereditary peer","zh":"世袭贵族"},{"phrase":"hereditary monarchy","zh":"世袭君主制"},{"phrase":"hereditary title","zh":"世袭头衔"}],"forms":[{"label":"比较级（少用）","form":"more hereditary"},{"label":"最高级（少用）","form":"most hereditary"},{"label":"副词","form":"hereditarily"},{"label":"名词（遗传）","form":"heredity"},{"label":"名词（继承性，罕见）","form":"hereditariness"}],"derivatives":[{"word":"heredity","pos":"n.","zh":"遗传"},{"word":"hereditarily","pos":"adv.","zh":"以遗传方式；世袭地"},{"word":"hereditament","pos":"n.","zh":"可继承的财产（法律用语）"},{"word":"hereditarian","pos":"n./adj.","zh":"遗传论者；遗传论的"}],"senses":[{"no":"01","title":"Passed through genes","titleCN":"经基因传递的","definition":"transmitted from parents to offspring through genetic material","definitionCN":"通过遗传物质由亲代传给子代","example":"Hereditary deafness runs in that family.","exampleCN":"遗传性耳聋在那个家族中代代出现。","why":"The adjective describes a trait whose cause travels in the genes, so it names the route rather than the illness itself.","whyCN":"这个形容词描述病因随基因传递的性状，因此命名的是传递路径，而非疾病本身。"},{"no":"02","title":"Inherited from ancestors","titleCN":"从祖先承接的","definition":"received from an ancestor rather than acquired in one's own lifetime","definitionCN":"从祖先处承接，而非在本人一生中获得","example":"The tendency is partly hereditary.","exampleCN":"这种倾向有一部分是遗传的。","why":"The word can soften a claim: partly hereditary means ancestry contributes without settling the outcome.","whyCN":"这个词可以缓和断言：部分遗传意味着祖先有贡献，但并不决定结果。"},{"no":"03","title":"Transmitted by succession","titleCN":"按世袭传递的","definition":"passed down by legal or customary succession rather than election","definitionCN":"按法律或习俗世袭传递，而非经选举","example":"The duke held a hereditary seat in the old assembly.","exampleCN":"公爵在旧议会中拥有一个世袭席位。","why":"Law uses the same adjective for offices because a seat can pass to an heir just as an estate can.","whyCN":"法律用同一个形容词描述职位，因为席位也能像产业一样传给继承人。"},{"no":"04","title":"Of hereditary monarchy","titleCN":"世袭君主制的","definition":"describing a system in which the head of state succeeds by birth","definitionCN":"描述国家元首按出生顺序继位的制度","example":"The country replaced hereditary rule with elections.","exampleCN":"这个国家用选举取代了世袭统治。","why":"The adjective attaches to institutions, not only to bodies, when rule itself is handed down.","whyCN":"当统治权本身被传下时，这个形容词也附着于制度，而不只是身体。"},{"no":"05","title":"Of hereditary material","titleCN":"遗传物质的","definition":"relating to the material that carries genes from one cell to the next","definitionCN":"与把基因从一代细胞带到下一代细胞的物质相关","example":"Hereditary material is copied into every cell.","exampleCN":"遗传物质被复制进每一个细胞。","why":"In biology the adjective can modify the carrier as well as the trait, which is why hereditary material is a fixed phrase.","whyCN":"在生物学中，这个形容词既能修饰性状，也能修饰载体，因此「遗传物质」成为固定搭配。"},{"no":"06","title":"Of a hereditary predisposition","titleCN":"遗传易感性的","definition":"describing an inherited tendency that raises risk without causing the condition alone","definitionCN":"描述提高风险但并不单独致病的遗传倾向","example":"A hereditary predisposition does not guarantee illness.","exampleCN":"遗传易感性并不保证一定患病。","why":"The word separates inheritance from inevitability: a predisposition is a loaded starting point, not a sentence.","whyCN":"这个词把「遗传」与「必然」分开：易感性是一个有负载的起点，而不是判决。"},{"no":"07","title":"Legally inheritable","titleCN":"法律上可继承的","definition":"able to pass to an heir under the law","definitionCN":"依法可以传给继承人","example":"The estate was hereditary and could not be sold.","exampleCN":"这份产业属于可继承财产，不能出售。","why":"Property law uses the adjective for land and rights that must descend rather than be traded freely.","whyCN":"财产法用这个形容词描述必须下传、不能自由买卖的土地与权利。"},{"no":"08","title":"Carried down from the past","titleCN":"从过去沿袭的（抽象义）","definition":"describing an attitude or conflict handed down so long that it seems inborn","definitionCN":"描述传得太久、仿佛天生的态度或冲突","example":"The two villages were hereditary enemies.","exampleCN":"这两个村子是世代相传的仇敌。","why":"The metaphor treats hostility as an estate: children receive a quarrel they never chose.","whyCN":"这个隐喻把敌意当作产业：孩子们接收了一场他们从未选择的争吵。"}],"etymology":{"intro":{"en":"Hereditary comes from Latin hereditarius 'of an inheritance', from hereditas 'inheritance', from heres (hered-) 'heir'.","cn":"hereditary 来自拉丁 hereditarius「继承的」，再上溯 hereditas「继承」与 heres（hered-）「继承人」。"},"items":[{"era":"LATIN HERES","en":"Heres (genitive heredis) meant 'heir'. Its deeper origin is not established; links to other Indo-European words are hypotheses, and any PIE form is a reconstruction.","cn":"heres（属格 heredis）意为「继承人」。其更深来源未得到确证；与其他印欧语词的联系只是假说，任何原始印欧语形式均属重构。"},{"era":"LATIN HEREDITARIUS","en":"Hereditarius 'of an inheritance' was formed from hereditas; the adjective suffix -arius marks belonging or relation.","cn":"hereditarius「继承的」由 hereditas 构成；形容词后缀 -arius 表示归属或关系。"},{"era":"ENGLISH BORROWING","en":"English took hereditary from Latin or French in the fifteenth or sixteenth century; the exact first date is uncertain.","cn":"英语在 15 或 16 世纪从拉丁语或法语借入 hereditary；确切首见年代不确定。"},{"era":"LEGAL SENSE","en":"The legal sense survives in hereditary titles and hereditary peers, where office passes by birth rather than election.","cn":"法律义残存于世袭头衔与世袭贵族，其职位按出生而非选举传递。"},{"era":"BIOLOGICAL SENSE","en":"The biological sense developed in the nineteenth century, when heredity became a research subject and traits were traced through families.","cn":"生物学义在 19 世纪发展起来，当时遗传成为研究课题，性状被沿家族追踪。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper root): heres has no established pre-Latin etymology, and the first English date is approximate.","cn":"来源不确定（更深词根）：heres 没有已确立的拉丁语之前词源，英语首见年代也只是约数。"}]},"similar":{"note":{"en":"Group one holds forms of the same hered- family that differ in grammar or nuance; group two holds adjectives that also describe what is present from birth or runs in families.","cn":"第一组是同出 hered- 词族、但语法角色或侧重不同的词；第二组是同样描述「出生即有」或「家族中常见」的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"heredity","ipa":"/həˈredəti/","tag":"same root, the noun","definition":"The process or system of transmission; hereditary is the adjective describing what is transmitted.","definitionCN":"指传递过程或系统；hereditary 是描述被传递之物的形容词。"},{"word":"heritable","ipa":"/ˈherɪtəbl/","tag":"same root, a capability","definition":"Able to be inherited, often used of traits or property; hereditary describes the actual transmission or legal status.","definitionCN":"指能够被继承，常用于性状或财产；hereditary 描述实际的传递或法律地位。"},{"word":"hereditament","ipa":"/hɪˈredɪtəmənt/","tag":"same root, legal property","definition":"A legal term for inheritable property; it is a noun of things, not a trait.","definitionCN":"指可继承财产的法律术语；它是事物名词，不是性状。"},{"word":"hereditarily","ipa":"/hɪˈredɪtərəli/","tag":"same root, the adverb","definition":"The adverb form; it describes how something is transmitted rather than what it is.","definitionCN":"副词形式；描述传递方式，而非事物本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"inherited","ipa":"/ɪnˈherɪtɪd/","tag":"the everyday participle","definition":"The ordinary participle from inherit; hereditary is the fixed adjective, especially in biology and law.","definitionCN":"inherit 的普通分词；hereditary 是固定形容词，尤用于生物学与法律。"},{"word":"congenital","ipa":"/kənˈdʒenɪtl/","tag":"present at birth, not always genetic","definition":"Present at birth; a congenital condition may arise during development and need not be hereditary.","definitionCN":"指出生时即存在；先天状况可能在发育中形成，未必是遗传的。"},{"word":"familial","ipa":"/fəˈmɪliəl/","tag":"runs in families","definition":"Occurring in a family more often than chance; familial does not prove a genetic cause.","definitionCN":"指在家族中发生率高于偶然；familial 并不证明存在遗传原因。"},{"word":"genetic","ipa":"/dʒəˈnetɪk/","tag":"relating to genes","definition":"The broad modern adjective; hereditary emphasises transmission from ancestors, genetic emphasises the genes themselves.","definitionCN":"宽泛的现代形容词；hereditary 强调从祖先传递，genetic 强调基因本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"heres 'heir' + -ary: belonging to an inheritance.","cn":"heres「继承人」+ -ary：属于继承的。"},{"en":"The family runs hereditary, heredity, hereditarily and hereditament.","cn":"同族词包括 hereditary、heredity、hereditarily 与 hereditament。"},{"en":"Law fixes hereditary peer and hereditary title; biology fixes hereditary disease.","cn":"法律固定搭配世袭贵族、世袭头衔；生物学固定搭配遗传性疾病。"},{"en":"Hereditary peer describes a seat, not a gene.","cn":"世袭贵族描述的是席位，不是基因。"},{"en":"A hereditary predisposition raises risk without deciding the outcome.","cn":"遗传易感性提高风险，却不决定结果。"}],"abstract":[{"en":"Picture a seal stamped on every generation of a document.","cn":"想象每一代文件上都盖着同一枚印章。"},{"en":"Picture a tune learned before birth and never questioned.","cn":"想象一支在出生前就学会、从不被质疑的曲子。"},{"en":"Picture a title that comes with the furniture, not with a vote.","cn":"想象一个头衔随家具而来，而不是随选票而来。"}]},"examples":[{"en":"The condition is hereditary, though not everyone who carries the gene falls ill.","cn":"这种病是遗传的，但并非每个携带该基因的人都会发病。"},{"en":"Hereditary peers lost their voting rights in the reform.","cn":"世袭贵族在改革中失去了投票权。"},{"en":"The museum refused to sell the hereditary collection.","cn":"博物馆拒绝出售这批世袭收藏。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"hered（继承人）+ itary（形容词尾）——与继承人相关的 → 世袭的、遗传的。","word":"hereditary"},"root":"拉丁 hereditarius「继承的」← hereditas「继承」← heres（hered-）「继承人」；heres 更深来源不确定。","sensesIntro":{"en":"Eight senses follow a stamp that keeps reappearing: in genes, in ancestry, in offices, in monarchy, in cellular material, in risk, in property law and finally in inherited hostility.","cn":"八个义项沿一枚反复出现的印章展开：出现在基因、祖先、职位、君主制、细胞物质、风险、财产法，最后出现在沿袭的敌意中。"},"semanticMap":{"core":{"en":"CORE IMAGE: the same hand shape appearing in photograph after photograph.","cn":"核心意象：同一手形在一张又一张照片中反复出现。"},"chain":["FROM ANCESTOR","THROUGH GENES","BY SUCCESSION","BY LAW","AS PREDISPOSITION","DOWN THE YEARS"],"branches":[{"senses":"S1 · S2","en":"GENETIC AND ANCESTRAL: a trait travels through genes and is received from ancestors.","cn":"遗传与祖先：性状经基因传递，并从祖先处承接。"},{"senses":"S5 · S6","en":"MATERIAL AND RISK: the carrier itself, and an inherited tendency that only raises risk.","cn":"物质与风险：载体本身，以及只提高风险的遗传倾向。"},{"senses":"S3 · S4","en":"OFFICE AND RULE: seats and crowns pass by birth rather than election.","cn":"职位与统治：席位与王冠按出生而非选举传递。"},{"senses":"S7","en":"PROPERTY LAW: land and rights that must descend to heirs.","cn":"财产法：必须下传给继承人的土地与权利。"},{"senses":"S8","en":"INHERITED HOSTILITY: an old quarrel arrives like an estate.","cn":"沿袭的敌意：旧日争吵像产业一样被接收。"}]},"affixes":{"intro":{"en":"Hereditary is an adjective built on the Latin hered- stem plus a suffix, and the same stem builds a legal and biological family.","cn":"hereditary 是由拉丁 hered- 词干加后缀构成的形容词，同一词干还构成法律与生物词族。"},"latinIntro":{"en":"Latin heres (hered-) gives hereditas, hereditarius, hereditary, heredity and inherit; -arius marks belonging.","cn":"拉丁 heres（hered-）衍生 hereditas、hereditarius、hereditary、heredity 与 inherit；-arius 标记归属关系。"},"items":[{"word":"heres","structure":"heres, heredis (Latin noun, third declension)","meaning":"heir","meaningCN":"继承人","example":"The stem names the person who receives.","exampleCN":"这个词干命名接收者。"},{"word":"hereditas","structure":"hereditas (Latin noun, third declension)","meaning":"inheritance, heirship","meaningCN":"继承；继承权","example":"Hereditas named the estate and the relation together.","exampleCN":"hereditas 同时命名产业与关系。"},{"word":"hereditarius","structure":"hereditarius (Latin adjective)","meaning":"of an inheritance","meaningCN":"继承的","example":"The adjective added -arius to the stem.","exampleCN":"这个形容词在词干后加 -arius。"},{"word":"-ary","structure":"-ary (English adjective suffix from Latin -arius)","meaning":"belonging to; connected with","meaningCN":"属于；与……有关","example":"The suffix turns the stem into a describing word.","exampleCN":"这个后缀把词干变成描述词。"},{"word":"hereditary","structure":"hereditarius + -ary, through French","meaning":"transmitted by inheritance","meaningCN":"遗传的；世袭的","example":"The title was hereditary.","exampleCN":"这个爵位是世袭的。"},{"word":"heredity","structure":"hereditas (Latin noun)","meaning":"the transmission of traits","meaningCN":"遗传","example":"Heredity and environment interact.","exampleCN":"遗传与环境相互作用。"},{"word":"hereditarily","structure":"hereditary + -ly (adverb suffix)","meaning":"by inheritance","meaningCN":"以遗传方式；世袭地","example":"The trait is hereditarily transmitted.","exampleCN":"这一性状以遗传方式传递。"},{"word":"inherit","structure":"in- + heres via Late Latin","meaning":"to receive by succession","meaningCN":"继承","example":"She inherited the house.","exampleCN":"她继承了这所房子。"},{"word":"inheritance","structure":"inherit + -ance","meaning":"the estate or the act","meaningCN":"遗产；继承","example":"The inheritance was divided.","exampleCN":"遗产被分配。"},{"word":"inheritable","structure":"inherit + -able","meaning":"able to be inherited","meaningCN":"可继承的","example":"The right is inheritable.","exampleCN":"这项权利可继承。"},{"word":"hereditament","structure":"hereditamentum (Medieval Latin)","meaning":"inheritable property","meaningCN":"可继承财产","example":"The deed lists every hereditament.","exampleCN":"契据列明了每一项可继承财产。"},{"word":"hereditarian","structure":"heredity + -arian (person or doctrine)","meaning":"one who stresses heredity","meaningCN":"遗传论者","example":"The debate drew both hereditarians and environmentalists.","exampleCN":"这场争论吸引了遗传论者与环境论者。"}],"latinEntries":[{"word":"heres","structure":"heres, heredis (m./f., third declension)","meaning":"heir","meaningCN":"继承人"},{"word":"hereditas","structure":"hereditas, hereditatis (f., third declension)","meaning":"inheritance, heirship","meaningCN":"继承；继承权"},{"word":"hereditarius","structure":"hereditarius, hereditária, hereditarium (adj.)","meaning":"of an inheritance","meaningCN":"继承的"},{"word":"hereditamentum","structure":"hereditamentum, hereditamenti (n., second declension)","meaning":"inheritable property","meaningCN":"可继承财产"}]}},{"word":"heredity","ipa_uk":"/hɪˈredəti/","ipa_us":"/həˈredəti/","definition_zh":"遗传；遗传性；（旧义）继承","definition_en":"the transmission of traits from parents to offspring, or the set of inherited characteristics of an organism","core_image":"同一对父母养大的子女，身高与性格却各有差别，差别像从看不见的账本里带出来的","scene":"同一对父母养大的子女，身高与性格却各有差别。Researchers separate the effects of heredity from those of upbringing.","sceneCN":"这里 heredity 指「亲代把性状传给子代的生物过程」（第 1 个义项：性状的遗传传递）；句意为研究者把遗传的影响与养育的影响分开。可辨识物件：并排的身高尺、两张性格记录表、家谱图、双栏表格。","pos":[{"tag":"n.","zh":"遗传；遗传性"},{"tag":"n.","zh":"（旧义）继承；继承权"}],"collocations":[{"phrase":"heredity and environment","zh":"遗传与环境"},{"phrase":"laws of heredity","zh":"遗传规律"},{"phrase":"the study of heredity","zh":"遗传研究"},{"phrase":"human heredity","zh":"人类遗传"},{"phrase":"heredity versus upbringing","zh":"遗传与教养"}],"forms":[{"label":"复数（少用）","form":"heredities"},{"label":"所有格","form":"heredity's"},{"label":"形容词","form":"hereditary"}],"derivatives":[{"word":"hereditary","pos":"adj.","zh":"遗传的；世袭的"},{"word":"hereditarily","pos":"adv.","zh":"以遗传方式"},{"word":"hereditarian","pos":"n./adj.","zh":"遗传论者；遗传论的"},{"word":"inherit","pos":"v.","zh":"继承；遗传"}],"senses":[{"no":"01","title":"Transmission of traits","titleCN":"性状的遗传传递","definition":"the passing of characteristics from parents to offspring","definitionCN":"特征由亲代传给子代","example":"Heredity explains why siblings resemble their parents.","exampleCN":"遗传解释了为什么兄弟姐妹像他们的父母。","why":"The word names the process itself, not the genes that carry it, which is why it pairs naturally with environment.","whyCN":"这个词命名过程本身，而非承载它的基因，因此天然与「环境」配对。"},{"no":"02","title":"An organism's inherited constitution","titleCN":"生物体的遗传组成","definition":"the total set of inherited characteristics of an organism","definitionCN":"一个生物体所继承的全部特征","example":"Heredity and environment interact in development.","exampleCN":"遗传与环境在发育中相互作用。","why":"The process sense and the constitution sense share a form: what is transmitted becomes what an organism carries.","whyCN":"过程义与组成义共用一词形：被传下的东西成为生物体所携带的东西。"},{"no":"03","title":"The study of inheritance","titleCN":"对遗传的研究","definition":"the field or subject concerned with transmission of traits","definitionCN":"研究性状传递的领域或学科","example":"Heredity was studied long before genes were named.","exampleCN":"早在基因被命名之前，人们就在研究遗传。","why":"The name of the process also names the subject that studies it, so heredity can stand for a field of inquiry.","whyCN":"过程之名也命名研究它的学科，因此 heredity 可以指一个研究领域。"},{"no":"04","title":"Laws of heredity","titleCN":"遗传规律","definition":"the regular patterns by which traits appear in later generations","definitionCN":"性状在后代中出现的规律模式","example":"Mendel's laws of heredity describe the ratios of traits.","exampleCN":"孟德尔的遗传规律描述了性状的比例。","why":"Once patterns were counted, heredity could be spoken of as having laws rather than merely effects.","whyCN":"一旦模式可以被计数，遗传就可以被说成有规律，而不只是有效应。"},{"no":"05","title":"Heredity versus environment","titleCN":"遗传与环境之争","definition":"the relative contribution of inherited and environmental factors","definitionCN":"遗传因素与环境因素的相对贡献","example":"The debate over heredity and environment has softened.","exampleCN":"关于遗传与环境的争论已经缓和。","why":"The word became a pole in a debate, so heredity often appears opposite environment rather than alone.","whyCN":"这个词成了争论中的一极，因此 heredity 常与 environment 相对出现，而非单独使用。"},{"no":"06","title":"Heredity as a biological force","titleCN":"作为生物力量的遗传","definition":"the influence of inherited factors on development and behaviour","definitionCN":"遗传因素对发育与行为的影响","example":"Heredity sets limits that nutrition can only partly shift.","exampleCN":"遗传设定了界限，营养只能部分改变。","why":"When treated as a force, heredity explains the range of possible development rather than a single fixed result.","whyCN":"当被当作一种力量时，遗传解释的是发育的可能范围，而非单一固定结果。"},{"no":"07","title":"Heredity in breeding","titleCN":"育种中的遗传","definition":"the transmission that breeders rely on when fixing traits","definitionCN":"育种者固定性状时所依赖的传递","example":"Heredity determines which traits a breeder can fix.","exampleCN":"遗传决定育种者能固定哪些性状。","why":"Breeders work with heredity as a practical constraint: some traits can be fixed, others cannot.","whyCN":"育种者把遗传当作实际限制来工作：有些性状可以固定，有些不能。"},{"no":"08","title":"Archaic legal inheritance","titleCN":"旧时的法律继承义","definition":"the old sense of inheriting property or a right","definitionCN":"继承财产或权利的旧义","example":"In older legal writing, heredity meant the right to inherit.","exampleCN":"在较早的法律文本中，heredity 指继承权。","why":"The legal sense is the oldest layer of the word, preserved in older statutes rather than in modern biology.","whyCN":"法律义是这个词最古老的层次，保存在较早的法条中，而非现代生物学中。"}],"etymology":{"intro":{"en":"Heredity was borrowed from Latin hereditas 'inheritance, heirship', from heres (hered-) 'heir'.","cn":"heredity 直接借自拉丁 hereditas「继承、继承权」，其词干为 heres（hered-）「继承人」。"},"items":[{"era":"LATIN HERES","en":"Heres (genitive heredis) meant 'heir'. Its deeper origin is not established; related forms in other Indo-European languages are hypotheses, and any PIE form is a reconstruction.","cn":"heres（属格 heredis）意为「继承人」。其更深来源未得到确证；其他印欧语中的相关形式只是假说，任何原始印欧语形式均属重构。"},{"era":"LATIN HEREDITAS","en":"Hereditas meant 'inheritance, heirship'; English heredity was borrowed directly from this Latin noun rather than through French.","cn":"hereditas 意为「继承、继承权」；英语 heredity 直接借自这个拉丁名词，而非经法语。"},{"era":"EARLY ENGLISH","en":"The word appears in English by the sixteenth century with the legal sense 'inheritance'; the exact first citation is uncertain.","cn":"这个词在 16 世纪已以「继承」的法律义出现在英语中；确切的最早书证不确定。"},{"era":"BIOLOGICAL SENSE","en":"In the nineteenth century heredity was reshaped into the biological term for the transmission of traits, as breeding and cell theory advanced.","cn":"19 世纪，随着育种与细胞理论进展，heredity 被重塑为性状传递的生物学术语。"},{"era":"MODERN USE","en":"Twentieth-century genetics narrowed heredity to the transmission itself, distinct from the genes that carry it.","cn":"20 世纪的遗传学把 heredity 收窄为传递过程本身，与承载它的基因区分开。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper root and first date): the pre-Latin origin of heres is unsettled, and the shift from legal to biological use is not sharply dated.","cn":"来源不确定（更深词根与首见年代）：heres 的拉丁语之前来源未有定论，从法律义到生物学义的转变也没有精确年代。"}]},"similar":{"note":{"en":"Group one separates heredity from same-root words with different grammar; group two separates it from the words for inheritance, lineage and the science of genes.","cn":"第一组把 heredity 与同根但语法角色不同的词分开；第二组把它与继承、世系、基因科学相关词区分。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hereditary","ipa":"/hɪˈredɪtəri/","tag":"same root, the adjective","definition":"The adjective describing what is transmitted; heredity is the process or constitution itself.","definitionCN":"描述被传递之物的形容词；heredity 是过程或组成本身。"},{"word":"heritage","ipa":"/ˈherɪtɪdʒ/","tag":"same root, handed-down things","definition":"What is handed down, especially culture or family property; it is not the biological process.","definitionCN":"指被传下的东西，尤其是文化或家族财产；不是生物过程。"},{"word":"heritable","ipa":"/ˈherɪtəbl/","tag":"same root, a capability","definition":"Able to be inherited; the word describes a possibility, while heredity names the actual transmission.","definitionCN":"指可被继承；描述可能性，而 heredity 命名实际传递。"},{"word":"hereditarian","ipa":"/hɪˌredɪˈteəriən/","tag":"same root, a stance","definition":"A person or doctrine stressing heredity as a cause of differences; it belongs to debate rather than biology alone.","definitionCN":"强调遗传是差异原因的人或学说；属于争论语境，而非单纯生物学。"}]},{"heading":"NEAR MEANING","entries":[{"word":"inheritance","ipa":"/ɪnˈherɪtəns/","tag":"the broader word","definition":"A broader word covering legal property and biological transmission; heredity is the biological process itself.","definitionCN":"较宽泛的词，涵盖法定财产与生物传递；heredity 是生物过程本身。"},{"word":"genetics","ipa":"/dʒəˈnetɪks/","tag":"the science","definition":"The modern science of genes; heredity names the transmission that genetics explains.","definitionCN":"研究基因的现代科学；heredity 命名遗传学所要解释的传递。"},{"word":"descent","ipa":"/dɪˈsent/","tag":"the line of ancestry","definition":"Ancestry or lineage, especially as a line of descent; heredity is the mechanism, descent is the line.","definitionCN":"指血统或世系，尤指一条下传的线；heredity 是机制，descent 是那条线。"},{"word":"transmission","ipa":"/trænsˈmɪʃən/","tag":"the general act of passing on","definition":"A neutral term for passing anything from one generation to the next, biological or not.","definitionCN":"中性词，指把任何东西传给下一代，不论是否生物性的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"heres 'heir' + -ity: the state of being inherited.","cn":"heres「继承人」+ -ity：被继承的状态。"},{"en":"The family runs heredity, hereditary, hereditarily and hereditarian.","cn":"同族词包括 heredity、hereditary、hereditarily 与 hereditarian。"},{"en":"The fixed pair is heredity and environment.","cn":"固定搭配是遗传与环境。"},{"en":"Laws of heredity were counted before genes were named.","cn":"在基因被命名之前，遗传规律就已被计数。"},{"en":"Modern genetics separates heredity from the genes that carry it.","cn":"现代遗传学把遗传过程与承载它的基因分开。"}],"abstract":[{"en":"Picture an invisible ledger that each child receives with a few entries already filled in.","cn":"想象每个孩子都收到一本看不见的账本，上面已写好几笔。"},{"en":"Picture two seeds from one pod landing in different soils.","cn":"想象同一豆荚里的两粒种子落在不同的土里。"},{"en":"Picture a hand of cards dealt before anyone chooses how to play.","cn":"想象一手牌在任何人决定怎么打之前就已发好。"}]},"examples":[{"en":"Heredity alone does not explain the difference between the twins.","cn":"单靠遗传解释不了这对双胞胎的差异。"},{"en":"Breeders rely on heredity when they select for a fixed coat colour.","cn":"育种者选育固定毛色时依赖遗传。"},{"en":"The old statute used heredity in the sense of a right to inherit.","cn":"旧法规用 heredity 指继承权。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"hered（继承人）+ ity（名词尾）——继承人接到的东西 → 遗传；旧义才是「继承」。","word":"heredity"},"root":"拉丁 hereditas「继承、继承权」← heres（hered-）「继承人」；heres 更深来源不确定。","sensesIntro":{"en":"Eight senses follow a current running through generations: the process, the constitution it produces, the study of it, its laws, its debate with environment, its force, its use in breeding and its old legal sense.","cn":"八个义项沿一股穿越世代的电流展开：传递过程、由此形成的组成、对它的研究、它的规律、它与环境的争论、它的力量、它在育种中的用途，以及旧时的法律义。"},"semanticMap":{"core":{"en":"CORE IMAGE: an invisible ledger handed to each child with a few entries already filled in.","cn":"核心意象：每个孩子都收到一本看不见的账本，上面已写好几笔。"},"chain":["PASS DOWN","TRAIT TRANSMISSION","INHERITED CONSTITUTION","PATTERNS AND LAWS","VERSUS ENVIRONMENT","OLD LEGAL SENSE"],"branches":[{"senses":"S1 · S6","en":"PROCESS AND FORCE: transmission itself, and the influence it exerts on development.","cn":"过程与力量：传递本身，以及它对发育施加的影响。"},{"senses":"S2 · S7","en":"CONSTITUTION AND BREEDING: what an organism carries, and what a breeder can fix.","cn":"组成与育种：生物体携带什么，育种者能固定什么。"},{"senses":"S3","en":"STUDY: the field that examines transmission before and after genes were named.","cn":"研究：在基因被命名前后考察传递的领域。"},{"senses":"S4 · S5","en":"LAWS AND DEBATE: counted ratios, and the argument with environment.","cn":"规律与争论：可计数的比例，以及与环境的论战。"},{"senses":"S8","en":"OLD LAW: the archaic sense of a right to inherit property.","cn":"旧法律：继承财产之权利的古老义。"}]},"affixes":{"intro":{"en":"Heredity is a Latin noun built on the hered- stem; the same stem forms the legal and biological words around it.","cn":"heredity 是建立在 hered- 词干上的拉丁名词；同一词干构成周围的法律与生物词。"},"latinIntro":{"en":"Latin heres (hered-) gives hereditas, hereditarius, heredity, hereditary and inherit; no prefix is involved in heredity itself.","cn":"拉丁 heres（hered-）衍生 hereditas、hereditarius、heredity、hereditary 与 inherit；heredity 本身不含前缀。"},"items":[{"word":"heres","structure":"heres, heredis (Latin noun, third declension)","meaning":"heir","meaningCN":"继承人","example":"The stem names the person who receives.","exampleCN":"这个词干命名接收者。"},{"word":"hereditas","structure":"hereditas, hereditatis (Latin noun, third declension)","meaning":"inheritance, heirship","meaningCN":"继承；继承权","example":"Hereditas is the direct source of heredity.","exampleCN":"hereditas 是 heredity 的直接来源。"},{"word":"hereditarius","structure":"hereditarius (Latin adjective)","meaning":"of an inheritance","meaningCN":"继承的","example":"The adjective supplied hereditary.","exampleCN":"这个形容词提供了 hereditary。"},{"word":"-ity","structure":"-ity (English noun suffix from Latin -itas)","meaning":"state or quality","meaningCN":"状态；性质","example":"The suffix turns the stem into a noun of state.","exampleCN":"这个后缀把词干变成状态名词。"},{"word":"heredity","structure":"hereditas, borrowed directly","meaning":"the transmission of traits","meaningCN":"遗传","example":"Heredity and environment interact.","exampleCN":"遗传与环境相互作用。"},{"word":"hereditary","structure":"hereditarius + -ary","meaning":"transmitted by inheritance","meaningCN":"遗传的；世袭的","example":"The condition is hereditary.","exampleCN":"这种病是遗传的。"},{"word":"hereditarily","structure":"hereditary + -ly","meaning":"by inheritance","meaningCN":"以遗传方式","example":"The trait is hereditarily transmitted.","exampleCN":"这一性状以遗传方式传递。"},{"word":"inherit","structure":"in- + heres via Late Latin","meaning":"to receive by succession","meaningCN":"继承","example":"She inherited the house.","exampleCN":"她继承了这所房子。"},{"word":"inheritance","structure":"inherit + -ance","meaning":"the estate or the act","meaningCN":"遗产；继承","example":"The inheritance was divided.","exampleCN":"遗产被分配。"},{"word":"inheritor","structure":"inherit + -or","meaning":"a person who inherits","meaningCN":"继承人","example":"The inheritor signed the deed.","exampleCN":"继承人在契据上签了字。"},{"word":"heritable","structure":"inherit + -able","meaning":"able to be inherited","meaningCN":"可继承的；可遗传的","example":"The right is heritable.","exampleCN":"这项权利可继承。"}],"latinEntries":[{"word":"heres","structure":"heres, heredis (m./f., third declension)","meaning":"heir","meaningCN":"继承人"},{"word":"hereditas","structure":"hereditas, hereditatis (f., third declension)","meaning":"inheritance, heirship","meaningCN":"继承；继承权"},{"word":"hereditarius","structure":"hereditarius, hereditária, hereditarium (adj.)","meaning":"of an inheritance","meaningCN":"继承的"},{"word":"hereditare","structure":"hereditare, hereditavi, hereditatum (verb, first conjugation)","meaning":"to inherit, leave as an inheritance","meaningCN":"继承；遗赠"}]}},{"word":"genetics","ipa_uk":"/dʒɪˈnetɪks/","ipa_us":"/dʒəˈnetɪks/","definition_zh":"遗传学；（某生物或群体的）遗传组成","definition_en":"the branch of biology that studies heredity and genes, or the genetic makeup of an organism or group","core_image":"一块白板写满杂交组合与比例，旁边摆着一排标了代号的育苗盘","scene":"实验室的白板上写满杂交组合，研究生在计算下一代的性状比例。Modern genetics explains how traits pass from parents to offspring.","sceneCN":"这里 genetics 指「研究遗传与基因的生物学科」（第 1 个义项：遗传学）；句意为现代遗传学解释了性状如何由亲代传给子代。可辨识物件：白板、粉笔、杂交组合表、育苗盘、计算器。","pos":[{"tag":"n.","zh":"遗传学（作单数）"},{"tag":"n.","zh":"遗传组成；遗传特征（作复数）"}],"collocations":[{"phrase":"molecular genetics","zh":"分子遗传学"},{"phrase":"population genetics","zh":"群体遗传学"},{"phrase":"medical genetics","zh":"医学遗传学"},{"phrase":"the genetics of","zh":"……的遗传组成"},{"phrase":"genetics research","zh":"遗传学研究"},{"phrase":"human genetics","zh":"人类遗传学"}],"forms":[{"label":"单数（学科名）","form":"genetics"},{"label":"复数（学科名，通常作单数）","form":"genetics"},{"label":"名词（遗传学家）","form":"geneticist"}],"derivatives":[{"word":"genetic","pos":"adj.","zh":"遗传的；基因的"},{"word":"genetically","pos":"adv.","zh":"遗传上；基因上"},{"word":"geneticist","pos":"n.","zh":"遗传学家"},{"word":"genomics","pos":"n.","zh":"基因组学"}],"senses":[{"no":"01","title":"The science of heredity","titleCN":"研究遗传的学科","definition":"the branch of biology concerned with genes, heredity and variation","definitionCN":"研究基因、遗传与变异的生物学分支","example":"Modern genetics explains how traits pass from parents to offspring.","exampleCN":"现代遗传学解释了性状如何由亲代传给子代。","why":"The name was coined for a discipline, so genetics takes a singular verb even though it ends in -s.","whyCN":"这个名称是为学科而造的，因此尽管以 -s 结尾，genetics 仍接单数动词。"},{"no":"02","title":"The genetic makeup of an organism","titleCN":"某生物的遗传组成","definition":"the total genetic constitution of an organism or group","definitionCN":"一个生物或群体的全部遗传构成","example":"The genetics of this population differ from those of the mainland.","exampleCN":"这个群体的遗传组成与大陆群体不同。","why":"Because the field studies variation, its name was transferred to the variation itself, especially in population studies.","whyCN":"由于该领域研究变异，其名称被转用到变异本身，尤其在群体研究中。"},{"no":"03","title":"A branch or subfield","titleCN":"遗传学的分支","definition":"a specialized division of the science, such as medical or molecular genetics","definitionCN":"该学科的一个专门分支，如医学遗传学或分子遗传学","example":"Medical genetics now guides many cancer treatments.","exampleCN":"医学遗传学如今指导许多癌症治疗。","why":"Compound names such as medical genetics treat the word as a countable field, so one can speak of several genetics.","whyCN":"医学遗传学这类复合名称把该词当作可数的领域，因此可以说有多个遗传学分支。"},{"no":"04","title":"Molecular genetics","titleCN":"分子遗传学","definition":"the study of how genetic material is copied, expressed and repaired at the molecular level","definitionCN":"在分子层面研究遗传物质如何复制、表达与修复","example":"Molecular genetics studies how sequences are copied and repaired.","exampleCN":"分子遗传学研究序列如何被复制与修复。","why":"When the focus moves to molecules, the word pairs with an adjective that names the level rather than the organism.","whyCN":"当焦点转向分子，这个词便与标明层次的形容词搭配，而非与生物体搭配。"},{"no":"05","title":"Population genetics","titleCN":"群体遗传学","definition":"the study of allele frequencies and their changes in populations","definitionCN":"研究群体中等位基因频率及其变化","example":"Population genetics tracks allele frequencies over time.","exampleCN":"群体遗传学追踪等位基因频率随时间的变化。","why":"Once genes are counted across groups, genetics becomes a science of frequencies rather than of single families.","whyCN":"一旦跨群体计数基因，遗传学就成为频率的科学，而非单个家族的科学。"},{"no":"06","title":"Genetics as a subject taught","titleCN":"作为课程的遗传学","definition":"the subject as taught or examined in a course","definitionCN":"作为课程或考试科目的遗传学","example":"She teaches genetics to first-year biology students.","exampleCN":"她给一年级生物学生教遗传学。","why":"The discipline name also names a course, which is why it appears with teach, study and examine.","whyCN":"学科名同时也指一门课程，因此常与「教」「学」「考」搭配。"},{"no":"07","title":"Clinical genetics","titleCN":"临床遗传学","definition":"the application of genetics to diagnosis and counselling in medicine","definitionCN":"遗传学在医学诊断与咨询中的应用","example":"Clinical genetics offers testing for inherited conditions.","exampleCN":"临床遗传学为遗传性疾病提供检测。","why":"The clinical compound marks the point where the science meets patients, testing and advice.","whyCN":"临床复合词标记出这门科学与患者、检测与建议相接的地方。"},{"no":"08","title":"Genetics in agriculture","titleCN":"农业中的遗传学","definition":"the use of genetic knowledge to improve crops and livestock","definitionCN":"利用遗传知识改良作物与家畜","example":"Modern genetics produced wheat that tolerates drought.","exampleCN":"现代遗传学培育出了耐旱小麦。","why":"Breeding was practiced long before the science existed, but genetics now explains and directs what breeders do.","whyCN":"育种远在这门科学出现之前就已实践，但遗传学如今解释并指导育种者的工作。"}],"etymology":{"intro":{"en":"Genetics was coined from Greek genetikos 'generative', a derivative of genesis 'origin' and genos 'race, kind'. The English noun is usually credited to William Bateson, who proposed it in 1905 and published it in 1906; other reference works record an isolated use in 1872 and a related sense in 1891, so the first date is disputed.","cn":"genetics 由希腊 genetikos「生殖的、产生的」造出，后者源出 genesis「起源」与 genos「种族、种类」。英语名词通常归功于威廉·贝特森，他于 1905 年提出、1906 年发表；另有参考书记录 1872 年的一处孤立用法与 1891 年的相关义，因此首见年代存在争议。"},"items":[{"era":"GREEK GENOS","en":"Genos meant 'race, kind, birth'. It belongs to the PIE family reconstructed as *ǵenh₁-, so that root form is a reconstruction; Latin genus is a cognate, not the source of the English word.","cn":"genos 意为「种族、种类、出生」。它属于被重构为 *ǵenh₁- 的原始印欧语词族，因此该词根形式是重构；拉丁 genus 是同源词，并非这个英语词的来源。"},{"era":"GREEK GENESIS","en":"Genesis 'origin, generation' supplied the noun of coming into being that stands behind genetikos.","cn":"genesis「起源、生成」提供了「进入存在」的名词，位于 genetikos 之后。"},{"era":"GREEK GENETIKOS","en":"Genetikos 'generative, concerned with generation' was formed with the adjectival suffix -ikos.","cn":"genetikos「生殖的、与生成有关的」由形容词后缀 -ikos 构成。"},{"era":"ENGLISH COINAGE","en":"William Bateson proposed genetics in a letter of 1905 and used it in print in 1906; some reference works record an isolated 1872 use and a 'study of heredity' sense in 1891, so the exact first appearance is disputed rather than the root.","cn":"威廉·贝特森在 1905 年的一封信中提出 genetics，并于 1906 年用于印刷文本；有些参考书记录 1872 年的一处孤立用法与 1891 年的「遗传研究」义，因此存疑的是确切首见年代，而非词根。"},{"era":"MODERN FIELD","en":"During the twentieth century the field split into molecular, population and clinical branches, and the plural-looking name stayed grammatically singular.","cn":"20 世纪，该领域分化为分子、群体与临床分支，这个看似复数的名称在语法上仍保持单数。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date only): the root in genetikos is not in doubt, but the first English appearance is disputed between an isolated 1872 use, an 1891 sense and Bateson's 1905-1906 coinage; no Latin derivative of genetikos exists, so latinEntries is empty, and the Latin cognate genus belongs to the same PIE family but is not the source.","cn":"来源不确定（仅首见年代）：genetikos 的词根并无疑问，但英语首见年代在 1872 年孤立用法、1891 年义项与贝特森 1905—1906 年造词之间存在争议；genetikos 没有拉丁派生词，因此 latinEntries 留空；拉丁同源词 genus 属于同一原始印欧语词族，但并非来源。"}]},"similar":{"note":{"en":"Group one separates genetics from words built on the same Greek stem and from one accidental sound-alike; group two separates it from the neighbouring sciences and from the older word for transmission.","cn":"第一组把 genetics 与同一希腊词干构成的词及一个偶然音近词分开；第二组把它与邻近学科及更早的「传递」用词区分。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"genetic","ipa":"/dʒəˈnetɪk/","tag":"same root, the adjective","definition":"The adjective meaning 'relating to genes'; genetics is the discipline or the makeup it studies.","definitionCN":"意为「与基因有关的」的形容词；genetics 是学科或被研究的组成。"},{"word":"genomics","ipa":"/dʒəˈnɒmɪks/","tag":"same root, a different scale","definition":"The study of whole genomes rather than single genes; it grew out of genetics but is not a synonym.","definitionCN":"研究整个基因组而非单个基因的学科；由遗传学发展而来，但并非同义词。"},{"word":"gene","ipa":"/dʒiːn/","tag":"same root, the unit","definition":"The unit of heredity that genetics studies; the science and its object are not interchangeable.","definitionCN":"遗传学所研究的遗传单位；学科与其对象不能互换。"},{"word":"gymnastics","ipa":"/dʒɪmˈnæstɪks/","tag":"different root","definition":"From Greek gymnazein 'to train naked', not from genos: physical exercises. The resemblance is only in sound.","definitionCN":"来自希腊 gymnazein「裸身训练」，并非 genos：指体操。相似仅在读音。"}]},{"heading":"NEAR MEANING","entries":[{"word":"heredity","ipa":"/həˈredəti/","tag":"the process studied","definition":"The transmission of traits; genetics is the science that explains it, not the transmission itself.","definitionCN":"指性状传递；genetics 是解释它的科学，而非传递本身。"},{"word":"inheritance","ipa":"/ɪnˈherɪtəns/","tag":"the broader word","definition":"A broader word for property and biological transmission; genetics names the discipline, not an estate.","definitionCN":"涵盖财产与生物传递的较宽泛词；genetics 命名学科，而非产业。"},{"word":"genomics","ipa":"/dʒəˈnɒmɪks/","tag":"the whole-set science","definition":"The study of complete genomes; genetics often focuses on individual genes and their effects.","definitionCN":"研究完整基因组的学科；genetics 常聚焦单个基因及其效应。"},{"word":"molecular biology","ipa":"/məˈlekjələ baɪˈɒlədʒi/","tag":"the wider field","definition":"The wider study of biological molecules; genetics is one part of it, focused on heredity.","definitionCN":"研究生物大分子的更广领域；遗传学是其中专注遗传的一部分。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Greek genos 'race, kind' + -etics: the study of how kind passes down.","cn":"希腊 genos「种族、种类」+ 学科后缀：研究种类如何下传的学问。"},{"en":"The family runs gene, genetic, genetically, genetics, geneticist and genomics.","cn":"同族词包括 gene、genetic、genetically、genetics、geneticist 与 genomics。"},{"en":"The name ends in -s but takes a singular verb when it means the science.","cn":"这个词以 -s 结尾，但指学科时接单数动词。"},{"en":"Bateson proposed the term in 1905 and printed it in 1906.","cn":"贝特森于 1905 年提出该术语，1906 年正式印行。"},{"en":"Medical, molecular and population are its common branches.","cn":"医学、分子与群体是其常见分支。"}],"abstract":[{"en":"Picture a library that catalogues not books but the instructions for making them.","cn":"想象一座图书馆不编目书籍，而编目造书的指令。"},{"en":"Picture a family tree redrawn as a table of frequencies.","cn":"想象一棵家谱树被重画成一张频率表。"},{"en":"Picture a recipe book whose pages are copied with occasional mistakes.","cn":"想象一本食谱，页面被复制时偶尔出错。"}]},"examples":[{"en":"Genetics has become central to conservation planning.","cn":"遗传学已成为保护规划的核心。"},{"en":"The genetics of the island population show a long isolation.","cn":"这个岛屿群体的遗传组成显示出长期隔离。"},{"en":"She switched from field biology to genetics after her first course.","cn":"她在上完第一门课后从野外生物学转向遗传学。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"gene（基因）+ tics（学科）——研究基因的学科 → 遗传学；指学科时作单数。","word":"genetics"},"root":"希腊 genetikos「生殖的」← genesis「起源」+ genos「种族、种类」；genos 出自原始印欧语 *ǵenh₁-（重构形式）；拉丁 genus 为同源词，非来源；英语词通常归功于贝特森 1905—1906 年，另有 1872/1891 年早期用法之说。","sensesIntro":{"en":"Eight senses follow one discipline as it spreads: the science, the makeup it describes, its branches, its molecular and population scales, its teaching, its clinical use and its agricultural use.","cn":"八个义项沿一门学科的外扩展开：学科本身、它所描述的组成、它的分支、分子与群体尺度、它的教学、临床用途与农业用途。"},"semanticMap":{"core":{"en":"CORE IMAGE: a whiteboard of crosses and ratios beside trays of labelled seedlings.","cn":"核心意象：一块写满杂交与比例的白板，旁边是一排标了代号的育苗盘。"},"chain":["RACE OR KIND","ORIGIN","GENERATIVE","SCIENCE OF HEREDITY","GENETIC MAKEUP","APPLIED BRANCHES"],"branches":[{"senses":"S1 · S6","en":"THE DISCIPLINE: the science itself, including the course that teaches it.","cn":"学科：科学本身，包括讲授它的课程。"},{"senses":"S2","en":"THE MAKEUP: the name transferred from the field to what the field measures.","cn":"组成：名称从领域转用到领域所测量的对象。"},{"senses":"S3 · S4 · S5","en":"BRANCHES AND SCALES: medical, molecular and population divisions.","cn":"分支与尺度：医学、分子与群体划分。"},{"senses":"S7","en":"CLINICAL USE: testing and counselling where the science meets patients.","cn":"临床用途：科学与患者相接处的检测与咨询。"},{"senses":"S8","en":"AGRICULTURAL USE: breeding guided by genetic knowledge.","cn":"农业用途：由遗传知识指导的育种。"}]},"affixes":{"intro":{"en":"Genetics is a Greek-derived compound whose stem also builds the modern vocabulary of heredity; the suffixes mark an adjective, a science and a person.","cn":"genetics 是希腊语来源的复合词，其词干还构成现代遗传词汇；后缀分别标记形容词、学科与从业者。"},"latinIntro":{"en":"Greek genos 'race, kind' gives gene, genetic, genetics and genomics; -ikos gives the adjective and -ics names the field. No Latin derivative of genetikos exists, so latinEntries is empty.","cn":"希腊 genos「种族、种类」衍生 gene、genetic、genetics 与 genomics；-ikos 构成形容词，-ics 命名学科。genetikos 没有拉丁派生词，因此 latinEntries 留空。"},"items":[{"word":"genos","structure":"genos (Greek noun, 'race, kind, birth')","meaning":"race; kind; birth","meaningCN":"种族；种类；出生","example":"The stem names a kind that reproduces its kind.","exampleCN":"这个词干命名会繁衍同类的那种「类」。"},{"word":"genesis","structure":"genesis (Greek noun, 'origin, generation')","meaning":"origin; coming into being","meaningCN":"起源；生成","example":"Genesis names the coming-into-being of a thing.","exampleCN":"genesis 命名事物进入存在的过程。"},{"word":"genetikos","structure":"genetikos (Greek adjective, 'generative')","meaning":"generative; concerned with generation","meaningCN":"生殖的；与生成有关的","example":"The adjective described what produces or transmits.","exampleCN":"这个形容词描述能产生或传递的东西。"},{"word":"-ikos","structure":"-ikos (Greek adjectival suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix turned the noun stem into an adjective.","exampleCN":"这个后缀把名词词干变成形容词。"},{"word":"-ics","structure":"-ics (English suffix naming a science)","meaning":"field or discipline","meaningCN":"学科；领域","example":"The suffix makes the adjective into a science name.","exampleCN":"这个后缀把形容词变成学科名。"},{"word":"gene","structure":"genos, shortened through Danish gen","meaning":"unit of heredity","meaningCN":"基因","example":"A gene is a unit of heredity.","exampleCN":"基因是遗传单位。"},{"word":"genetic","structure":"genetikos via French génétique","meaning":"relating to genes","meaningCN":"遗传的；基因的","example":"Genetic testing is now routine.","exampleCN":"基因检测如今已很常规。"},{"word":"genetically","structure":"genetic + -ally","meaning":"in genetic terms","meaningCN":"遗传上；基因上","example":"The strains are genetically distinct.","exampleCN":"这些菌株在遗传上不同。"},{"word":"genetics","structure":"genetikos + -ics","meaning":"the science of heredity","meaningCN":"遗传学","example":"Genetics explains inheritance.","exampleCN":"遗传学解释遗传。"},{"word":"geneticist","structure":"genetics + -ist (person)","meaning":"a specialist in genetics","meaningCN":"遗传学家","example":"The geneticist mapped the region.","exampleCN":"这位遗传学家绘制了该区域。"},{"word":"genomics","structure":"genome + -ics","meaning":"the study of whole genomes","meaningCN":"基因组学","example":"Genomics compares complete sequences.","exampleCN":"基因组学比较完整序列。"},{"word":"genotype","structure":"genos + typos (Greek 'impression')","meaning":"the inherited constitution","meaningCN":"基因型","example":"The genotype was recorded for each plant.","exampleCN":"每株植物都记录了基因型。"}],"latinEntries":[]}},{"word":"genetic","ipa_uk":"/dʒɪˈnetɪk/","ipa_us":"/dʒəˈnetɪk/","definition_zh":"遗传的；基因的；与起源或发生有关的（旧义）","definition_en":"relating to genes or heredity, or, in older use, relating to origin and development","core_image":"两株外观相同的幼苗被切开，内部露出一段段不同的指令条纹","scene":"两株同样的苗，一株在阴处长得细弱，一株在阳光下粗壮。The difference lies in genetic makeup rather than in care.","sceneCN":"这里 genetic 指「与基因组成有关的」（第 1 个义项：与基因相关的）；句意为差别在于基因组成，而不在于照料。可辨识物件：两株幼苗、遮阴布、光照灯、标注基因组成的卡片。","pos":[{"tag":"adj.","zh":"遗传的；基因的"},{"tag":"adj.","zh":"起源的；发生的（旧义）"}],"collocations":[{"phrase":"genetic testing","zh":"基因检测"},{"phrase":"genetic engineering","zh":"基因工程"},{"phrase":"genetic code","zh":"遗传密码"},{"phrase":"genetic diversity","zh":"遗传多样性"},{"phrase":"genetic predisposition","zh":"遗传易感性"},{"phrase":"genetic relationship","zh":"遗传关系；谱系关系"}],"forms":[{"label":"副词","form":"genetically"},{"label":"名词（遗传学）","form":"genetics"},{"label":"旧变体（罕用）","form":"genetical"},{"label":"比较级（少用）","form":"more genetic"},{"label":"最高级（少用）","form":"most genetic"}],"derivatives":[{"word":"genetics","pos":"n.","zh":"遗传学"},{"word":"genetically","pos":"adv.","zh":"遗传上；基因上"},{"word":"geneticist","pos":"n.","zh":"遗传学家"},{"word":"genome","pos":"n.","zh":"基因组"}],"senses":[{"no":"01","title":"Relating to genes","titleCN":"与基因相关的","definition":"relating to genes or the material that carries them","definitionCN":"与基因或承载基因的物质相关","example":"Genetic testing can reveal carrier status.","exampleCN":"基因检测可以揭示携带者状态。","why":"The adjective attaches the whole vocabulary of heredity to a noun, so testing, material and code all become genetic.","whyCN":"这个形容词把整套遗传词汇附着到名词上，因此检测、物质与密码都可以成为「基因的」。"},{"no":"02","title":"Inherited rather than acquired","titleCN":"遗传而非后天获得的","definition":"determined by inheritance rather than by environment","definitionCN":"由遗传而非环境决定","example":"The condition is genetic, not infectious.","exampleCN":"这种病是遗传的，不是传染的。","why":"In this sense the word draws a line: what is genetic comes with the organism, not from contact or choice.","whyCN":"在这个义项里，这个词划出一条界线：遗传之物随生物体而来，不来自接触或选择。"},{"no":"03","title":"Relating to origin or development","titleCN":"与起源或发生有关的（旧义）","definition":"concerned with the origin and development of something, especially in older philosophy and linguistics","definitionCN":"与某物的起源和发展有关，尤见于较早的哲学与语言学","example":"The genetic link between the two languages is disputed.","exampleCN":"这两种语言之间的谱系联系尚有争议。","why":"Before genes were known, genetic meant 'pertaining to origins'; linguistics still uses it for language families.","whyCN":"在基因被发现之前，genetic 意为「与起源有关的」；语言学仍用它指语言谱系。"},{"no":"04","title":"Of genetic engineering","titleCN":"基因工程的","definition":"relating to the deliberate alteration of genetic material","definitionCN":"与有意改变遗传物质相关","example":"Genetic engineering inserted a bacterial gene into the crop.","exampleCN":"基因工程把一个细菌基因植入作物。","why":"Once humans could cut and paste sequences, the adjective began to modify the techniques as well as the material.","whyCN":"当人类能够剪切与粘贴序列后，这个形容词开始修饰技术，而不只是物质。"},{"no":"05","title":"Of the genetic code","titleCN":"遗传密码的","definition":"relating to the mapping from nucleotide triplets to amino acids","definitionCN":"与核苷酸三联体到氨基酸的对应关系相关","example":"The genetic code maps triplets to amino acids.","exampleCN":"遗传密码把三联体映射到氨基酸。","why":"The word describes a system of correspondence, not a single gene, which is why code is its natural noun.","whyCN":"这个词描述一套对应系统，而非单个基因，因此「密码」是它的自然搭配。"},{"no":"06","title":"Of genetic diversity","titleCN":"遗传多样性的","definition":"relating to the range of genetic variation within a group","definitionCN":"与一个群体内遗传变异的幅度相关","example":"Genetic diversity protects a population from disease.","exampleCN":"遗传多样性保护群体免受疾病。","why":"Here the adjective measures variety across a group, so it contrasts with uniformity rather than with environment.","whyCN":"这里这个形容词衡量群体内的差异，因此与「一致」相对，而非与环境相对。"},{"no":"07","title":"Of a genetic predisposition","titleCN":"遗传易感性的","definition":"relating to an inherited tendency that raises the likelihood of a condition","definitionCN":"与提高患病可能性的遗传倾向相关","example":"A genetic predisposition raises the risk but does not decide it.","exampleCN":"遗传易感性提高风险，但不决定结果。","why":"The phrase keeps inheritance and inevitability apart, a distinction the adjective alone does not make.","whyCN":"这个短语把遗传与必然分开，而单靠形容词并不能作出这一区分。"},{"no":"08","title":"Of genetic relationship","titleCN":"遗传关系或谱系关系的","definition":"relating to shared ancestry, whether of organisms or of languages","definitionCN":"与共同祖先相关，无论指生物还是语言","example":"Genetic relationship among species is measured by shared sequences.","exampleCN":"物种间的遗传关系由共享序列来测量。","why":"The older 'origin' sense and the newer 'gene' sense meet here: shared ancestry can be read from sequences or from language forms.","whyCN":"较旧的「起源」义与较新的「基因」义在此相遇：共同祖先既可从序列读出，也可从语言形式读出。"}],"etymology":{"intro":{"en":"Genetic comes from Greek genetikos 'generative', through French génétique. English first used it for 'pertaining to origin' from 1831, and from the early twentieth century, often dated 1908, for genes and heredity.","cn":"genetic 来自希腊 genetikos「生殖的」，经法语 génétique 传入。英语从 1831 年起用它表示「与起源有关的」，到 20 世纪初（常定在 1908 年）才用于基因与遗传。"},"items":[{"era":"GREEK GENOS","en":"Genos 'race, kind, birth' belongs to the PIE family reconstructed as *ǵenh₁-, so the root form is a reconstruction; Latin genus is a cognate, not the source.","cn":"genos「种族、种类、出生」属于被重构为 *ǵenh₁- 的原始印欧语词族，因此该词根形式是重构；拉丁 genus 是同源词，并非来源。"},{"era":"GREEK GENETIKOS","en":"Genetikos 'generative' was built on genesis 'origin' with the adjectival suffix -ikos.","cn":"genetikos「生殖的」由 genesis「起源」加形容词后缀 -ikos 构成。"},{"era":"EARLY ENGLISH","en":"Genetic entered English in 1831 (early nineteenth century) with the sense 'pertaining to origin or development', especially in philosophy and linguistics; the date is recorded, but how the sense developed is not fully documented.","cn":"genetic 在 1831 年（19 世纪初）以「与起源或发展有关的」义进入英语，尤用于哲学与语言学；年代有记录，但该义如何发展并无完整文献。"},{"era":"BIOLOGICAL SENSE","en":"From the early twentieth century, often dated 1908, the adjective was attached to genes and heredity, and this sense now dominates everyday use.","cn":"到 20 世纪初（常定在 1908 年），这个形容词被附着到基因与遗传上，这一义项如今在日常使用中占主导。"},{"era":"LATIN COGNATE","en":"Latin genus and generare belong to the same PIE family, but genetic is not derived from them; generic is the adjective built directly on Latin genus.","cn":"拉丁 genus 与 generare 属于同一原始印欧语词族，但 genetic 并非由它们派生；generic 才是直接建立在拉丁 genus 上的形容词。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (sense dates): the 1831 first use is on record, but the exact date of the biological shift is given variously as 1905 and 1908, and no Latin derivative of genetikos exists, so latinEntries is empty.","cn":"来源不确定（义项年代）：1831 年的首用有记录，但生物学义的确切年代有 1905 与 1908 两说；且 genetikos 没有拉丁派生词，因此 latinEntries 留空。"}]},"similar":{"note":{"en":"Group one separates genetic from related formations and near sound-alikes; group two separates it from the words for inherited and whole-genome properties.","cn":"第一组把 genetic 与相关构词及音近词分开；第二组把它与「遗传的」「全基因组的」等词区分。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"generic","ipa":"/dʒəˈnerɪk/","tag":"same PIE family, different formation","definition":"Built directly on Latin genus 'kind', not on Greek genetikos: it means 'general, not branded or specific'. The two words are related only through the PIE family.","definitionCN":"直接建立在拉丁 genus「种类」上，而非希腊 genetikos：意为「通用的、非专属的」。两词仅通过原始印欧语词族相关联。"},{"word":"genetical","ipa":"/dʒəˈnetɪkl/","tag":"older variant adjective","definition":"An older adjective form now mostly replaced by genetic; it survives in some technical writing.","definitionCN":"较旧的形容词形式，现多被 genetic 取代；仍残存于部分技术文献。"},{"word":"genital","ipa":"/ˈdʒenɪtl/","tag":"same Latin root, different meaning","definition":"From genitalis, built on the same gignere stem, but it refers to reproduction and anatomy, not to genes.","definitionCN":"来自 genitalis，建立在同一 gignere 词干上，但指生殖与解剖，而非基因。"},{"word":"congenital","ipa":"/kənˈdʒenɪtl/","tag":"same Latin root, different sense","definition":"Con- 'together' plus gignere 'beget': present from birth. It is not a synonym of genetic, since a congenital cause may be non-genetic.","definitionCN":"con-「共同」加 gignere「生育」：指出生即有。它不是 genetic 的同义词，因为先天原因未必是遗传原因。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hereditary","ipa":"/hɪˈredɪtəri/","tag":"emphasises transmission","definition":"It stresses descent from ancestors, while genetic points to the genes that carry the trait.","definitionCN":"强调从祖先传来，而 genetic 指向承载性状的基因。"},{"word":"inherited","ipa":"/ɪnˈherɪtɪd/","tag":"the everyday participle","definition":"The ordinary participle from inherit; genetic is the technical adjective and can also mean 'relating to genes' without transmission.","definitionCN":"inherit 的普通分词；genetic 是技术形容词，也可仅指「与基因有关」而不涉及传递。"},{"word":"genomic","ipa":"/dʒəˈnɒmɪk/","tag":"whole-genome scale","definition":"Relating to the entire genome rather than to individual genes.","definitionCN":"与整个基因组相关，而非单个基因。"},{"word":"congenital","ipa":"/kənˈdʒenɪtl/","tag":"present from birth","definition":"Present at birth, whether or not the cause is genetic; the two words answer different questions.","definitionCN":"指出生时即存在，无论原因是否遗传；两词回答不同问题。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"genos 'kind' + -ic: belonging to the kind one is born into.","cn":"genos「种类」+ -ic：属于出生所在的那个种类。"},{"en":"The family runs gene, genetic, genetically, genetics and geneticist.","cn":"同族词包括 gene、genetic、genetically、genetics 与 geneticist。"},{"en":"Old sense: genetic philosophy, genetic linguistics, meaning 'of origins'.","cn":"旧义搭配：发生哲学、谱系语言学，意为「关于起源的」。"},{"en":"New sense in the early twentieth century: genetic code, genetic testing, genetic engineering.","cn":"20 世纪初的新义搭配：遗传密码、基因检测、基因工程。"},{"en":"Genetic is not congenital: a congenital condition need not be genetic.","cn":"genetic 不等于 congenital：先天状况未必是遗传的。"}],"abstract":[{"en":"Picture a sealed envelope that comes with the body and cannot be exchanged.","cn":"想象一个随身体附来的密封信封，无法退换。"},{"en":"Picture two identical chairs made from different batches of wood.","cn":"想象两把相同的椅子，用不同批次的木材做成。"},{"en":"Picture an old map labelled by origin rather than by road.","cn":"想象一张按起源而非按道路标注的旧地图。"}]},"examples":[{"en":"Genetic testing is offered to families with a known history of the disease.","cn":"有明确家族史的家庭可获得基因检测。"},{"en":"The two languages show a genetic relationship in their verb endings.","cn":"这两种语言在动词词尾上显示出谱系关系。"},{"en":"Genetic diversity fell sharply after the population crashed.","cn":"群体数量骤降后，遗传多样性急剧下降。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"gene（基因）+ tic（形容词尾）——与基因有关的 → 遗传的；旧义是「关于起源的」。","word":"genetic"},"root":"希腊 genetikos「生殖的」← genesis「起源」+ genos「种族、种类」；genos 出自原始印欧语 *ǵenh₁-（重构形式）；拉丁 genus 为同源词，非来源。","sensesIntro":{"en":"Eight senses follow one adjective as it moves from origins to genes: gene-related, inherited, origin-related, engineered, coded, diverse, predisposing and ancestry-sharing.","cn":"八个义项沿一个形容词从「起源」走向「基因」：与基因相关、遗传而来、关于起源、经工程改造、关于密码、关于多样性、关于易感性、关于共同祖先。"},"semanticMap":{"core":{"en":"CORE IMAGE: two identical seedlings cut open to show different stripes of instructions inside.","cn":"核心意象：两株外观相同的幼苗被切开，内部露出不同的指令条纹。"},"chain":["ORIGIN","KIND","GENERATIVE","GENE-RELATED","INHERITED","APPLIED TO SEQUENCES"],"branches":[{"senses":"S1 · S2","en":"GENES AND INHERITANCE: the core modern pair, what genes are and what comes with them.","cn":"基因与遗传：现代核心的两项，基因是什么，以及随基因而来的东西。"},{"senses":"S3 · S8","en":"ORIGINS AND ANCESTRY: the older sense survives in language families and shared descent.","cn":"起源与祖先：旧义残存于语系与共同世系。"},{"senses":"S4 · S5","en":"ENGINEERING AND CODE: techniques for altering sequences, and the mapping they use.","cn":"工程与密码：改变序列的技术，以及它们所用的对应表。"},{"senses":"S6","en":"DIVERSITY: variation across a group, measured at the level of genes.","cn":"多样性：群体内的变异，在基因层面测量。"},{"senses":"S7","en":"PREDISPOSITION: an inherited tendency that raises risk without fixing the outcome.","cn":"易感性：提高风险却不固定结果的遗传倾向。"}]},"affixes":{"intro":{"en":"Genetic is the adjective of the Greek-derived gen- family; its suffix marks relation, and the same stem builds the science and the agent noun.","cn":"genetic 是希腊来源 gen- 词族的形容词；后缀标记关系，同一词干还构成学科名与从业者名。"},"latinIntro":{"en":"Greek genos 'race, kind' gives genetic and genetics; -ikos gives the adjective, -ics the science. No Latin derivative of genetikos exists, so latinEntries is empty; Latin genus is only a cognate.","cn":"希腊 genos「种族、种类」衍生 genetic 与 genetics；-ikos 构成形容词，-ics 构成学科名。genetikos 没有拉丁派生词，因此 latinEntries 留空；拉丁 genus 仅为同源词。"},"items":[{"word":"genos","structure":"genos (Greek noun, 'race, kind')","meaning":"race; kind","meaningCN":"种族；种类","example":"The stem names a kind that reproduces itself.","exampleCN":"这个词干命名自我繁衍的「类」。"},{"word":"genesis","structure":"genesis (Greek noun, 'origin')","meaning":"origin; generation","meaningCN":"起源；生成","example":"Genesis supplies the idea of coming into being.","exampleCN":"genesis 提供「进入存在」的观念。"},{"word":"genetikos","structure":"genetikos (Greek adjective)","meaning":"generative","meaningCN":"生殖的；生成的","example":"The adjective described what generates.","exampleCN":"这个形容词描述能生成之物。"},{"word":"-ic","structure":"-ic (adjective suffix from Greek -ikos)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix makes a relational adjective.","exampleCN":"这个后缀构成关系形容词。"},{"word":"gene","structure":"genos, shortened through Danish gen","meaning":"unit of heredity","meaningCN":"基因","example":"A gene is a unit of heredity.","exampleCN":"基因是遗传单位。"},{"word":"genetic","structure":"genetikos via French","meaning":"relating to genes or origins","meaningCN":"遗传的；基因的；起源的","example":"Genetic testing is routine.","exampleCN":"基因检测已很常规。"},{"word":"genetically","structure":"genetic + -ally","meaning":"in genetic terms","meaningCN":"遗传上；基因上","example":"The strains are genetically distinct.","exampleCN":"这些菌株在遗传上不同。"},{"word":"genetics","structure":"genetic + -ics","meaning":"the science of heredity","meaningCN":"遗传学","example":"Genetics explains inheritance.","exampleCN":"遗传学解释遗传。"},{"word":"geneticist","structure":"genetics + -ist","meaning":"a specialist in genetics","meaningCN":"遗传学家","example":"The geneticist mapped the region.","exampleCN":"这位遗传学家绘制了该区域。"},{"word":"genome","structure":"genos + -ome, modelled on chromosome","meaning":"the whole set of genes","meaningCN":"基因组","example":"The genome was sequenced.","exampleCN":"基因组被测序。"},{"word":"genotype","structure":"genos + typos 'impression'","meaning":"the inherited constitution","meaningCN":"基因型","example":"The genotype was recorded.","exampleCN":"基因型被记录。"}],"latinEntries":[]}},{"word":"genetically","ipa_uk":"/dʒɪˈnetɪkli/","ipa_us":"/dʒəˈnetɪkli/","definition_zh":"遗传上；从基因角度；以遗传方式；经基因改造地","definition_en":"in a way that relates to genes or heredity, or by means of genetic material or genetic modification","core_image":"两批外观相同的种子被放进检测仪，屏幕上显示出内部不同的条带","scene":"两批种子外表相同，实验室却能测出内部的差异。The two strains are genetically distinct although they look alike.","sceneCN":"这里 genetically 指「从基因角度看、在遗传上」（第 2 个义项：就基因而言）；句意为这两个菌株虽然外表相似，在遗传上却不同。可辨识物件：两盘种子、检测仪、条带屏幕、标签。","pos":[{"tag":"adv.","zh":"遗传上；从基因角度"},{"tag":"adv.","zh":"以遗传方式；经基因改造地"}],"collocations":[{"phrase":"genetically modified","zh":"转基因的；经基因改造的"},{"phrase":"genetically distinct","zh":"遗传上不同的"},{"phrase":"genetically determined","zh":"由遗传决定的"},{"phrase":"genetically engineered","zh":"经基因工程的"},{"phrase":"genetically inherited","zh":"经遗传得来的"},{"phrase":"genetically identical","zh":"遗传上相同的"}],"forms":[{"label":"比较级（少用）","form":"more genetically"},{"label":"最高级（少用）","form":"most genetically"},{"label":"形容词","form":"genetic"},{"label":"名词（遗传学）","form":"genetics"}],"derivatives":[{"word":"genetic","pos":"adj.","zh":"遗传的；基因的"},{"word":"genetics","pos":"n.","zh":"遗传学"},{"word":"geneticist","pos":"n.","zh":"遗传学家"},{"word":"genome","pos":"n.","zh":"基因组"}],"senses":[{"no":"01","title":"By genetic modification","titleCN":"经基因改造地","definition":"by changing genetic material, especially through engineering","definitionCN":"通过改变遗传物质，尤指通过工程手段","example":"The crop was genetically modified to resist insects.","exampleCN":"这种作物经过基因改造以抵抗昆虫。","why":"The adverb marks the means, so genetically modified means changed at the level of the instructions rather than by breeding alone.","whyCN":"这个副词标记手段，因此「经基因改造」指在指令层面被改变，而非仅靠育种。"},{"no":"02","title":"In genetic terms","titleCN":"从基因角度看","definition":"as judged by genes rather than by appearance","definitionCN":"以基因而非外表来评判","example":"The two strains are genetically distinct although they look alike.","exampleCN":"这两个菌株外表相似，在遗传上却不同。","why":"Here the adverb sets the viewpoint: what is compared is the sequence, not the visible form.","whyCN":"这里这个副词设定视角：比较的是序列，而非可见形态。"},{"no":"03","title":"As determined by inheritance","titleCN":"由遗传决定地","definition":"in a way that is influenced or fixed by inherited factors","definitionCN":"受遗传因素影响或固定的方式","example":"Height is genetically influenced but not fixed.","exampleCN":"身高受遗传影响，但并非固定不变。","why":"The adverb can soften causation: genetically influenced leaves room for environment, while genetically determined closes it.","whyCN":"这个副词可以缓和因果关系：受遗传影响仍给环境留余地，而由遗传决定则不留。"},{"no":"04","title":"At the level of genetic material","titleCN":"在遗传物质层面","definition":"by examining or acting on DNA or other hereditary material","definitionCN":"通过检查或作用于遗传物质","example":"The samples were compared genetically.","exampleCN":"这些样本在遗传层面做了比较。","why":"The adverb can describe a method as well as a cause: comparing genetically means using sequences as the evidence.","whyCN":"这个副词既能描述方法也能描述原因：在遗传层面比较，就是用序列作证据。"},{"no":"05","title":"Through genetic transmission","titleCN":"经遗传传递地","definition":"by passing from parents to offspring through genes","definitionCN":"通过基因由亲代传给子代","example":"The disorder is genetically transmitted.","exampleCN":"这种疾病经遗传传递。","why":"The adverb attaches transmission to genes, so the route is explicitly biological rather than social.","whyCN":"这个副词把传递附着到基因上，因此路径明确是生物的，而非社会的。"},{"no":"06","title":"With respect to genetic makeup","titleCN":"就遗传组成而言","definition":"in terms of the overall genetic constitution of a group","definitionCN":"就一个群体的整体遗传构成而言","example":"Genetically, the island population is unusually uniform.","exampleCN":"就遗传而言，这个岛屿群体异常一致。","why":"At the start of a clause, the adverb frames the whole statement as a genetic judgement.","whyCN":"置于句首时，这个副词把整句框定为遗传判断。"},{"no":"07","title":"By genetic engineering","titleCN":"通过基因工程地","definition":"by deliberate insertion, deletion or editing of sequences","definitionCN":"通过有意插入、删除或编辑序列","example":"The vaccine seed strain was genetically engineered.","exampleCN":"疫苗种株经过基因工程改造。","why":"Engineering is the most deliberate form of the means sense: the change is designed, not selected from existing variation.","whyCN":"工程是手段义中最有意的一种：改变是被设计出来的，而非从既有变异中选出的。"},{"no":"08","title":"In genetic classification","titleCN":"在遗传分类上","definition":"as grouped by shared genetic material rather than by visible traits","definitionCN":"按共享遗传物质而非可见性状来归类","example":"Genetically, the two species belong to one genus.","exampleCN":"从遗传分类看，这两个物种属于同一属。","why":"The adverb can qualify taxonomy itself, marking a classification that follows sequences instead of shape.","whyCN":"这个副词能限定分类学本身，标记一种依据序列而非外形的分类。"}],"etymology":{"intro":{"en":"Genetically is genetic plus the adverbial ending -ally, from -al + -ly. The adjective goes back through French to Greek genetikos 'generative'.","cn":"genetically 是 genetic 加副词词尾 -ally 构成，后者来自 -al + -ly。形容词经法语上溯到希腊 genetikos「生殖的」。"},"items":[{"era":"GREEK GENOS","en":"Genos 'race, kind' belongs to the PIE family reconstructed as *ǵenh₁-, so the root form is a reconstruction; Latin genus is a cognate, not the source.","cn":"genos「种族、种类」属于被重构为 *ǵenh₁- 的原始印欧语词族，因此该词根形式是重构；拉丁 genus 是同源词，并非来源。"},{"era":"GREEK GENETIKOS","en":"Genetikos 'generative' was formed from genesis 'origin' with the suffix -ikos.","cn":"genetikos「生殖的」由 genesis「起源」加后缀 -ikos 构成。"},{"era":"ENGLISH ADJECTIVE","en":"Genetic entered English in 1831 for 'pertaining to origin', and from the early twentieth century, often dated 1908, for genes; genetical was the older adjective form.","cn":"genetic 在 1831 年以「关于起源的」义进入英语，20 世纪初（常定在 1908 年）起用于基因；genetical 是较早的形容词形式。"},{"era":"ADVERB FORM","en":"The adverb was built as genetic + -al + -ly, giving genetically; the older genetical now survives mainly in technical writing.","cn":"副词由 genetic + -al + -ly 构成，写作 genetically；较旧的 genetical 如今主要残存于技术文献。"},{"era":"SCIENTIFIC SPREAD","en":"In the twentieth century the adverb spread to modification, screening and classification: genetically modified, genetically screened, genetically distinct.","cn":"20 世纪，这个副词扩展到改造、筛查与分类：转基因、经基因筛查、遗传上不同。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the first recorded use of the adverb is not firmly dated, and no Latin derivative of genetikos exists, so latinEntries is empty.","cn":"来源不确定（首见年代）：这个副词的最早书证没有确切年代，且 genetikos 没有拉丁派生词，因此 latinEntries 留空。"}]},"similar":{"note":{"en":"Group one separates genetically from look-alikes with other roots; group two separates it from adverbs that name inheritance, genotype or environment.","cn":"第一组把 genetically 与词根不同的形近词分开；第二组把它与表示遗传、基因型或环境的副词区分。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"genially","ipa":"/ˈdʒiːniəli/","tag":"different root","definition":"From Latin genialis 'festive, natural', connected with genius, not genos: in a cheerful and friendly way.","definitionCN":"来自拉丁 genialis「节庆的、天生的」，与 genius 相关，而非 genos：指和蔼愉快地。"},{"word":"generally","ipa":"/ˈdʒenərəli/","tag":"different formation","definition":"From general, built on Latin genus 'kind' but meaning 'in most cases'; it is not a genetic judgement.","definitionCN":"来自 general，虽建立在拉丁 genus「种类」上，但意为「通常」；不是遗传判断。"},{"word":"genetically modified","ipa":"/dʒəˈnetɪkli ˈmɒdɪfaɪd/","tag":"fixed phrase","definition":"The most common collocation, naming an organism whose material has been deliberately altered.","definitionCN":"最常见的搭配，指遗传物质被有意改造过的生物。"},{"word":"genetically identical","ipa":"/dʒəˈnetɪkli aɪˈdentɪkl/","tag":"fixed phrase","definition":"Sharing the same genetic material, as clones do; the adverb marks the level of identity.","definitionCN":"共享相同遗传物质，如克隆体；副词标记同一性的层面。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hereditarily","ipa":"/hɪˈredɪtərəli/","tag":"by inheritance","definition":"It stresses transmission from ancestors, while genetically can also mean 'at the level of genes' without descent.","definitionCN":"强调从祖先传递，而 genetically 也可仅指「在基因层面」，不涉及世系。"},{"word":"genotypically","ipa":"/ˌdʒiːnəˈtɪpɪkli/","tag":"by genotype","definition":"Relating to the inherited constitution at one or more loci, a narrower technical term.","definitionCN":"与一个或多个位点的遗传组成相关，是更窄的技术词。"},{"word":"phenotypically","ipa":"/ˌfiːnəˈtɪpɪkli/","tag":"by observable traits","definition":"Relating to visible or measurable traits, the opposite angle from genetically.","definitionCN":"与可见或可测性状相关，角度与 genetically 相反。"},{"word":"environmentally","ipa":"/ɪnˌvaɪrənˈmentəli/","tag":"by surroundings","definition":"Relating to external conditions rather than genes; the usual contrast in nature-nurture debates.","definitionCN":"与外部条件相关而非基因；是天性与教养争论中的常见对照。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"genetic + -al + -ly: in the manner of genes.","cn":"genetic + -al + -ly：以基因的方式。"},{"en":"The family runs gene, genetic, genetically, genetics and geneticist.","cn":"同族词包括 gene、genetic、genetically、genetics 与 geneticist。"},{"en":"Fixed phrases: genetically modified, genetically distinct, genetically determined.","cn":"固定搭配：转基因的、遗传上不同的、由遗传决定的。"},{"en":"As a sentence opener, genetically frames the whole claim.","cn":"作为句首状语，genetically 为整句断言设定框架。"},{"en":"Genetically is not environmentally: the two adverbs split nature from nurture.","cn":"genetically 与 environmentally 相对：两个副词把天性从教养中分开。"}],"abstract":[{"en":"Picture two jars with identical labels but different contents.","cn":"想象两个标签相同、内容不同的罐子。"},{"en":"Picture a barcode read while the package looks blank.","cn":"想象包装看似空白，条形码却已被读出。"},{"en":"Picture a family resemblance measured with a ruler instead of an eye.","cn":"想象用尺子而不是眼睛来测量家族相似。"}]},"examples":[{"en":"The tomatoes were genetically modified to ripen on schedule.","cn":"这些番茄经过基因改造，可按计划成熟。"},{"en":"Genetically, the two populations have been separate for centuries.","cn":"从遗传上看，这两个群体已分离数百年。"},{"en":"The rescued cubs are genetically diverse enough to breed.","cn":"获救的幼兽遗传多样性足够，可以繁育。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"gene（基因）+ tically（副词尾）——从基因角度 → 遗传上；与「转基因的」搭配时指经基因改造。","word":"genetically"},"root":"genetic + -al + -ly；genetic 来自希腊 genetikos「生殖的」← genos「种族、种类」；genos 出自原始印欧语 *ǵenh₁-（重构形式）。","sensesIntro":{"en":"Eight senses follow one viewpoint: by modification, in genetic terms, by inheritance, at the material level, through transmission, as makeup, by engineering and in classification.","cn":"八个义项沿同一个视角展开：经改造、从基因角度、由遗传决定、在物质层面、经传递、就组成而言、经工程、在分类上。"},"semanticMap":{"core":{"en":"CORE IMAGE: two trays of identical seeds, while a screen shows different internal bands.","cn":"核心意象：两盘外观相同的种子，屏幕却显示出不同的内部条带。"},"chain":["GENE","MANNER","VIEWPOINT","MEANS","LEVEL","CLASSIFICATION"],"branches":[{"senses":"S1 · S7","en":"BY MODIFICATION: the change is made deliberately at the level of the instructions.","cn":"经改造：改变是在指令层面有意作出的。"},{"senses":"S2 · S8","en":"VIEWPOINT: the judgement is made by sequences rather than by appearance or shape.","cn":"视角：判断依据序列而非外表或形态。"},{"senses":"S3 · S5","en":"CAUSE AND ROUTE: inherited influence, and transmission from parents to offspring.","cn":"原因与路径：遗传影响，以及由亲代到子代的传递。"},{"senses":"S4","en":"MATERIAL LEVEL: the comparison or action occurs on the hereditary material itself.","cn":"物质层面：比较或作用发生在遗传物质本身。"},{"senses":"S6","en":"MAKEUP: the adverb frames a statement about a group's overall constitution.","cn":"组成：副词为关于群体整体构成的陈述设定框架。"}]},"affixes":{"intro":{"en":"Genetically is a layered adverb: a Greek-derived stem, an adjective suffix, and a further adverbial ending.","cn":"genetically 是分层构成的副词：希腊来源词干、形容词后缀，再加副词词尾。"},"latinIntro":{"en":"Greek genos gives gene and genetic; -ic and -al form the adjective, and -ly forms the adverb. No Latin derivative of genetikos exists, so latinEntries is empty.","cn":"希腊 genos 衍生 gene 与 genetic；-ic 与 -al 构成形容词，-ly 构成副词。genetikos 没有拉丁派生词，因此 latinEntries 留空。"},"items":[{"word":"genos","structure":"genos (Greek noun, 'race, kind')","meaning":"race; kind","meaningCN":"种族；种类","example":"The stem names a reproducing kind.","exampleCN":"这个词干命名自我繁衍的类。"},{"word":"genetikos","structure":"genetikos (Greek adjective)","meaning":"generative","meaningCN":"生殖的；生成的","example":"The adjective described what generates.","exampleCN":"这个形容词描述能生成之物。"},{"word":"gene","structure":"genos, shortened through Danish gen","meaning":"unit of heredity","meaningCN":"基因","example":"A gene is a unit of heredity.","exampleCN":"基因是遗传单位。"},{"word":"genetic","structure":"genetikos via French, plus -ic","meaning":"relating to genes","meaningCN":"遗传的；基因的","example":"Genetic testing is routine.","exampleCN":"基因检测已很常规。"},{"word":"-ic","structure":"-ic (adjective suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix forms a relational adjective.","exampleCN":"这个后缀构成关系形容词。"},{"word":"-al","structure":"-al (adjective suffix from Latin -alis)","meaning":"of or belonging to","meaningCN":"属于……的","example":"The older genetical added -al to the same stem.","exampleCN":"较旧的 genetical 在同一词干后加 -al。"},{"word":"-ly","structure":"-ly (English adverb suffix)","meaning":"in the manner of","meaningCN":"以……方式","example":"The suffix turns the adjective into an adverb.","exampleCN":"这个后缀把形容词变成副词。"},{"word":"-ally","structure":"-al + -ly (combined adverbial ending)","meaning":"in a ... manner","meaningCN":"以……方式","example":"The combined ending gives genetically.","exampleCN":"组合词尾构成 genetically。"},{"word":"genetically","structure":"genetic + -ally","meaning":"in genetic terms","meaningCN":"遗传上；基因上","example":"The strains are genetically distinct.","exampleCN":"这些菌株在遗传上不同。"},{"word":"genetics","structure":"genetic + -ics","meaning":"the science of heredity","meaningCN":"遗传学","example":"Genetics explains inheritance.","exampleCN":"遗传学解释遗传。"},{"word":"genotype","structure":"genos + typos 'impression'","meaning":"the inherited constitution","meaningCN":"基因型","example":"The genotype was recorded.","exampleCN":"基因型被记录。"},{"word":"phenotype","structure":"phainein 'show' + typos","meaning":"the observable traits","meaningCN":"表现型","example":"The phenotype was measured.","exampleCN":"表现型被测量。"}],"latinEntries":[]}},{"word":"gene","ipa_uk":"/dʒiːn/","ipa_us":"/dʒiːn/","definition_zh":"基因；（遗传的）单位、因子","definition_en":"a unit of heredity, a segment of genetic material that carries instructions for a trait or a product","core_image":"一条长指令带被分成许多小段，每段卷起来装进一个信封，信封上写着一种性状","scene":"一条长长的指令带被分成许多小段，每段负责一个性状。A single gene carries the instructions for one inherited trait.","sceneCN":"这里 gene 指「承载某一遗传性状指令的遗传单位」（第 1 个义项：遗传的基本单位）；句意为一个基因承载一种遗传性状的指令。可辨识物件：长纸条、剪刀、信封、性状标签、放大镜。","pos":[{"tag":"n.","zh":"基因；遗传单位"},{"tag":"n.","zh":"（特定性状的）基因、等位基因（口语）"}],"collocations":[{"phrase":"a gene for","zh":"决定……的基因"},{"phrase":"gene expression","zh":"基因表达"},{"phrase":"gene therapy","zh":"基因治疗"},{"phrase":"gene pool","zh":"基因库"},{"phrase":"dominant gene","zh":"显性基因"},{"phrase":"gene editing","zh":"基因编辑"}],"forms":[{"label":"复数","form":"genes"},{"label":"所有格","form":"gene's"},{"label":"形容词","form":"genetic"},{"label":"名词（基因组）","form":"genome"}],"derivatives":[{"word":"genetic","pos":"adj.","zh":"遗传的；基因的"},{"word":"genetics","pos":"n.","zh":"遗传学"},{"word":"genome","pos":"n.","zh":"基因组"},{"word":"genotype","pos":"n.","zh":"基因型"}],"senses":[{"no":"01","title":"A unit of heredity","titleCN":"遗传的基本单位","definition":"a unit of heredity that is passed from parents to offspring","definitionCN":"由亲代传给子代的遗传单位","example":"A gene is a segment of sequence that codes for a product.","exampleCN":"基因是一段编码某种产物的序列。","why":"The word was coined for a unit, so its core sense is countable: one gene, many genes.","whyCN":"这个词是为「单位」而造的，因此核心义可数：一个基因、许多基因。"},{"no":"02","title":"A specific inherited factor","titleCN":"决定某一性状的特定基因","definition":"the particular genetic factor responsible for a trait","definitionCN":"造成某一性状的特定遗传因子","example":"The gene for red hair is recessive.","exampleCN":"决定红发的基因是隐性的。","why":"Everyday usage compresses 'a variant at a locus' into 'the gene for a trait', which is convenient but imprecise.","whyCN":"日常用法把「某位点的变异」压缩成「决定某性状的基因」，方便但不精确。"},{"no":"03","title":"A molecular region","titleCN":"分子意义上的基因区域","definition":"a stretch of genetic material that includes coding and control regions","definitionCN":"一段包含编码区与控制区的遗传物质","example":"The gene includes control regions as well as coding regions.","exampleCN":"基因既包含编码区，也包含控制区。","why":"Molecular biology widened the unit from a bead of inheritance to a region with switches and boundaries.","whyCN":"分子生物学把这个单位从一颗遗传珠子扩展为带有开关与边界的一段区域。"},{"no":"04","title":"A variant or allele","titleCN":"基因变体、等位基因","definition":"one of the alternative forms of a gene at a given locus","definitionCN":"某一位点上基因的备选形式之一","example":"Some people carry a gene that protects against malaria.","exampleCN":"有些人携带一种可预防疟疾的基因变体。","why":"Strictly the variant is an allele; loose usage calls any version a gene, and this sense is common in health writing.","whyCN":"严格说变体是等位基因；宽松用法把任何版本都叫基因，这一义在健康写作中很常见。"},{"no":"05","title":"A target for gene therapy","titleCN":"基因治疗的靶标","definition":"a gene delivered or repaired to treat a disease","definitionCN":"为治疗疾病而递送或修复的基因","example":"Doctors delivered a working gene to the patient's cells.","exampleCN":"医生把一份有功能的基因送入患者细胞。","why":"The therapeutic sense treats the gene as a object to be inserted, which follows from its definition as a segment of instructions.","whyCN":"治疗义把基因当作可插入的对象，这来自它作为「一段指令」的定义。"},{"no":"06","title":"An object of study","titleCN":"作为研究对象的基因","definition":"a gene chosen for laboratory study because of its role in a process","definitionCN":"因在某一过程中的作用而被选作实验对象的基因","example":"The lab studies a gene involved in nerve growth.","exampleCN":"实验室研究一个参与神经生长的基因。","why":"Laboratories speak of 'a gene' as a manageable piece of a much larger sequence, which is why the singular is so common.","whyCN":"实验室把「一个基因」说成更大序列中可处理的一块，因此单数用法非常普遍。"},{"no":"07","title":"A gene in the gene pool","titleCN":"基因库中的基因","definition":"a version of a gene considered as part of a population's stored variation","definitionCN":"把某一基因版本视作群体储存变异的一部分","example":"The gene is rare in the northern gene pool.","exampleCN":"这个基因在北方基因库中很罕见。","why":"Population thinking shifts the unit from an individual's instruction to a frequency in a shared store.","whyCN":"群体思维把这个单位从个体的指令转为共享储存中的频率。"},{"no":"08","title":"The selfish-gene view","titleCN":"「自私的基因」视角","definition":"a gene treated as the unit on which selection acts","definitionCN":"被视作自然选择作用单位的基因","example":"The idea of the selfish gene reframed behaviour.","exampleCN":"「自私的基因」这一观念重塑了行为研究。","why":"The metaphor makes the gene the central actor, a perspective that is debated rather than settled.","whyCN":"这个隐喻让基因成为中心行动者，这一视角仍有争论，并非定论。"}],"etymology":{"intro":{"en":"Gene was coined by Wilhelm Johannsen from Danish gen and German Gen, shortened from de Vries's pangene, which joined Greek pan 'all' with genos 'race, kind'. The German coinage is variously dated 1905 and 1909, and English gene is recorded by 1911.","cn":"gene 由威廉·约翰森据丹麦语 gen 与德语 Gen 造出，二者是德弗里斯 pangene 的缩短形式，而 pangene 由希腊 pan「全部」加 genos「种族、种类」构成。德语造词年代有 1905 与 1909 两说，英语 gene 在 1911 年前已有记录。"},"items":[{"era":"GREEK GENOS","en":"Genos 'race, kind, birth' belongs to the PIE family reconstructed as *ǵenh₁-, so the root form is a reconstruction; Latin genus is a cognate, not the source.","cn":"genos「种族、种类、出生」属于被重构为 *ǵenh₁- 的原始印欧语词族，因此该词根形式是重构；拉丁 genus 是同源词，并非来源。"},{"era":"PANGENE","en":"Hugo de Vries proposed pangene for imagined particles of heredity, joining pan 'all' with genos; the particles themselves were never observed.","cn":"胡戈·德弗里斯提出 pangene 指想象中的遗传颗粒，由 pan「全部」加 genos 构成；这些颗粒本身从未被观察到。"},{"era":"DANISH AND GERMAN","en":"Johannsen used Danish gen and German Gen in the first decade of the twentieth century, shortening the earlier compound to a single syllable; the German date is given as either 1905 or 1909.","cn":"约翰森在 20 世纪头十年使用丹麦语 gen 与德语 Gen，把较早的复合词缩短为一个音节；德语年代有 1905 与 1909 两说。"},{"era":"ENGLISH GENE","en":"English adopted gene by 1911; the exact first English citation is not settled, but the date is usually placed in that year.","cn":"英语在 1911 年前已采用 gene；确切的最早英语书证尚未定论，但年代通常定在该年。"},{"era":"MOLECULAR RESHAPING","en":"Once the structure of the molecule was known, gene was redefined as a stretch of sequence rather than a particle.","cn":"当分子结构被弄清后，gene 被重新定义为一段序列，而非一颗颗粒。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (route and first date): the shortening from pangene is generally considered correct but not fully documented, and no Latin derivative exists, so latinEntries is empty.","cn":"来源不确定（路径与首见年代）：从 pangene 缩短而来一般认为正确，但没有完整文献记录；且不存在拉丁派生词，因此 latinEntries 留空。"}]},"similar":{"note":{"en":"Group one separates gene from same-root terms and one accidental sound-alike; group two separates it from the neighbouring units and concepts.","cn":"第一组把 gene 与同根词及一个偶然音近词分开；第二组把它与相邻的单位和概念区分。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"genome","ipa":"/ˈdʒiːnəʊm/","tag":"same root, the whole set","definition":"The whole set of genetic material; a gene is one segment within it.","definitionCN":"指全部遗传物质；基因是其中的一个片段。"},{"word":"genotype","ipa":"/ˈdʒiːnətaɪp/","tag":"same root, the constitution","definition":"The inherited constitution at one or more loci; a genotype is a combination, not a single segment.","definitionCN":"指一个或多个位点的遗传组成；基因型是组合，不是单个片段。"},{"word":"genera","ipa":"/ˈdʒenərə/","tag":"same root, a plural","definition":"The plural of genus, a taxonomic rank; it belongs to classification, not to molecular segments.","definitionCN":"genus 的复数，是分类阶元；属于分类学，而非分子片段。"},{"word":"genie","ipa":"/ˈdʒiːni/","tag":"different root","definition":"From Arabic jinn, not from genos: a spirit of folklore. The resemblance is only in sound.","definitionCN":"来自阿拉伯语 jinn，并非 genos：指民间传说中的精灵。相似仅在读音。"}]},{"heading":"NEAR MEANING","entries":[{"word":"allele","ipa":"/əˈliːl/","tag":"one version at a locus","definition":"One of the alternative forms of a gene; the precise term for what loose usage calls a gene variant.","definitionCN":"基因在某一位点的备选形式之一；是「基因变体」这一宽松说法的精确术语。"},{"word":"locus","ipa":"/ˈləʊkəs/","tag":"the position","definition":"The fixed position of a gene on a chromosome; it names the address rather than the instruction.","definitionCN":"基因在染色体上的固定位置；命名地址而非指令。"},{"word":"chromosome","ipa":"/ˈkrəʊməsəʊm/","tag":"the carrier","definition":"The structure that carries many genes; it is larger than a gene and contains many of them.","definitionCN":"承载许多基因的结构；比基因大，并包含许多基因。"},{"word":"trait","ipa":"/treɪt/","tag":"the observed feature","definition":"The observable characteristic produced with the help of genes; a gene is the instruction, a trait is the result.","definitionCN":"在基因作用下产生的可观察特征；基因是指令，性状是结果。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Greek genos 'kind': the unit that makes offspring the same kind.","cn":"希腊 genos「种类」：使后代成为同类的那一单位。"},{"en":"The family runs gene, genetic, genetics, genome and genotype.","cn":"同族词包括 gene、genetic、genetics、genome 与 genotype。"},{"en":"Johannsen coined the word from Danish gen, usually dated around 1905-1909.","cn":"约翰森据丹麦语 gen 造出这个词，年代通常定在 1905 至 1909 年间。"},{"en":"Strictly, variants at a locus are alleles, not separate genes.","cn":"严格说，位点上的变体是等位基因，而非独立的基因。"},{"en":"Gene editing and gene therapy treat the gene as an object to be changed.","cn":"基因编辑与基因治疗把基因当作可改变的对象。"}],"abstract":[{"en":"Picture one sentence cut out of a very long book and placed in an envelope.","cn":"想象从一本很长的书里剪下一句话，装进信封。"},{"en":"Picture a library where each volume is a gene and the whole shelf is a genome.","cn":"想象一座图书馆，每本书是一个基因，整排书架是一个基因组。"},{"en":"Picture a switch inside a locked room that changes what the whole house does.","cn":"想象锁着的房间里有一个开关，改变整座房子的运作。"}]},"examples":[{"en":"The gene was first identified in a fruit fly.","cn":"这个基因最早在果蝇中被识别。"},{"en":"Mutations in that gene can alter the shape of the wing.","cn":"该基因的突变能改变翅膀形状。"},{"en":"Gene therapy remains experimental for most inherited disorders.","cn":"对多数遗传病而言，基因治疗仍属实验性。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"gene 音近「基因」——汉语译名就是音译；一个基因一段指令。","word":"gene"},"root":"希腊 genos「种族、种类」← 原始印欧语 *ǵenh₁-（重构形式）；经德弗里斯 pangene、约翰森据丹麦语 gen 缩短而来（德语造词有 1905 与 1909 两说）；拉丁 genus 为同源词，非来源。","sensesIntro":{"en":"Eight senses follow one segment of instructions: a unit, a factor for a trait, a molecular region, a variant, a therapeutic object, a laboratory object, a pool member and a unit of selection.","cn":"八个义项沿一段指令展开：一个单位、一个性状因子、一个分子区域、一个变体、一个治疗对象、一个实验对象、一个库成员、一个选择单位。"},"semanticMap":{"core":{"en":"CORE IMAGE: one sentence cut from a long tape and filed under a trait.","cn":"核心意象：从长纸条上剪下一句，归档在一个性状之下。"},"chain":["KIND","UNIT OF HEREDITY","TRAIT FACTOR","SEQUENCE REGION","VARIANT","OBJECT OF ACTION"],"branches":[{"senses":"S1 · S2","en":"UNIT AND FACTOR: a countable unit, and the factor singled out for a trait.","cn":"单位与因子：可数的单位，以及为某性状单独指出的因子。"},{"senses":"S3","en":"MOLECULAR REGION: a stretch with coding and control parts, not a bead.","cn":"分子区域：带编码与控制部分的一段，而非一颗珠子。"},{"senses":"S4 · S7","en":"VARIANT AND POOL: alternative versions, and their frequency in a shared store.","cn":"变体与库：备选版本，以及它们在共享储存中的频率。"},{"senses":"S5 · S6","en":"OBJECT OF ACTION: something delivered in therapy or studied in the lab.","cn":"作用对象：治疗中递送之物，或实验室研究之物。"},{"senses":"S8","en":"UNIT OF SELECTION: the gene pictured as the actor on which selection works.","cn":"选择单位：被想象为自然选择作用对象的基因。"}]},"affixes":{"intro":{"en":"Gene is a modern shortening of a Greek-derived compound; its stem builds the entire vocabulary of heredity, and its suffixes mark the science, the adjective and the person.","cn":"gene 是希腊来源复合词的现代缩短形式；其词干构成整套遗传词汇，后缀标记学科、形容词与从业者。"},"latinIntro":{"en":"Greek genos gives gene, genetic, genetics, genome and genotype; pan- 'all' formed the earlier pangene. No Latin derivative exists, so latinEntries is empty.","cn":"希腊 genos 衍生 gene、genetic、genetics、genome 与 genotype；pan-「全部」构成较早的 pangene。不存在拉丁派生词，因此 latinEntries 留空。"},"items":[{"word":"genos","structure":"genos (Greek noun, 'race, kind')","meaning":"race; kind; birth","meaningCN":"种族；种类；出生","example":"The stem names a kind that reproduces itself.","exampleCN":"这个词干命名自我繁衍的类。"},{"word":"pan-","structure":"pan- (Greek prefix, 'all')","meaning":"all; whole","meaningCN":"全部；整体","example":"De Vries joined pan- to genos for pangene.","exampleCN":"德弗里斯把 pan- 加 genos 构成 pangene。"},{"word":"pangene","structure":"pan- + genos (de Vries, 1889)","meaning":"imagined particle of heredity","meaningCN":"想象中的遗传颗粒","example":"Pangene was shortened by later writers.","exampleCN":"pangene 被后来的作者缩短。"},{"word":"gen","structure":"gen (Danish and German shortening)","meaning":"gene","meaningCN":"基因","example":"Johannsen used gen in the first decade of the twentieth century.","exampleCN":"约翰森在 20 世纪头十年使用了 gen。"},{"word":"gene","structure":"English from Danish gen and German Gen","meaning":"unit of heredity","meaningCN":"基因","example":"A gene carries instructions.","exampleCN":"基因承载指令。"},{"word":"genetic","structure":"genetikos via French, plus -ic","meaning":"relating to genes","meaningCN":"遗传的；基因的","example":"Genetic testing is routine.","exampleCN":"基因检测已很常规。"},{"word":"genetics","structure":"genetic + -ics","meaning":"the science of heredity","meaningCN":"遗传学","example":"Genetics explains inheritance.","exampleCN":"遗传学解释遗传。"},{"word":"geneticist","structure":"genetics + -ist","meaning":"a specialist in genetics","meaningCN":"遗传学家","example":"The geneticist mapped the region.","exampleCN":"这位遗传学家绘制了该区域。"},{"word":"genome","structure":"gene + -ome, modelled on chromosome","meaning":"the whole set of genes","meaningCN":"基因组","example":"The genome was sequenced.","exampleCN":"基因组被测序。"},{"word":"genotype","structure":"genos + typos 'impression'","meaning":"the inherited constitution","meaningCN":"基因型","example":"The genotype was recorded.","exampleCN":"基因型被记录。"},{"word":"genomics","structure":"genome + -ics","meaning":"the study of whole genomes","meaningCN":"基因组学","example":"Genomics compares complete sequences.","exampleCN":"基因组学比较完整序列。"}],"latinEntries":[]}},{"word":"genome","ipa_uk":"/ˈdʒiːnəʊm/","ipa_us":"/ˈdʒiːnoʊm/","definition_zh":"基因组；一套完整的遗传物质","definition_en":"the complete set of genetic material in a cell, organism or species","core_image":"一份厚得像电话簿的目录，里面装着构成一个身体所需的全部指令","scene":"把一个人的全部遗传指令装进一份目录，厚得像电话簿。The human genome contains every instruction needed to build a body.","sceneCN":"这里 genome 指「一个生物体或物种的全套遗传物质」（第 1 个义项：完整的遗传物质集合）；句意为人类基因组包含构建一个身体所需的全部指令。可辨识物件：厚目录、索引标签、染色体示意图、书签。","pos":[{"tag":"n.","zh":"基因组；全套遗传物质"}],"collocations":[{"phrase":"the human genome","zh":"人类基因组"},{"phrase":"genome sequencing","zh":"基因组测序"},{"phrase":"genome project","zh":"基因组计划"},{"phrase":"viral genome","zh":"病毒基因组"},{"phrase":"genome size","zh":"基因组大小"},{"phrase":"genome editing","zh":"基因组编辑"}],"forms":[{"label":"复数","form":"genomes"},{"label":"所有格","form":"genome's"},{"label":"形容词","form":"genomic"},{"label":"名词（基因组学）","form":"genomics"}],"derivatives":[{"word":"genomic","pos":"adj.","zh":"基因组的"},{"word":"genomics","pos":"n.","zh":"基因组学"},{"word":"genomically","pos":"adv.","zh":"在基因组层面"},{"word":"genotype","pos":"n.","zh":"基因型"}],"senses":[{"no":"01","title":"The complete genetic material","titleCN":"完整的遗传物质集合","definition":"the entire set of genetic material in a cell or organism","definitionCN":"细胞或生物体内全部遗传物质的总和","example":"The human genome contains every instruction needed to build a body.","exampleCN":"人类基因组包含构建一个身体所需的全部指令。","why":"The word was coined for the whole set, so its core sense is collective: one genome per cell or species, not one per trait.","whyCN":"这个词是为「整套」而造的，因此核心义是集合性的：每个细胞或物种一个基因组，而不是每个性状一个。"},{"no":"02","title":"A sequenced genome","titleCN":"已测序的基因组","definition":"the genome of an organism as read out in sequence data","definitionCN":"以序列数据形式读出的某生物基因组","example":"The first genome of a fruit fly was published in 2000.","exampleCN":"果蝇的第一个基因组于 2000 年公布。","why":"Once sequencing became possible, the word came to mean the published read-out as well as the biological set.","whyCN":"当测序成为可能后，这个词既指生物学的集合，也指公布的读出结果。"},{"no":"03","title":"A genome as a dataset","titleCN":"作为数据集的基因组","definition":"a collection of sequences from many individuals used for comparison","definitionCN":"用于比较的、来自许多个体的序列集合","example":"Researchers compared genomes from a thousand patients.","exampleCN":"研究者比较了一千名患者的基因组。","why":"In data work the singular expands to many files: a 'genome' can mean the assembled dataset of one individual.","whyCN":"在数据工作中，单数扩展到许多文件：一个「基因组」可指某个体组装好的数据集。"},{"no":"04","title":"A viral genome","titleCN":"病毒基因组","definition":"the genetic material of a virus, often a single RNA or DNA molecule","definitionCN":"病毒的遗传物质，常为单个核糖核酸或脱氧核糖核酸分子","example":"The viral genome is only a few thousand units long.","exampleCN":"病毒基因组只有几千个单位长。","why":"Viruses have genomes too, so the term crosses the boundary between cellular life and its parasites.","whyCN":"病毒也有基因组，因此这个术语跨越了细胞生命与其寄生者的边界。"},{"no":"05","title":"Genome organization","titleCN":"基因组的组织方式","definition":"the way genetic material is arranged and packed in a cell","definitionCN":"遗传物质在细胞中排列与包装的方式","example":"The genome is packed into chromosomes.","exampleCN":"基因组被包装进染色体。","why":"The word can name the arrangement, not only the contents, which is why genomes have sizes and structures.","whyCN":"这个词也能命名排列方式，而不只是内容，因此基因组有大小与结构。"},{"no":"06","title":"A genome project","titleCN":"基因组计划","definition":"a large coordinated effort to sequence a species' genome","definitionCN":"为测定某一物种基因组而进行的大型协作","example":"The genome project finished ahead of schedule.","exampleCN":"这项基因组计划提前完成。","why":"Big science turned the word into a project name, so 'the genome' can mean the effort as well as the object.","whyCN":"大科学把这个词变成项目名，因此「基因组」也可指这项工程，而不只是对象。"},{"no":"07","title":"Genome size","titleCN":"基因组大小","definition":"the total amount of genetic material in a genome, often measured in base pairs","definitionCN":"基因组中遗传物质的总量，常以碱基对计量","example":"Genome size does not track organism complexity.","exampleCN":"基因组大小并不随生物复杂度变化。","why":"Measuring a genome requires treating it as a quantity, which produces the size sense.","whyCN":"测量基因组需要把它当作一个量，于是产生「大小」这一义。"},{"no":"08","title":"A target for genome editing","titleCN":"基因组编辑的对象","definition":"the whole set of material that can be altered at precise sites","definitionCN":"可在精确位点被改变的全部遗传物质","example":"The genome can now be edited at precise sites.","exampleCN":"基因组如今可以在精确位点被编辑。","why":"Editing acts on the set rather than on one gene, so the word names the scope of the intervention.","whyCN":"编辑作用于整套而非单个基因，因此这个词命名干预的范围。"}],"etymology":{"intro":{"en":"Genome was coined by Hans Winkler in 1920 as German Genom, usually explained as a blend of Gen 'gene' and Chromosom 'chromosome'.","cn":"genome 由汉斯·温克勒于 1920 年以德语 Genom 造出，通常解释为 Gen「基因」与 Chromosom「染色体」的混成词。"},"items":[{"era":"GREEK GENOS","en":"Genos 'race, kind' belongs to the PIE family reconstructed as *ǵenh₁-; the root form is a reconstruction, and Latin genus is a cognate rather than the source.","cn":"genos「种族、种类」属于被重构为 *ǵenh₁- 的原始印欧语词族；该词根形式是重构，拉丁 genus 是同源词而非来源。"},{"era":"SUFFIX -OME","en":"The suffix -ome, extracted from chromosome, marks a complete set. Chromosome itself joins Greek chroma 'colour' and soma 'body'.","cn":"后缀 -ome 从 chromosome 中析出，标记一个完整集合。chromosome 本身由希腊 chroma「颜色」与 soma「身体」构成。"},{"era":"GERMAN COINAGE","en":"Hans Winkler coined German Genom in 1920; it is generally considered a blend of Gen and Chromosom, though that reading remains an interpretation of his intention.","cn":"汉斯·温克勒于 1920 年造出德语 Genom；一般认为它是 Gen 与 Chromosom 的混成，但这一读法仍是对其意图的解释。"},{"era":"ENGLISH ADOPTION","en":"English genome is recorded by 1930 and spread widely later in the twentieth century with sequencing projects; the first English citation is often dated to that year.","cn":"英语 genome 在 1930 年前已有记录，20 世纪后期随测序计划广泛传播；最早的英语书证常定在该年。"},{"era":"MODERN WIDENING","en":"The meaning widened from a set of genes to the entire sequence of a cell or species, including non-coding regions.","cn":"词义从「一组基因」扩展到细胞或物种的全部序列，包括非编码区域。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (coinage details): the 1920 date is documented, but the blend account is an interpretation, and the pre-Latin root form is a reconstruction.","cn":"来源不确定（造词细节）：1920 年这一年代有文献可查，但混成说法属于解释，且拉丁语之前的词根形式是重构。"}]},"similar":{"note":{"en":"Group one separates genome from same-root terms and one accidental sound-alike; group two separates it from the neighbouring whole-set and carrier terms.","cn":"第一组把 genome 与同根词及一个偶然音近词分开；第二组把它与相邻的「整套」和「载体」术语区分。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"gene","ipa":"/dʒiːn/","tag":"same root, the unit","definition":"One segment of instructions; a genome is the complete set of such segments.","definitionCN":"指一段指令；基因组是这类片段的完整集合。"},{"word":"genotype","ipa":"/ˈdʒiːnətaɪp/","tag":"same root, the constitution","definition":"The inherited constitution at one or more loci; a genome is the whole material, not a combination at a locus.","definitionCN":"指一个或多个位点的遗传组成；基因组是全部物质，而非某位点的组合。"},{"word":"genomics","ipa":"/dʒəˈnɒmɪks/","tag":"same root, the science","definition":"The study of genomes; genome is the object, genomics is the discipline.","definitionCN":"研究基因组的学科；genome 是对象，genomics 是学科。"},{"word":"gnome","ipa":"/nəʊm/","tag":"different root","definition":"A garden ornament or a folklore figure; its origin is not related to genos. The resemblance is only in spelling and sound.","definitionCN":"指花园装饰或民间传说人物；其来源与 genos 无关。相似仅在拼写与读音。"}]},{"heading":"NEAR MEANING","entries":[{"word":"chromosome","ipa":"/ˈkrəʊməsəʊm/","tag":"the carrier","definition":"A structure that carries part of the genome; a genome is the total material, packaged into chromosomes.","definitionCN":"承载部分基因组的结构；基因组是被包装进染色体的全部物质。"},{"word":"genotype","ipa":"/ˈdʒiːnətaɪp/","tag":"the constitution","definition":"The inherited constitution, especially at specified loci; the genome is the full sequence.","definitionCN":"指遗传组成，尤指特定位点；基因组是完整序列。"},{"word":"transcriptome","ipa":"/trænˈskrɪptəʊm/","tag":"the expressed subset","definition":"The set of all RNA transcripts; it is a subset of what the genome contains, not the genome itself.","definitionCN":"全部核糖核酸转录本的集合；是基因组内容的一部分，而非基因组本身。"},{"word":"proteome","ipa":"/ˈprəʊtiəʊm/","tag":"the protein set","definition":"The complete set of proteins produced; it is downstream of the genome and not the same object.","definitionCN":"所产生的全部蛋白质集合；位于基因组下游，并非同一对象。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"gene + -ome: the whole set of genes.","cn":"gene + -ome：全部基因的集合。"},{"en":"The family runs gene, genome, genomic, genomics and genotype.","cn":"同族词包括 gene、genome、genomic、genomics 与 genotype。"},{"en":"Winkler coined Genom in 1920 as gene plus chromosome.","cn":"温克勒于 1920 年以 gene 加 chromosome 造出 Genom。"},{"en":"Genome size is measured in base pairs, not in gene counts.","cn":"基因组大小以碱基对计量，而非以基因数计量。"},{"en":"Genomics is the science; the genome is its object.","cn":"genomics 是学科；genome 是它的对象。"}],"abstract":[{"en":"Picture a phone book that contains every instruction for building a city.","cn":"想象一本电话簿，装着建造一座城市所需的全部指令。"},{"en":"Picture a library shelf treated as one catalogue entry.","cn":"想象整排书架被当作一条目录记录。"},{"en":"Picture a map that includes empty streets as well as named ones.","cn":"想象一张地图，既有命名街道，也有空白街道。"}]},"examples":[{"en":"The genome was assembled from millions of short reads.","cn":"这个基因组由数百万条短读段组装而成。"},{"en":"Viral genomes mutate faster than most cellular genomes.","cn":"病毒基因组比多数细胞基因组突变得更快。"},{"en":"Genome size varies widely among flowering plants.","cn":"开花植物的基因组大小差异很大。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"gene（基因）+ ome（整体）——全部基因装在一起 → 基因组；-ome 来自 chromosome。","word":"genome"},"root":"德语 Genom（温克勒，1920）＝Gen「基因」+ Chromosom「染色体」的混成；gen 源于希腊 genos「种族、种类」，genos 出自原始印欧语 *ǵenh₁-（重构形式）。","sensesIntro":{"en":"Eight senses follow one complete set: the material, its sequenced read-out, its data form, its viral version, its packing, its project, its size and its edited scope.","cn":"八个义项沿一个完整集合展开：物质本身、测序读出、数据形式、病毒版本、包装方式、计划、大小与可编辑范围。"},"semanticMap":{"core":{"en":"CORE IMAGE: a phone-book-thick catalogue holding every instruction for a body.","cn":"核心意象：一本电话簿厚的目录，装着构建一个身体所需的全部指令。"},"chain":["GENE","CHROMOSOME","COMPLETE SET","SEQUENCED READ-OUT","PACKED STRUCTURE","EDITABLE SCOPE"],"branches":[{"senses":"S1 · S5","en":"THE WHOLE SET: all the material, and the way it is packed.","cn":"整套：全部物质，以及它的包装方式。"},{"senses":"S2 · S3","en":"READ-OUT AND DATA: the published sequence and the assembled dataset.","cn":"读出与数据：公布的序列与组装好的数据集。"},{"senses":"S4","en":"VIRAL VERSION: the term crosses into parasites with their own material.","cn":"病毒版本：这个术语跨入拥有自身物质的寄生者。"},{"senses":"S6 · S7","en":"PROJECT AND SIZE: the word as an effort, and as a quantity to measure.","cn":"计划与大小：作为工程，以及作为可测量的量。"},{"senses":"S8","en":"EDITABLE SCOPE: the full set as the range of intervention.","cn":"可编辑范围：作为干预范围的全套物质。"}]},"affixes":{"intro":{"en":"Genome joins a Greek-derived stem to a suffix extracted from chromosome, and the pair builds the vocabulary of whole-set biology.","cn":"genome 把希腊来源词干与从 chromosome 析出的后缀结合，这一组合构成整套生物学的词汇。"},"latinIntro":{"en":"Greek genos gives gene; -ome, from chromosome, marks a complete set. Genome then yields genomic and genomics. No Latin derivative exists, so latinEntries is empty.","cn":"希腊 genos 衍生 gene；来自 chromosome 的 -ome 标记完整集合。genome 再衍生 genomic 与 genomics。不存在拉丁派生词，因此 latinEntries 留空。"},"items":[{"word":"genos","structure":"genos (Greek noun, 'race, kind')","meaning":"race; kind","meaningCN":"种族；种类","example":"The stem names a kind that reproduces itself.","exampleCN":"这个词干命名自我繁衍的类。"},{"word":"-ome","structure":"-ome (suffix extracted from chromosome)","meaning":"complete set","meaningCN":"完整集合","example":"The suffix marks a whole collection.","exampleCN":"这个后缀标记一个完整集合。"},{"word":"chromosome","structure":"chroma 'colour' + soma 'body' (Greek)","meaning":"the coloured body that carries genes","meaningCN":"承载基因的染色小体","example":"Chromosome supplied the -ome element.","exampleCN":"chromosome 提供了 -ome 这一成分。"},{"word":"gene","structure":"genos, shortened through Danish gen","meaning":"unit of heredity","meaningCN":"基因","example":"A gene is a unit of heredity.","exampleCN":"基因是遗传单位。"},{"word":"genome","structure":"Gen + Chromosom (German Genom, 1920)","meaning":"the complete set of genes","meaningCN":"基因组","example":"The genome was sequenced.","exampleCN":"基因组被测序。"},{"word":"genomic","structure":"genome + -ic","meaning":"relating to a genome","meaningCN":"基因组的","example":"Genomic data arrived quickly.","exampleCN":"基因组数据很快到达。"},{"word":"genomics","structure":"genome + -ics","meaning":"the study of whole genomes","meaningCN":"基因组学","example":"Genomics compares complete sequences.","exampleCN":"基因组学比较完整序列。"},{"word":"genomically","structure":"genomic + -ally","meaning":"at the genome level","meaningCN":"在基因组层面","example":"The samples were compared genomically.","exampleCN":"样本在基因组层面做了比较。"},{"word":"genotype","structure":"genos + typos 'impression'","meaning":"the inherited constitution","meaningCN":"基因型","example":"The genotype was recorded.","exampleCN":"基因型被记录。"},{"word":"phenotype","structure":"phainein 'show' + typos","meaning":"the observable traits","meaningCN":"表现型","example":"The phenotype was measured.","exampleCN":"表现型被测量。"}],"latinEntries":[]}},{"word":"genomic","ipa_uk":"/dʒɪˈnəʊmɪk/","ipa_us":"/dʒəˈnoʊmɪk/","definition_zh":"基因组的；与整套遗传物质有关的","definition_en":"relating to a genome or to the study of whole sets of genetic material","core_image":"一台机器同时读出成千上万段指令，屏幕上是一整面密密的条带","scene":"一台机器同时读出成千上万段遗传密码。Genomic data now arrive faster than any single laboratory can interpret.","sceneCN":"这里 genomic 指「与整个基因组有关的」（第 1 个义项：与基因组相关的）；句意为基因组数据到来的速度超过任何单一实验室的解读能力。可辨识物件：测序仪、密集条带屏幕、样本盘、数据线。","pos":[{"tag":"adj.","zh":"基因组的；全基因组层面的"}],"collocations":[{"phrase":"genomic data","zh":"基因组数据"},{"phrase":"genomic sequencing","zh":"基因组测序"},{"phrase":"genomic medicine","zh":"基因组医学"},{"phrase":"genomic variation","zh":"基因组变异"},{"phrase":"genomic research","zh":"基因组研究"},{"phrase":"genomic selection","zh":"基因组选择"}],"forms":[{"label":"副词","form":"genomically"},{"label":"名词（基因组）","form":"genome"},{"label":"名词（基因组学）","form":"genomics"},{"label":"比较级（少用）","form":"more genomic"},{"label":"最高级（少用）","form":"most genomic"}],"derivatives":[{"word":"genome","pos":"n.","zh":"基因组"},{"word":"genomics","pos":"n.","zh":"基因组学"},{"word":"genomically","pos":"adv.","zh":"在基因组层面"},{"word":"genomicist","pos":"n.","zh":"基因组学研究者（非正式）"}],"senses":[{"no":"01","title":"Relating to a genome","titleCN":"与基因组相关的","definition":"relating to the complete set of genetic material of an organism","definitionCN":"与一个生物体全部遗传物质相关","example":"Genomic analysis compared every gene in the two strains.","exampleCN":"基因组分析比较了两个菌株中的每一个基因。","why":"The adjective marks the whole-set level, so it is used even when individual genes are mentioned inside the study.","whyCN":"这个形容词标记整套层面，因此即使研究内部提到单个基因，也仍用它来限定整体。"},{"no":"02","title":"Of genomic sequencing","titleCN":"基因组测序的","definition":"relating to the reading of a complete set of sequences","definitionCN":"与读取整套序列相关","example":"Genomic sequencing produced millions of short reads.","exampleCN":"基因组测序产生了数百万条短读段。","why":"Sequencing gave the adjective its most common noun: the technique reads the set at once rather than gene by gene.","whyCN":"测序给了这个形容词最常见的搭配：该技术一次读取整套，而非逐个基因读取。"},{"no":"03","title":"Of genomic medicine","titleCN":"基因组医学的","definition":"relating to medical care guided by whole-genome information","definitionCN":"与由全基因组信息指导的医疗相关","example":"Genomic medicine matches drugs to a patient's variants.","exampleCN":"基因组医学把药物与患者的变体相匹配。","why":"When the set informs treatment, the adjective moves from research to the clinic without changing its scale.","whyCN":"当整套信息用于治疗，这个形容词从研究走向临床，尺度并未改变。"},{"no":"04","title":"Of genomic data","titleCN":"基因组数据的","definition":"relating to the large datasets produced by reading genomes","definitionCN":"与读取基因组所产生的大数据集相关","example":"Genomic data raise questions of privacy.","exampleCN":"基因组数据引发隐私问题。","why":"The data sense is about volume and sensitivity, which is why privacy follows genomic so naturally.","whyCN":"数据义关乎体量与敏感性，因此隐私问题会如此自然地跟随 genomic。"},{"no":"05","title":"Of genomic variation","titleCN":"基因组变异的","definition":"relating to differences across whole genomes","definitionCN":"与整条基因组之间的差异相关","example":"Genomic variation explains why siblings differ.","exampleCN":"基因组变异解释了兄弟姐妹为何不同。","why":"The adjective expands variation from one locus to the whole set, so it can explain differences that single genes cannot.","whyCN":"这个形容词把变异从一个位点扩展到整套，因此能解释单基因无法解释的差异。"},{"no":"06","title":"Of genomic research","titleCN":"基因组研究的","definition":"relating to research conducted at the scale of whole genomes","definitionCN":"与在全基因组尺度上进行的研究相关","example":"Genomic research now spans every branch of biology.","exampleCN":"基因组研究如今遍及生物学的每个分支。","why":"Because every organism has a genome, the adjective travels across fields that otherwise share little.","whyCN":"因为每种生物都有基因组，这个形容词能跨越原本共享甚少的领域。"},{"no":"07","title":"At whole-genome scale","titleCN":"全基因组尺度的","definition":"carried out across the entire set rather than at single sites","definitionCN":"在整套层面而非单个位点进行","example":"The study worked at genomic scale rather than gene by gene.","exampleCN":"这项研究在全基因组尺度上开展，而非逐个基因进行。","why":"Here the adjective names a scale of work, not a kind of object, so it contrasts with single-locus studies.","whyCN":"这里这个形容词命名工作尺度，而非对象种类，因此与单位点研究相对。"},{"no":"08","title":"Of genomic selection","titleCN":"基因组选择的","definition":"relating to breeding decisions based on whole-genome predictions","definitionCN":"与基于全基因组预测的育种决策相关","example":"Genomic selection ranks bulls by predicted breeding value.","exampleCN":"基因组选择按预测育种值给公牛排序。","why":"In breeding, the set becomes a prediction tool: many markers are combined into one score.","whyCN":"在育种中，整套信息成为预测工具：许多标记被合并为一个分数。"}],"etymology":{"intro":{"en":"Genomic is genome plus the relational suffix -ic. Genome was coined in German in 1920, and genomic followed as the adjective of whole-genome work.","cn":"genomic 是 genome 加关系后缀 -ic 构成。genome 于 1920 年以德语造出，genomic 随后成为全基因组工作的形容词。"},"items":[{"era":"GREEK GENOS","en":"Genos 'race, kind' belongs to the PIE family reconstructed as *ǵenh₁-; the root form is a reconstruction, and Latin genus is a cognate rather than the source.","cn":"genos「种族、种类」属于被重构为 *ǵenh₁- 的原始印欧语词族；该词根形式是重构，拉丁 genus 是同源词而非来源。"},{"era":"SUFFIX -OME","en":"The -ome of genome was extracted from chromosome and marks a complete set; chromosome joins Greek chroma 'colour' and soma 'body'.","cn":"genome 中的 -ome 从 chromosome 析出，标记完整集合；chromosome 由希腊 chroma「颜色」与 soma「身体」构成。"},{"era":"GERMAN COINAGE","en":"Hans Winkler coined Genom in 1920, usually explained as a blend of Gen 'gene' and Chromosom 'chromosome'.","cn":"汉斯·温克勒于 1920 年造出 Genom，通常解释为 Gen「基因」与 Chromosom「染色体」的混成。"},{"era":"ADJECTIVE FORM","en":"Genomic was formed with -ic to mark relation to a genome; its first recorded use is not precisely dated.","cn":"genomic 由 -ic 构成，标记与基因组的关系；其最早书证没有精确年代。"},{"era":"WHOLE-SET SCIENCE","en":"With genomics in the late 1980s, genomic became the standard adjective for data, medicine and selection at whole-genome scale.","cn":"随着 20 世纪 80 年代末基因组学的兴起，genomic 成为全基因组尺度的数据、医学与选择的标准形容词。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the coinage of genome is documented, but the first use of genomic is approximate, and no Latin derivative exists, so latinEntries is empty.","cn":"来源不确定（首见年代）：genome 的造词有文献可查，但 genomic 的最早使用只是约数；不存在拉丁派生词，因此 latinEntries 留空。"}]},"similar":{"note":{"en":"Group one separates genomic from same-root adjectives and one accidental sound-alike; group two separates it from genetic and from the neighbouring whole-set sciences.","cn":"第一组把 genomic 与同根形容词及一个偶然音近词分开；第二组把它与 genetic 及相邻的整套学科词区分。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"genetic","ipa":"/dʒəˈnetɪk/","tag":"same root, narrower scale","definition":"Relating to genes, often one or a few at a time; genomic refers to the whole set.","definitionCN":"与基因相关，常指一个或少数几个；genomic 指整套。"},{"word":"genomics","ipa":"/dʒəˈnɒmɪks/","tag":"same root, the science","definition":"The study of genomes; genomic is the adjective, genomics the discipline.","definitionCN":"研究基因组的学科；genomic 是形容词，genomics 是学科。"},{"word":"genomically","ipa":"/dʒəˈnɒmɪkli/","tag":"same root, the adverb","definition":"At the level of the genome; the adverb marks the respect in which a claim holds.","definitionCN":"在基因组层面；副词标记断言成立的方面。"},{"word":"gnomic","ipa":"/ˈɡnəʊmɪk/","tag":"different root","definition":"From Greek gnome 'maxim, thought', not genos: expressed in short, obscure maxims. The resemblance is only in sound.","definitionCN":"来自希腊 gnome「格言、思想」，并非 genos：指以简短隐晦的格言表达。相似仅在读音。"}]},{"heading":"NEAR MEANING","entries":[{"word":"genetic","ipa":"/dʒəˈnetɪk/","tag":"gene-level","definition":"Gene-level in focus; genomic is whole-set in focus, though both belong to the same field.","definitionCN":"聚焦基因层面；genomic 聚焦整套，但两者属于同一领域。"},{"word":"genomics","ipa":"/dʒəˈnɒmɪks/","tag":"the discipline","definition":"The discipline that produces genomic data; the adjective names what belongs to that scale.","definitionCN":"产生基因组数据的学科；形容词命名属于该尺度的事物。"},{"word":"transcriptomic","ipa":"/trænˈskrɪptɒmɪk/","tag":"a different whole set","definition":"Relating to all transcripts rather than all genes; the suffix is shared but the object differs.","definitionCN":"与全部转录本相关而非全部基因；后缀相同但对象不同。"},{"word":"proteomic","ipa":"/ˌprəʊtiˈɒmɪk/","tag":"a downstream set","definition":"Relating to the complete set of proteins, downstream of the genome.","definitionCN":"与全部蛋白质相关，位于基因组下游。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"genome + -ic: belonging to the whole set.","cn":"genome + -ic：属于整套。"},{"en":"The family runs genome, genomic, genomics and genomically.","cn":"同族词包括 genome、genomic、genomics 与 genomically。"},{"en":"Genomic data, genomic medicine and genomic selection are fixed phrases.","cn":"基因组数据、基因组医学与基因组选择是固定搭配。"},{"en":"Genomic is whole-set; genetic is gene-level.","cn":"genomic 是整套层面；genetic 是基因层面。"},{"en":"Genomics is the field; genomic is its adjective.","cn":"genomics 是领域；genomic 是它的形容词。"}],"abstract":[{"en":"Picture an entire shelf read at once instead of one book at a time.","cn":"想象整排书架一次被读完，而不是一次读一本。"},{"en":"Picture a map where every street is visible at once.","cn":"想象一张所有街道同时可见的地图。"},{"en":"Picture a weather report that covers a continent, not one town.","cn":"想象一份覆盖整块大陆而非一个小镇的气象报告。"}]},"examples":[{"en":"Genomic sequencing has become cheaper than many single-gene tests.","cn":"基因组测序已比许多单基因检测更便宜。"},{"en":"The clinic opened a genomic medicine service last year.","cn":"这家诊所去年开设了基因组医学服务。"},{"en":"Genomic selection shortened the breeding cycle by half.","cn":"基因组选择把育种周期缩短了一半。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"genome（基因组）+ ic（形容词尾）——整个基因组的 → 基因组的；与 genetic（基因层面的）相对。","word":"genomic"},"root":"genome + -ic；genome 来自德语 Genom（温克勒，1920）＝Gen「基因」+ Chromosom「染色体」混成；gen 源于希腊 genos「种族、种类」。","sensesIntro":{"en":"Eight senses follow one scale: the whole genome, its sequencing, its medical use, its data, its variation, its research, its scale and its use in breeding.","cn":"八个义项沿同一个尺度展开：整个基因组、其测序、其医学用途、其数据、其变异、其研究、其尺度与育种用途。"},"semanticMap":{"core":{"en":"CORE IMAGE: a machine reading thousands of instruction strips at once.","cn":"核心意象：一台机器同时读取成千上万段指令条。"},"chain":["GENE","WHOLE SET","SEQUENCED","DATA","MEDICAL USE","BREEDING SCORE"],"branches":[{"senses":"S1 · S7","en":"WHOLE-SET SCALE: the adjective always marks the set, whether as object or as scale of work.","cn":"整套尺度：这个形容词始终标记整套，无论作为对象还是工作尺度。"},{"senses":"S2 · S4","en":"READING AND DATA: sequencing produces the reads, and the reads become sensitive data.","cn":"读取与数据：测序产生读段，读段成为敏感数据。"},{"senses":"S3","en":"MEDICINE: whole-genome information guides treatment.","cn":"医学：全基因组信息指导治疗。"},{"senses":"S5 · S6","en":"VARIATION AND RESEARCH: differences across sets, and a field that spans biology.","cn":"变异与研究：整套之间的差异，以及横跨生物学的领域。"},{"senses":"S8","en":"BREEDING: many markers combined into one predicted score.","cn":"育种：许多标记合并为一个预测分数。"}]},"affixes":{"intro":{"en":"Genomic is genome plus a relation suffix; the stem goes back through German to Greek, and the suffix family names the whole-set sciences.","cn":"genomic 是 genome 加关系后缀；词干经德语上溯希腊，后缀家族命名整套层面的各门学科。"},"latinIntro":{"en":"Greek genos gives gene; -ome from chromosome gives genome; -ic gives genomic, and -ics gives genomics. No Latin derivative exists, so latinEntries is empty.","cn":"希腊 genos 衍生 gene；来自 chromosome 的 -ome 构成 genome；-ic 构成 genomic，-ics 构成 genomics。不存在拉丁派生词，因此 latinEntries 留空。"},"items":[{"word":"genos","structure":"genos (Greek noun, 'race, kind')","meaning":"race; kind","meaningCN":"种族；种类","example":"The stem names a reproducing kind.","exampleCN":"这个词干命名自我繁衍的类。"},{"word":"-ome","structure":"-ome (suffix from chromosome)","meaning":"complete set","meaningCN":"完整集合","example":"The suffix marks a whole collection.","exampleCN":"这个后缀标记完整集合。"},{"word":"genome","structure":"Gen + Chromosom (German, 1920)","meaning":"the complete set of genes","meaningCN":"基因组","example":"The genome was sequenced.","exampleCN":"基因组被测序。"},{"word":"-ic","structure":"-ic (adjective suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix forms a relational adjective.","exampleCN":"这个后缀构成关系形容词。"},{"word":"genomic","structure":"genome + -ic","meaning":"relating to a genome","meaningCN":"基因组的","example":"Genomic data arrived quickly.","exampleCN":"基因组数据很快到达。"},{"word":"genomics","structure":"genome + -ics","meaning":"the study of whole genomes","meaningCN":"基因组学","example":"Genomics compares complete sequences.","exampleCN":"基因组学比较完整序列。"},{"word":"genomically","structure":"genomic + -ally","meaning":"at genome level","meaningCN":"在基因组层面","example":"The samples were compared genomically.","exampleCN":"样本在基因组层面做了比较。"},{"word":"gene","structure":"genos, shortened","meaning":"unit of heredity","meaningCN":"基因","example":"A gene is a unit of heredity.","exampleCN":"基因是遗传单位。"},{"word":"genotype","structure":"genos + typos 'impression'","meaning":"the inherited constitution","meaningCN":"基因型","example":"The genotype was recorded.","exampleCN":"基因型被记录。"},{"word":"phenotype","structure":"phainein 'show' + typos","meaning":"the observable traits","meaningCN":"表现型","example":"The phenotype was measured.","exampleCN":"表现型被测量。"}],"latinEntries":[]}},{"word":"genotype","ipa_uk":"/ˈdʒiːnətaɪp/","ipa_us":"/ˈdʒiːnoʊtaɪp/","definition_zh":"基因型；一个生物体的遗传组成","definition_en":"the genetic constitution of an organism, especially the combination of alleles at one or more loci","core_image":"同一株植物在不同土壤里外形不同，但根里那套指令始终一致","scene":"同一株植物在不同土壤里长得不一样，但根里的指令相同。Two plants may share a genotype yet look completely different.","sceneCN":"这里 genotype 指「生物体内部的遗传组成」（第 1 个义项：全部遗传指令的组合）；句意为两株植物可以基因型相同，外表却完全不同。可辨识物件：两盆植物、不同土壤、根系示意图、指令卡片。","pos":[{"tag":"n.","zh":"基因型；遗传组成"}],"collocations":[{"phrase":"genotype and phenotype","zh":"基因型与表现型"},{"phrase":"genotype frequency","zh":"基因型频率"},{"phrase":"genotype testing","zh":"基因型检测"},{"phrase":"the genotype of","zh":"……的基因型"},{"phrase":"genotype-phenotype map","zh":"基因型—表现型对应图"},{"phrase":"heterozygous genotype","zh":"杂合基因型"}],"forms":[{"label":"复数","form":"genotypes"},{"label":"所有格","form":"genotype's"},{"label":"形容词","form":"genotypic"},{"label":"副词","form":"genotypically"}],"derivatives":[{"word":"genotypic","pos":"adj.","zh":"基因型的"},{"word":"genotypically","pos":"adv.","zh":"按基因型地"},{"word":"phenotype","pos":"n.","zh":"表现型"},{"word":"genome","pos":"n.","zh":"基因组"}],"senses":[{"no":"01","title":"The inherited constitution","titleCN":"遗传组成","definition":"the complete set of inherited instructions in an organism","definitionCN":"一个生物体所继承的全部指令集合","example":"The genotype of an organism is its full set of inherited instructions.","exampleCN":"一个生物体的基因型就是它所继承的全部指令。","why":"Johannsen coined the word to separate what is inherited from what is seen, so genotype names the internal constitution.","whyCN":"约翰森造这个词是为了把「遗传的」与「看见的」分开，因此基因型命名内部组成。"},{"no":"02","title":"Genotype contrasted with phenotype","titleCN":"与表现型相对的基因型","definition":"the inherited constitution considered apart from its observable expression","definitionCN":"与其可观察表现分开考虑的遗传组成","example":"Two mice with the same genotype can differ in phenotype.","exampleCN":"基因型相同的两只小鼠可以有不同的表现型。","why":"The pair genotype and phenotype was coined together, and each word is defined by its contrast with the other.","whyCN":"基因型与表现型是成对造出的，每个词都通过与另一个词对照而获得定义。"},{"no":"03","title":"Genotype at one locus","titleCN":"某一位点上的基因型","definition":"the combination of alleles at a specified genetic locus","definitionCN":"在特定位点上等位基因的组合","example":"The genotype at that locus was heterozygous in half the sample.","exampleCN":"该位点的基因型在样本中有一半是杂合的。","why":"The word narrowed from the whole constitution to the allele pair at one address, especially in laboratory genetics.","whyCN":"这个词从整体组成收窄到某一地址上的等位基因对，尤其在实验室遗传学中。"},{"no":"04","title":"Genotype testing","titleCN":"基因型检测","definition":"laboratory testing that identifies a specific inherited constitution","definitionCN":"识别特定遗传组成的实验室检测","example":"Genotype testing identifies carriers before symptoms appear.","exampleCN":"基因型检测在症状出现前识别携带者。","why":"Testing turns the abstract constitution into a result that can guide decisions.","whyCN":"检测把抽象的组成变成可指导决策的结果。"},{"no":"05","title":"Genotype frequency","titleCN":"基因型频率","definition":"the proportion of individuals in a group with a given genotype","definitionCN":"一个群体中具有某一基因型的个体比例","example":"Genotype frequencies shift under selection.","exampleCN":"基因型频率在选择作用下发生移动。","why":"Population genetics counts constitutions, so the word becomes a frequency rather than a property of one body.","whyCN":"群体遗传学对组成进行计数，因此这个词成为频率，而非单个身体的性质。"},{"no":"06","title":"The genotype-phenotype map","titleCN":"基因型与表现型的对应关系","definition":"the relationship by which inherited constitution produces observable traits","definitionCN":"遗传组成产生可观察性状的对应关系","example":"The genotype-phenotype map is rarely one to one.","exampleCN":"基因型与表现型的对应关系很少是一对一的。","why":"The compound marks the central problem of genetics: many instructions can lead to one form, and one instruction to many forms.","whyCN":"这个复合词标记遗传学的核心难题：多套指令可以导致一种形态，一套指令也可以导致多种形态。"},{"no":"07","title":"Classification by genotype","titleCN":"按基因型分类","definition":"grouping organisms by inherited constitution rather than by appearance","definitionCN":"按遗传组成而非外表对生物分组","example":"Breeders group animals by genotype rather than appearance.","exampleCN":"育种者按基因型而非外表给动物分组。","why":"When appearance misleads, classification moves to the constitution, which is why genotype becomes a sorting label.","whyCN":"当外表会误导时，分类转向内部组成，因此基因型成为分类标签。"},{"no":"08","title":"Genotype in microbiology","titleCN":"微生物学中的基因型","definition":"the inherited constitution of a virus or microbe, often used to trace strains","definitionCN":"病毒或微生物的遗传组成，常用于追踪毒株","example":"The viral genotype determines which cells it can enter.","exampleCN":"病毒的基因型决定它能进入哪些细胞。","why":"In microbiology the word often names a strain marker, since small genomes make the constitution easy to compare.","whyCN":"在微生物学中，这个词常命名毒株标记，因为小基因组使组成易于比较。"}],"etymology":{"intro":{"en":"Genotype was introduced by Wilhelm Johannsen in 1909 as German Genotypus, joining genos 'race, kind' with typos 'impression, mold'.","cn":"genotype 由威廉·约翰森于 1909 年以德语 Genotypus 引入，把 genos「种族、种类」与 typos「印痕、模子」结合起来。"},"items":[{"era":"GREEK GENOS","en":"Genos 'race, kind' belongs to the PIE family reconstructed as *ǵenh₁-; the root form is a reconstruction, and Latin genus is a cognate rather than the source.","cn":"genos「种族、种类」属于被重构为 *ǵenh₁- 的原始印欧语词族；该词根形式是重构，拉丁 genus 是同源词而非来源。"},{"era":"GREEK TYPOS","en":"Typos meant 'impression, mold, model'; it also appears in phenotype, typography and in Latin typus, a loan from Greek.","cn":"typos 意为「印痕、模子、模型」；它也出现在 phenotype、typography 以及借自希腊的拉丁 typus 中。"},{"era":"GERMAN COINAGE","en":"Johannsen used German Genotypus in 1909 to name the inherited constitution, in deliberate contrast with the visible result.","cn":"约翰森在 1909 年使用德语 Genotypus，命名遗传组成，刻意与可见结果相对。"},{"era":"ENGLISH ADOPTION","en":"English genotype is recorded by 1910; spelling and first date vary between Genotypus and genotype, and early translations complicate the record.","cn":"英语 genotype 在 1910 年前已有记录；Genotypus 与 genotype 的拼写和首见年代各有差异，早期翻译使记录更复杂。"},{"era":"NARROWING","en":"The word moved from the whole constitution to the allele combination at a single locus, a narrower laboratory use.","cn":"这个词从整体组成转向单位点的等位基因组合，这是更窄的实验室用法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first English date and spelling): the coinage is documented, but the route into English is not precisely dated, and no Latin derivative of the compound exists, so latinEntries is empty.","cn":"来源不确定（英语首见年代与拼写）：造词有文献可查，但进入英语的路径没有精确年代；该复合词没有拉丁派生词，因此 latinEntries 留空。"}]},"similar":{"note":{"en":"Group one separates genotype from its paired and same-root terms plus one accidental look-alike; group two separates it from the observable and the carrier concepts.","cn":"第一组把 genotype 与成对词、同根词及一个偶然形近词分开；第二组把它与「可观察」和「载体」概念区分。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"phenotype","ipa":"/ˈfiːnətaɪp/","tag":"same second element, opposite half","definition":"The observable traits produced by the genotype plus environment; the two words were coined as a pair.","definitionCN":"由基因型与环境共同产生的可观察性状；两词是成对造出的。"},{"word":"genotypic","ipa":"/ˌdʒiːnəˈtɪpɪk/","tag":"same root, adjective","definition":"The adjective meaning 'of a genotype'; it does not name the constitution itself.","definitionCN":"意为「基因型的」的形容词；它不命名组成本身。"},{"word":"genome","ipa":"/ˈdʒiːnəʊm/","tag":"same root, the whole material","definition":"The entire genetic material; the genotype is the constitution with respect to particular loci or alleles.","definitionCN":"指全部遗传物质；基因型是就特定位点或等位基因而言的组成。"},{"word":"karyotype","ipa":"/ˈkæriətaɪp/","tag":"different first element","definition":"From Greek karyon 'nut, kernel' plus typos: the number and appearance of chromosomes, not the allele constitution.","definitionCN":"来自希腊 karyon「核、仁」加 typos：指染色体的数目与外观，而非等位基因组成。"}]},{"heading":"NEAR MEANING","entries":[{"word":"phenotype","ipa":"/ˈfiːnətaɪp/","tag":"the observable result","definition":"What can be seen or measured; genotype is the inherited instruction behind it.","definitionCN":"可见或可测的结果；基因型是它背后的遗传指令。"},{"word":"genome","ipa":"/ˈdʒiːnəʊm/","tag":"the whole material","definition":"The complete sequence; genotype is a description of constitution at specified loci.","definitionCN":"指完整序列；基因型是对特定位点组成的描述。"},{"word":"allele","ipa":"/əˈliːl/","tag":"one version","definition":"One alternative form at a locus; a genotype is the combination of such forms.","definitionCN":"指某位点的一种备选形式；基因型是这类形式的组合。"},{"word":"strain","ipa":"/streɪn/","tag":"a laboratory lineage","definition":"A lineage of organisms with a shared background; genotype is the precise constitution used to define it.","definitionCN":"指共享背景的生物谱系；基因型是用来界定它的精确组成。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"genos 'kind' + typos 'mold': the kind stamped inside.","cn":"genos「种类」+ typos「模子」：印在内部的那个种类。"},{"en":"The pair is genotype and phenotype: inside versus outside.","cn":"成对词是 genotype 与 phenotype：内部对表面。"},{"en":"The family runs genotype, genotypic, genotypically and phenotype.","cn":"同族词包括 genotype、genotypic、genotypically 与 phenotype。"},{"en":"At one locus, genotype means the allele pair.","cn":"在单个位点上，基因型指等位基因对。"},{"en":"Genotype testing looks at the constitution before symptoms.","cn":"基因型检测在症状出现前查看组成。"}],"abstract":[{"en":"Picture a sealed blueprint that may be built in several different ways.","cn":"想象一张密封蓝图，可以用几种不同方式建造。"},{"en":"Picture the same recipe cooked in two kitchens with different results.","cn":"想象同一份食谱在两个厨房做出不同结果。"},{"en":"Picture a locked box whose label describes the contents, not the contents themselves.","cn":"想象一只锁着的箱子，标签描述内容，却不等于内容。"}]},"examples":[{"en":"The genotype of each seedling was recorded before planting.","cn":"每株幼苗的基因型在栽种前被记录。"},{"en":"Genotype frequencies changed after the drought.","cn":"干旱之后基因型频率发生变化。"},{"en":"The viral genotype was used to trace the outbreak.","cn":"病毒基因型被用来追踪疫情。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"geno（种类）+ type（模子）——内部印着的那套模子 → 基因型；与 phenotype（表现型）成对。","word":"genotype"},"root":"希腊 genos「种族、种类」+ typos「印痕、模子」；约翰森 1909 年以德语 Genotypus 造词；genos 出自原始印欧语 *ǵenh₁-（重构形式）。","sensesIntro":{"en":"Eight senses follow an inner constitution: the whole set, its contrast with phenotype, one locus, a test, a frequency, a map, a classification and a strain marker.","cn":"八个义项沿一份内部组成展开：整套、与表现型的对照、单个位点、检测、频率、对应图、分类与毒株标记。"},"semanticMap":{"core":{"en":"CORE IMAGE: one plant, two soils, two shapes, one identical set of instructions in the roots.","cn":"核心意象：同一株植物，两种土壤，两种外形，根里却是同一套指令。"},"chain":["KIND","MOLD","INNER CONSTITUTION","VERSUS PHENOTYPE","LOCUS PAIR","STRAIN MARKER"],"branches":[{"senses":"S1","en":"THE CONSTITUTION: the full inherited instruction set of one organism.","cn":"组成：一个生物体所继承的完整指令集。"},{"senses":"S2 · S6","en":"THE PAIR AND THE MAP: what is inherited versus what is seen, and how the two connect.","cn":"成对与对应：遗传之物对可见之物，以及两者如何连接。"},{"senses":"S3 · S7","en":"LOCUS AND CLASSIFICATION: the allele pair at one address, and sorting by constitution.","cn":"位点与分类：某一地址上的等位基因对，以及按组成归类。"},{"senses":"S4 · S5","en":"TEST AND FREQUENCY: a result that guides decisions, and a proportion in a group.","cn":"检测与频率：指导决策的结果，以及群体中的比例。"},{"senses":"S8","en":"STRAIN MARKER: in microbes, the constitution used to trace a lineage.","cn":"毒株标记：在微生物中，用来追踪谱系的组成。"}]},"affixes":{"intro":{"en":"Genotype joins two Greek elements; the second, typos, also builds phenotype and a family of type words.","cn":"genotype 结合两个希腊成分；第二个成分 typos 还构成 phenotype 及一批以 type 结尾的词。"},"latinIntro":{"en":"Greek genos gives the first element, typos the second. The same typos appears in phenotype, karyotype and typography. No Latin derivative of the compound exists, so latinEntries is empty.","cn":"希腊 genos 提供第一个成分，typos 提供第二个。同一 typos 还出现在 phenotype、karyotype 与 typography 中。该复合词没有拉丁派生词，因此 latinEntries 留空。"},"items":[{"word":"genos","structure":"genos (Greek noun, 'race, kind')","meaning":"race; kind","meaningCN":"种族；种类","example":"The first element names the kind.","exampleCN":"第一个成分命名种类。"},{"word":"typos","structure":"typos (Greek noun, 'impression, mold')","meaning":"impression; mold; model","meaningCN":"印痕；模子；模型","example":"The second element names the stamp or pattern.","exampleCN":"第二个成分命名印记或模式。"},{"word":"geno-","structure":"geno- (combining form from genos)","meaning":"kind; gene","meaningCN":"种类；基因","example":"The combining form joins genotype and genome.","exampleCN":"这个组合形式连接 genotype 与 genome。"},{"word":"-type","structure":"-type (combining form from typos)","meaning":"type; model","meaningCN":"类型；模型","example":"The suffix also appears in phenotype and karyotype.","exampleCN":"这个后缀也出现在 phenotype 与 karyotype 中。"},{"word":"genotype","structure":"genos + typos (German Genotypus, 1909)","meaning":"the inherited constitution","meaningCN":"基因型","example":"The genotype was recorded.","exampleCN":"基因型被记录。"},{"word":"genotypic","structure":"genotype + -ic","meaning":"of a genotype","meaningCN":"基因型的","example":"The genotypic difference was small.","exampleCN":"基因型差异很小。"},{"word":"genotypically","structure":"genotypic + -ally","meaning":"by genotype","meaningCN":"按基因型地","example":"The lines differ genotypically.","exampleCN":"这些品系在基因型上不同。"},{"word":"phenotype","structure":"phainein 'show' + typos","meaning":"the observable traits","meaningCN":"表现型","example":"The phenotype was measured.","exampleCN":"表现型被测量。"},{"word":"phenotypic","structure":"phenotype + -ic","meaning":"of a phenotype","meaningCN":"表现型的","example":"Phenotypic variation was wide.","exampleCN":"表现型变异很大。"},{"word":"karyotype","structure":"karyon 'kernel' + typos","meaning":"chromosome number and appearance","meaningCN":"核型","example":"The karyotype showed an extra chromosome.","exampleCN":"核型显示多了一条染色体。"},{"word":"genome","structure":"genos + -ome","meaning":"the whole set of genes","meaningCN":"基因组","example":"The genome was sequenced.","exampleCN":"基因组被测序。"}],"latinEntries":[]}},{"word":"phenotype","ipa_uk":"/ˈfiːnətaɪp/","ipa_us":"/ˈfiːnoʊtaɪp/","definition_zh":"表现型；可观察的性状组合","definition_en":"the observable traits of an organism, produced by its genotype together with its environment","core_image":"同一批种子播在两种土里，叶色与株高出现差别，标签上却写着同一串内部编号","scene":"同一批种子播在两种土里，叶色与株高出现差别。Leaf colour and height form part of the phenotype of a plant.","sceneCN":"这里 phenotype 指「生物体可观察到的性状组合」（第 1 个义项：可见或可测的特征）；句意为叶色与株高构成植物表现型的一部分。可辨识物件：两排幼苗、两种土壤、叶色对比卡、株高尺。","pos":[{"tag":"n.","zh":"表现型；可观察性状"}],"collocations":[{"phrase":"phenotype and genotype","zh":"表现型与基因型"},{"phrase":"phenotypic plasticity","zh":"表现型可塑性"},{"phrase":"clinical phenotype","zh":"临床表现型"},{"phrase":"phenotype screening","zh":"表现型筛查"},{"phrase":"behavioural phenotype","zh":"行为表现型"},{"phrase":"phenotype expression","zh":"表现型表达"}],"forms":[{"label":"复数","form":"phenotypes"},{"label":"所有格","form":"phenotype's"},{"label":"形容词","form":"phenotypic"},{"label":"副词","form":"phenotypically"}],"derivatives":[{"word":"phenotypic","pos":"adj.","zh":"表现型的"},{"word":"phenotypically","pos":"adv.","zh":"按表现型地"},{"word":"genotype","pos":"n.","zh":"基因型"},{"word":"phenomics","pos":"n.","zh":"表现组学"}],"senses":[{"no":"01","title":"Observable traits","titleCN":"可观察的性状组合","definition":"the set of traits that can be observed or measured in an organism","definitionCN":"一个生物体可观察或可测量的性状集合","example":"Leaf colour and height form part of the phenotype of a plant.","exampleCN":"叶色与株高构成植物表现型的一部分。","why":"The word names what shows, not what is carried, so any visible or measurable feature can enter the phenotype.","whyCN":"这个词命名显现出来的东西，而非携带的东西，因此任何可见或可测特征都能进入表现型。"},{"no":"02","title":"Phenotype expression","titleCN":"表现型的表达","definition":"the way inherited instructions are realized in a particular tissue or condition","definitionCN":"遗传指令在特定组织或条件下被实现的方式","example":"The same allele can yield different phenotypes in different tissues.","exampleCN":"同一等位基因在不同组织中能产生不同表现型。","why":"Expression makes the phenotype a result of reading, not a simple copy of the genotype.","whyCN":"「表达」使表现型成为阅读的结果，而非基因型的简单复制。"},{"no":"03","title":"Phenotypic plasticity","titleCN":"表现型可塑性","definition":"the ability of one genotype to produce different phenotypes in different environments","definitionCN":"同一基因型在不同环境中产生不同表现型的能力","example":"Phenotypic plasticity lets one genotype fit several habitats.","exampleCN":"表现型可塑性让同一基因型适应几种生境。","why":"Plasticity is the clearest proof that phenotype is not fixed by genotype alone.","whyCN":"可塑性是最清楚的证据，说明表现型并不单由基因型固定。"},{"no":"04","title":"Clinical phenotype","titleCN":"临床表现型","definition":"the set of symptoms and signs by which a condition appears in a patient","definitionCN":"疾病在患者身上呈现的症状与体征组合","example":"The clinical phenotype of the disease varies between patients.","exampleCN":"这种病的临床表现在患者之间各不相同。","why":"Medicine borrowed the word for the visible course of an illness, treating symptoms as a phenotype.","whyCN":"医学借用这个词指疾病的可见过程，把症状当作一种表现型。"},{"no":"05","title":"Phenotype screening","titleCN":"表现型筛查","definition":"the process of selecting organisms by observable traits","definitionCN":"按可观察性状挑选生物的过程","example":"Phenotype screening found plants that tolerate salt.","exampleCN":"表现型筛查找到了耐盐植株。","why":"Screening works from the outside in: visible traits identify candidates before their genes are examined.","whyCN":"筛查由外而内：先由可见性状找出候选者，再检查其基因。"},{"no":"06","title":"Phenotype versus genotype","titleCN":"表现型与基因型的对照","definition":"the observable result contrasted with the inherited constitution","definitionCN":"可观察结果与遗传组成的对照","example":"Phenotype is what you measure; genotype is what is inherited.","exampleCN":"表现型是你测量的东西；基因型是遗传下来的东西。","why":"The two words were coined as a pair, and each is easiest to define by contrast with the other.","whyCN":"两个词是成对造出的，每个词都最容易通过与另一个对照来定义。"},{"no":"07","title":"Classification by phenotype","titleCN":"按表现型分类","definition":"grouping organisms by observable form rather than by genetic constitution","definitionCN":"按可观察形态而非遗传组成对生物分组","example":"Museum specimens were sorted by phenotype.","exampleCN":"博物馆标本按表现型分类。","why":"Before sequences were available, classification had to begin with what could be seen, which is phenotype.","whyCN":"在序列可用之前，分类只能从可见之物开始，也就是表现型。"},{"no":"08","title":"Behavioural phenotype","titleCN":"行为表现型","definition":"the observable behavioural traits associated with a condition or constitution","definitionCN":"与某种状况或组成相关的可观察行为特征","example":"A behavioural phenotype may accompany a genetic syndrome.","exampleCN":"行为表现型可能伴随某种遗传综合征。","why":"The word widens from body to behaviour, since behaviour is also observable and also shaped by constitution and environment.","whyCN":"这个词从身体扩展到行为，因为行为同样可观察，也同样受组成与环境塑造。"}],"etymology":{"intro":{"en":"Phenotype was introduced by Wilhelm Johannsen around 1909-1911 as German Phänotypus, joining phainein 'to show' with typos 'impression, mold'.","cn":"phenotype 由威廉·约翰森约在 1909 至 1911 年间以德语 Phänotypus 引入，把 phainein「显现」与 typos「印痕、模子」结合。"},"items":[{"era":"GREEK PHAINEIN","en":"Phainein meant 'to show, bring to light'; it also stands behind phenomenon and phantasia. The root marks what appears rather than what is hidden.","cn":"phainein 意为「显现、使见光」；它也是 phenomenon 与 phantasia 的词源。这个词根标记显现之物，而非隐藏之物。"},{"era":"GREEK TYPOS","en":"Typos meant 'impression, mold, model'; the same element appears in genotype, karyotype and typography.","cn":"typos 意为「印痕、模子、模型」；同一成分还出现在 genotype、karyotype 与 typography 中。"},{"era":"GERMAN COINAGE","en":"Johannsen used German Phänotypus around 1909-1911 to name the visible result, in deliberate contrast with genotype; the exact year is uncertain.","cn":"约翰森约在 1909 至 1911 年间使用德语 Phänotypus，命名可见结果，刻意与基因型相对；确切年份不确定。"},{"era":"ENGLISH ADOPTION","en":"English phenotype followed in the early twentieth century; the first English use is dated differently in different sources.","cn":"英语 phenotype 在 20 世纪初跟上；不同资料对其最早英语用法的年代记载不同。"},{"era":"WIDENING","en":"The word widened from visible body traits to behaviour and clinical signs, wherever observable traits are at issue.","cn":"这个词从可见身体性状扩展到行为与临床体征，凡涉及可观察性状之处都可使用。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (coinage date and first English date): the 1909-1911 window is approximate, and no Latin derivative of the compound exists, so latinEntries is empty.","cn":"来源不确定（造词年代与英语首见年代）：1909 至 1911 这一窗口只是约数；该复合词没有拉丁派生词，因此 latinEntries 留空。"}]},"similar":{"note":{"en":"Group one separates phenotype from its paired and same-root terms plus one accidental look-alike; group two separates it from the concepts of constitution and visible form.","cn":"第一组把 phenotype 与成对词、同根词及一个偶然形近词分开；第二组把它与「组成」和「可见形态」概念区分。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"genotype","ipa":"/ˈdʒiːnətaɪp/","tag":"same second element, opposite half","definition":"The inherited constitution; phenotype is what is observed after genes and environment interact.","definitionCN":"指遗传组成；表现型是基因与环境作用后可观察到的结果。"},{"word":"phenotypic","ipa":"/ˌfiːnəˈtɪpɪk/","tag":"same root, adjective","definition":"The adjective meaning 'of a phenotype'; it does not name the trait set itself.","definitionCN":"意为「表现型的」的形容词；它不命名性状集合本身。"},{"word":"phenomenon","ipa":"/fəˈnɒmɪnən/","tag":"same Greek root, different word","definition":"From phainomenon 'that which appears', sharing phainein with phenotype; it means an observable event, not a trait set.","definitionCN":"来自 phainomenon「显现之物」，与 phenotype 共享 phainein；指可观察事件，而非性状集合。"},{"word":"phonotype","ipa":"/ˈfəʊnətaɪp/","tag":"different first element","definition":"From Greek phone 'voice' plus typos: an old term for a phonetic symbol. The first element is unrelated.","definitionCN":"来自希腊 phone「声音」加 typos：指语音符号的旧术语。第一个成分无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"trait","ipa":"/treɪt/","tag":"one feature","definition":"A single observable characteristic; the phenotype is the whole set of such characteristics.","definitionCN":"指单个可观察特征；表现型是这类特征的整个集合。"},{"word":"morphology","ipa":"/mɔːˈfɒlədʒi/","tag":"form and structure","definition":"The study or description of form; phenotype also covers behaviour and physiology, not only shape.","definitionCN":"对形态的研究或描述；表现型还涵盖行为与生理，不只是形状。"},{"word":"genotype","ipa":"/ˈdʒiːnətaɪp/","tag":"the inherited half","definition":"The inherited constitution; phenotype is the result of that constitution plus environment.","definitionCN":"指遗传组成；表现型是该组成加环境的结果。"},{"word":"syndrome","ipa":"/ˈsɪndrəʊm/","tag":"a symptom cluster","definition":"A recognised cluster of signs; a clinical phenotype may be described as a syndrome.","definitionCN":"指被识别的一组体征；临床表现型可被描述为综合征。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"phainein 'show' + typos 'mold': the mold that shows.","cn":"phainein「显现」+ typos「模子」：显现出来的模子。"},{"en":"The pair is genotype and phenotype: inside versus outside.","cn":"成对词是 genotype 与 phenotype：内部对表面。"},{"en":"The family runs phenotype, phenotypic, phenotypically and phenomics.","cn":"同族词包括 phenotype、phenotypic、phenotypically 与 phenomics。"},{"en":"Phenotype is what you measure; genotype is what is inherited.","cn":"表现型是你测量的；基因型是遗传的。"},{"en":"Clinical and behavioural phenotypes extend the word beyond the body.","cn":"临床表现型与行为表现型把这个词扩展到身体之外。"}],"abstract":[{"en":"Picture the same recipe baked in two ovens, producing two different crusts.","cn":"想象同一份配方在两个烤箱里烤出两种不同的外壳。"},{"en":"Picture a blueprint that can be built as a house or a shed.","cn":"想象一张蓝图既能建造成房子，也能建造成棚屋。"},{"en":"Picture a mask that changes with the room's light.","cn":"想象一张面具随房间光线而变化。"}]},"examples":[{"en":"The phenotype was measured before any genetic testing.","cn":"表现型在任何基因检测之前被测量。"},{"en":"Phenotypic plasticity explains why clones can look different.","cn":"表现型可塑性解释了克隆体为何可以看起来不同。"},{"en":"The clinical phenotype includes tremor and loss of balance.","cn":"临床表现为震颤与失衡。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"pheno（显现）+ type（模子）——显现出来的那套样子 → 表现型；与 genotype（基因型）成对。","word":"phenotype"},"root":"希腊 phainein「显现」+ typos「印痕、模子」；约翰森约 1909—1911 年以德语 Phänotypus 造词；phainein 与 phenomenon 同源。","sensesIntro":{"en":"Eight senses follow what shows: observable traits, their expression, their plasticity, their clinical form, their screening, their contrast with genotype, their use in classification and their behavioural form.","cn":"八个义项沿「显现之物」展开：可观察性状、其表达、其可塑性、其临床形态、其筛查、与基因型的对照、分类用途与行为形态。"},"semanticMap":{"core":{"en":"CORE IMAGE: one batch of seeds in two soils, two leaf colours, one inner label.","cn":"核心意象：同一批种子播在两种土里，两种叶色，同一个内部标签。"},"chain":["SHOW","MOLD","OBSERVABLE TRAITS","GENE PLUS ENVIRONMENT","CLINICAL FORM","BEHAVIOUR"],"branches":[{"senses":"S1 · S6","en":"WHAT SHOWS: the visible set, and the contrast with what is carried inside.","cn":"显现之物：可见的集合，以及与被携带之物的对照。"},{"senses":"S2 · S3","en":"READING AND PLASTICITY: the same instructions read differently in different conditions.","cn":"阅读与可塑性：同一套指令在不同条件下被读出不同结果。"},{"senses":"S4 · S5","en":"CLINIC AND SCREENING: symptoms as a phenotype, and selection by visible traits.","cn":"临床与筛查：症状作为表现型，以及按可见性状挑选。"},{"senses":"S7","en":"CLASSIFICATION: sorting by form before sequences were available.","cn":"分类：在序列可用之前按形态归类。"},{"senses":"S8","en":"BEHAVIOUR: observable conduct also enters the phenotype.","cn":"行为：可观察的行为也进入表现型。"}]},"affixes":{"intro":{"en":"Phenotype joins a Greek verb meaning 'show' to the same element used in genotype; the family extends to the adjective, the adverb and the study of traits.","cn":"phenotype 把意为「显现」的希腊动词与 genotype 中的同一成分结合；词族延伸到形容词、副词与性状研究。"},"latinIntro":{"en":"Greek phainein 'show' gives the first element; typos 'mold' gives the second. Phenotype yields phenotypic and phenotypically, and shares typos with genotype and karyotype. No Latin derivative exists, so latinEntries is empty.","cn":"希腊 phainein「显现」提供第一个成分；typos「模子」提供第二个。phenotype 衍生 phenotypic 与 phenotypically，并与 genotype、karyotype 共享 typos。不存在拉丁派生词，因此 latinEntries 留空。"},"items":[{"word":"phainein","structure":"phainein (Greek verb, 'to show')","meaning":"to show; bring to light","meaningCN":"显现；使见光","example":"The verb names what comes into view.","exampleCN":"这个动词命名进入视野之物。"},{"word":"typos","structure":"typos (Greek noun, 'impression, mold')","meaning":"impression; mold","meaningCN":"印痕；模子","example":"The noun names the stamp or pattern.","exampleCN":"这个名词命名印记或模式。"},{"word":"pheno-","structure":"pheno- (combining form from phainein)","meaning":"showing; appearing","meaningCN":"显现的","example":"The combining form marks what appears.","exampleCN":"这个组合形式标记显现之物。"},{"word":"-type","structure":"-type (combining form from typos)","meaning":"type; model","meaningCN":"类型；模型","example":"The suffix also appears in genotype and karyotype.","exampleCN":"这个后缀也出现在 genotype 与 karyotype 中。"},{"word":"phenotype","structure":"phainein + typos (German Phänotypus)","meaning":"the observable traits","meaningCN":"表现型","example":"The phenotype was measured.","exampleCN":"表现型被测量。"},{"word":"phenotypic","structure":"phenotype + -ic","meaning":"of a phenotype","meaningCN":"表现型的","example":"Phenotypic variation was wide.","exampleCN":"表现型变异很大。"},{"word":"phenotypically","structure":"phenotypic + -ally","meaning":"by phenotype","meaningCN":"按表现型地","example":"The lines differ phenotypically.","exampleCN":"这些品系在表现型上不同。"},{"word":"phenomics","structure":"phenotype + -omics","meaning":"the large-scale study of traits","meaningCN":"表现组学","example":"Phenomics measures thousands of traits.","exampleCN":"表现组学测量成千上万个性状。"},{"word":"genotype","structure":"genos + typos","meaning":"the inherited constitution","meaningCN":"基因型","example":"The genotype was recorded.","exampleCN":"基因型被记录。"},{"word":"phenomenon","structure":"phainomenon (Greek, 'that which appears')","meaning":"an observable event","meaningCN":"现象","example":"The phenomenon was recorded.","exampleCN":"这一现象被记录。"}],"latinEntries":[]}},{"word":"mutation","ipa_uk":"/mjuːˈteɪʃən/","ipa_us":"/mjuːˈteɪʃən/","definition_zh":"突变；变异；（一般意义上的）变化；语音换音","definition_en":"a change in genetic material, the process that produces such a change, or a change of form in a broader sense","core_image":"复制过程中一个字母被换掉，整段指令的意思随之改变，纸带上留下一个明显的错位","scene":"复制过程中一个字母被换掉，整段指令的意思随之改变。A single mutation can switch off a gene that controls cell division.","sceneCN":"这里 mutation 指「遗传物质中的一个改变」（第 1 个义项：基因序列的变化）；句意为一个突变就能关闭控制细胞分裂的基因。可辨识物件：复制纸带、错位字母、红色标记、基因示意图。","pos":[{"tag":"n.","zh":"突变；基因变异"},{"tag":"n.","zh":"变化；转变（一般义）"},{"tag":"n.","zh":"语音换音（语言学）"}],"collocations":[{"phrase":"gene mutation","zh":"基因突变"},{"phrase":"mutation rate","zh":"突变率"},{"phrase":"point mutation","zh":"点突变"},{"phrase":"mutation breeding","zh":"突变育种"},{"phrase":"a mutation in","zh":"在……中的突变"},{"phrase":"harmful mutation","zh":"有害突变"}],"forms":[{"label":"复数","form":"mutations"},{"label":"所有格","form":"mutation's"},{"label":"形容词","form":"mutational"},{"label":"动词","form":"mutate"},{"label":"名词（突变体）","form":"mutant"}],"derivatives":[{"word":"mutate","pos":"v.","zh":"突变；改变"},{"word":"mutant","pos":"n./adj.","zh":"突变体；突变的"},{"word":"mutational","pos":"adj.","zh":"突变的"},{"word":"mutability","pos":"n.","zh":"可变性"}],"senses":[{"no":"01","title":"A change in genetic material","titleCN":"遗传物质中的改变","definition":"an alteration in the sequence or structure of genetic material","definitionCN":"遗传物质序列或结构的改变","example":"A mutation in the control region increased the plant's height.","exampleCN":"控制区的一个突变增加了这株植物的高度。","why":"The technical sense is a change at the level of instructions, which is why it can be small in size and large in effect.","whyCN":"技术义指指令层面的改变，因此它可以很小，却产生很大影响。"},{"no":"02","title":"The process that produces variation","titleCN":"产生变异的过程","definition":"the process by which genetic changes arise and supply variation","definitionCN":"遗传改变产生并提供变异的过程","example":"Mutation supplies the variation on which selection acts.","exampleCN":"突变为自然选择提供作用其上的变异。","why":"As a process, mutation is a source rather than an event, so it appears without an article in population genetics.","whyCN":"作为过程，突变是来源而非事件，因此在群体遗传学中常不带冠词。"},{"no":"03","title":"An organism carrying a change","titleCN":"带有突变的生物体","definition":"an organism or strain that carries an altered genetic sequence","definitionCN":"携带改变后遗传序列的生物体或品系","example":"The lab keeps a pale-eyed mutation in its fly stocks.","exampleCN":"实验室在果蝇品系中保存着一个浅色眼的突变体。","why":"Laboratory usage shortens 'a mutant organism' to 'a mutation', especially when the change is the point of interest.","whyCN":"实验室用法把「突变体生物」缩短为「一个突变」，尤其当改变本身是研究重点时。"},{"no":"04","title":"A general change of form","titleCN":"一般意义上的变化、转变","definition":"a change in form, character or policy","definitionCN":"形态、性质或政策上的变化","example":"The policy underwent several mutations before adoption.","exampleCN":"这项政策在通过前经历了几次变化。","why":"The older general sense survives outside biology, where mutation means transformation rather than sequence change.","whyCN":"较旧的一般义在生物学之外存续，那里的 mutation 指转变，而非序列改变。"},{"no":"05","title":"Vowel mutation in linguistics","titleCN":"语言学中的语音换音","definition":"a change in a vowel caused by a following sound, as in umlaut","definitionCN":"由后接音引起的元音变化，如日耳曼语变音","example":"The plural shows mutation of the root vowel.","exampleCN":"复数形式显示出词根元音的换音。","why":"Nineteenth-century philology used mutation for sound change, a sense older than the genetic one.","whyCN":"19 世纪语文学用 mutation 指语音变化，这一义比遗传义更早。"},{"no":"06","title":"Mutation rate","titleCN":"突变率","definition":"the frequency with which genetic changes arise per generation or unit of time","definitionCN":"每代或每单位时间出现遗传改变的频率","example":"Mutation rate depends on repair efficiency.","exampleCN":"突变率取决于修复效率。","why":"Measuring changes turns them into a rate, which is why mutation appears in quantitative genetics as a number.","whyCN":"测量改变使其成为比率，因此在数量遗传学中 mutation 以一个数字出现。"},{"no":"07","title":"Mutation breeding","titleCN":"突变育种","definition":"the use of induced genetic changes to produce new varieties","definitionCN":"利用诱发的遗传改变产生新品种","example":"Mutation breeding produced a shorter rice variety.","exampleCN":"突变育种产生了一种更矮的水稻品种。","why":"Breeding treats mutation as a tool: changes are induced, then selected, without inserting foreign sequences.","whyCN":"育种把突变当作工具：诱发改变后再选择，不插入外来序列。"},{"no":"08","title":"Neutral, harmful or beneficial","titleCN":"中性、有害或有利的突变","definition":"a genetic change classified by its effect on the organism","definitionCN":"按对生物体的影响分类的遗传改变","example":"Most mutations are neutral, a few are harmful, and a very few help.","exampleCN":"多数突变是中性的，少数有害，极少数有利。","why":"The word does not build harm into its meaning; effects are added by the adjectives that surround it.","whyCN":"这个词本身不含「有害」，影响是由周围的形容词加上的。"}],"etymology":{"intro":{"en":"Mutation comes from Latin mutatio 'a change', from mutare 'to change'. English used it for general change before genetics gave it a technical sense.","cn":"mutation 来自拉丁 mutatio「变化」，源自动词 mutare「改变」。在遗传学赋予它技术义之前，英语已用它表示一般变化。"},"items":[{"era":"LATIN MUTARE","en":"Mutare 'to change' is the base of mutatio. Its deeper origin is not established beyond Latin, so any pre-Latin root is a reconstruction.","cn":"mutare「改变」是 mutatio 的基础。它在拉丁语之外的更深来源未得到确证，因此任何拉丁语之前的词根均属重构。"},{"era":"LATIN MUTATIO","en":"Mutatio 'a change' was formed with -tio, the action-noun suffix, from the past participle stem mutat-.","cn":"mutatio「变化」由过去分词词干 mutat- 加动作名词后缀 -tio 构成。"},{"era":"ENGLISH BORROWING","en":"Mutation entered English in the fourteenth century with the general sense 'change, alteration'; the exact first date is uncertain.","cn":"mutation 在 14 世纪以「变化、改动」的一般义进入英语；确切首见年代不确定。"},{"era":"BIOLOGICAL SENSE","en":"Late nineteenth- and early twentieth-century genetics gave mutation the technical sense of a change in hereditary material; the genetic sense is recorded from 1894.","cn":"19 世纪末至 20 世纪初的遗传学赋予 mutation「遗传物质改变」的技术义；遗传义从 1894 年起有记录。"},{"era":"LINGUISTIC SENSE","en":"Nineteenth-century philology used mutation for vowel change, especially umlaut; the term i-mutation is recorded from 1874.","cn":"19 世纪语文学用 mutation 指元音变化，尤其是变音；i-mutation 这一术语从 1874 年起有记录。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (pre-Latin origin and sense dates): mutare has no established deeper etymology, and the boundary between general and biological use is not sharply dated.","cn":"来源不确定（拉丁语之前词源与义项年代）：mutare 没有已确立的更深词源，一般义与生物学义的分界也没有精确年代。"}]},"similar":{"note":{"en":"Group one separates mutation from its family and from a dangerous look-alike; group two separates it from words for variation and change.","cn":"第一组把 mutation 与其词族及一个易混形近词分开；第二组把它与「变异」「变化」类词区分。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mutate","ipa":"/mjuːˈteɪt/","tag":"same family, the verb","definition":"The verb meaning 'to undergo or cause a mutation'; mutation is the event or process.","definitionCN":"意为「发生或导致突变」的动词；mutation 是事件或过程。"},{"word":"mutant","ipa":"/ˈmjuːtənt/","tag":"same family, the carrier","definition":"An organism carrying a mutation, or the adjective describing it; it is a noun of the changed body.","definitionCN":"携带突变的生物体，或描述它的形容词；指被改变的身体。"},{"word":"mutational","ipa":"/mjuːˈteɪʃənl/","tag":"same family, adjective","definition":"Relating to a mutation; the adjective does not name the change itself.","definitionCN":"与突变相关的；形容词不命名改变本身。"},{"word":"mutilation","ipa":"/ˌmjuːtɪˈleɪʃən/","tag":"different root","definition":"From mutilare 'to maim, cut off', not mutare: the act of damaging or removing a part. The resemblance is accidental.","definitionCN":"来自 mutilare「残害、割去」，并非 mutare：指损伤或割除某一部分。相似是偶然的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"variation","ipa":"/ˌveəriˈeɪʃən/","tag":"difference within a group","definition":"Difference among individuals; mutation is one source of variation, not variation itself.","definitionCN":"群体内个体间的差异；突变是变异的来源之一，并非变异本身。"},{"word":"alteration","ipa":"/ˌɔːltəˈreɪʃən/","tag":"a change made","definition":"A change in something, often deliberate; mutation stresses a change in form or sequence.","definitionCN":"某物的改变，常为有意；mutation 强调形态或序列的改变。"},{"word":"change","ipa":"/tʃeɪndʒ/","tag":"the general word","definition":"The broad everyday word; mutation is narrower and often technical.","definitionCN":"宽泛的日常用词；mutation 更窄，常带技术性。"},{"word":"transformation","ipa":"/ˌtrænsfəˈmeɪʃən/","tag":"a thorough change of form","definition":"A complete change of form, often dramatic; mutation can be a single small change.","definitionCN":"形态的彻底改变，常较剧烈；mutation 可以是单个微小改变。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"mutare 'to change' + -tion: the act of changing.","cn":"mutare「改变」+ -tion：改变的行为。"},{"en":"The family runs mutate, mutation, mutant and mutational.","cn":"同族词包括 mutate、mutation、mutant 与 mutational。"},{"en":"Mutation rate, point mutation and mutation breeding are fixed phrases.","cn":"突变率、点突变与突变育种是固定搭配。"},{"en":"Mutation is not automatically harmful: most changes are neutral.","cn":"突变并非自动有害：多数改变是中性的。"},{"en":"Linguistic mutation means vowel change, an older sense.","cn":"语言学中的 mutation 指元音换音，是更早的义项。"}],"abstract":[{"en":"Picture a single wrong letter turning a recipe into a different dish.","cn":"想象一个错字母把食谱变成另一道菜。"},{"en":"Picture a copying machine that occasionally drops a mark.","cn":"想象一台复印机偶尔漏掉一个记号。"},{"en":"Picture a rumour changing as it passes from mouth to mouth.","cn":"想象一个传闻在口耳相传中改变。"}]},"examples":[{"en":"The mutation was traced to a single base change.","cn":"这个突变被追溯到单个碱基改变。"},{"en":"Mutation is the raw material of evolution.","cn":"突变是进化的原料。"},{"en":"The old word underwent a mutation in meaning over two centuries.","cn":"这个旧词在两个世纪里经历了词义变化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"mut（改变）+ ation（名词尾）——改变的结果 → 突变；一般义是「变化」。","word":"mutation"},"root":"拉丁 mutatio「变化」← mutare「改变」；mutare 在拉丁语之外的更深来源不确定，相关原始印欧语词根均属重构形式。","sensesIntro":{"en":"Eight senses follow one changed unit: the change itself, the process, the carrier, a general alteration, a vowel shift, a rate, a breeding tool and a classification by effect.","cn":"八个义项沿一个被改变的单位展开：改变本身、过程、携带者、一般变化、元音换音、比率、育种工具与按效果分类。"},"semanticMap":{"core":{"en":"CORE IMAGE: one letter replaced during copying, and the meaning of the whole strip shifts.","cn":"核心意象：复制时一个字母被替换，整条纸带的意思随之改变。"},"chain":["CHANGE","COPYING ERROR","GENETIC CHANGE","PROCESS","CARRIER","CLASSIFIED EFFECT"],"branches":[{"senses":"S1 · S2","en":"CHANGE AND SOURCE: a change in the material, and the process that keeps supplying it.","cn":"改变与来源：物质中的改变，以及不断提供改变的过程。"},{"senses":"S3 · S8","en":"CARRIER AND EFFECT: an organism that carries the change, and how its effect is classified.","cn":"携带者与效果：携带改变的生物体，以及效果如何分类。"},{"senses":"S4","en":"GENERAL CHANGE: policy and form can mutate outside biology.","cn":"一般变化：政策与形态在生物学之外也能改变。"},{"senses":"S5","en":"VOWEL CHANGE: philology used the word for sound shift before genetics did.","cn":"元音变化：语文学在遗传学之前就用这个词指语音转变。"},{"senses":"S6 · S7","en":"MEASURE AND TOOL: a rate to count, and a breeding method to use.","cn":"度量与工具：可计数的比率，以及可使用的育种方法。"}]},"affixes":{"intro":{"en":"Mutation is a Latin action noun; its stem also builds the verb, the carrier noun and the adjective, and the same root appears in words for change and unchangeability.","cn":"mutation 是拉丁动作名词；其词干还构成动词、携带者名词与形容词，同一词根也出现在表示「可变」与「不可变」的词中。"},"latinIntro":{"en":"Latin mutare gives mutate, mutation, mutant and mutable; com- and in- build commutation and immutable, trans- builds transmutation. All belong to the same changing root.","cn":"拉丁 mutare 衍生 mutate、mutation、mutant 与 mutable；com- 与 in- 构成 commutation 与 immutable，trans- 构成 transmutation。它们都属同一「改变」词根。"},"items":[{"word":"mutare","structure":"mutare (Latin verb, first conjugation)","meaning":"to change","meaningCN":"改变","example":"The root names the act of changing.","exampleCN":"这个词根命名改变的动作。"},{"word":"mutatio","structure":"mutare + -tio (action noun)","meaning":"a change","meaningCN":"变化","example":"Mutatio is the direct source of mutation.","exampleCN":"mutatio 是 mutation 的直接来源。"},{"word":"-ation","structure":"-ation (English noun suffix from Latin -atio)","meaning":"action or result","meaningCN":"行为；结果","example":"The suffix makes an action noun.","exampleCN":"这个后缀构成动作名词。"},{"word":"mutation","structure":"mutatio, borrowed into English","meaning":"a change; a genetic change","meaningCN":"变化；突变","example":"A mutation can be neutral.","exampleCN":"突变可以是中性的。"},{"word":"mutate","structure":"mutare + -ate (verb suffix)","meaning":"to change; to undergo mutation","meaningCN":"改变；突变","example":"Viruses mutate quickly.","exampleCN":"病毒突变很快。"},{"word":"mutant","structure":"mutare + -ant (one that does)","meaning":"an organism carrying a change","meaningCN":"突变体","example":"The mutant lacked wings.","exampleCN":"这个突变体没有翅膀。"},{"word":"mutational","structure":"mutation + -al","meaning":"relating to a mutation","meaningCN":"突变的","example":"Mutational load was measured.","exampleCN":"突变负荷被测量。"},{"word":"mutable","structure":"mutare + -able (can be)","meaning":"able to change","meaningCN":"可变的","example":"The sequence is mutable.","exampleCN":"序列是可变的。"},{"word":"immutable","structure":"in- 'not' + mutable","meaning":"not able to change","meaningCN":"不可变的","example":"The rule is immutable.","exampleCN":"这条规则不可改变。"},{"word":"commutation","structure":"com- 'together' + mutare","meaning":"exchange; substitution","meaningCN":"交换；替代","example":"Commutation of a sentence reduced the penalty.","exampleCN":"减刑降低了处罚。"},{"word":"transmutation","structure":"trans- 'across' + mutare","meaning":"change into another form","meaningCN":"转变；变形","example":"The transmutation of elements was once alchemy.","exampleCN":"元素转变曾属于炼金术。"}],"latinEntries":[{"word":"mutare","structure":"muto, mutare, mutavi, mutatum (verb, first conjugation)","meaning":"to change, alter","meaningCN":"改变；变更"},{"word":"mutatio","structure":"mutatio, mutationis (f., third declension)","meaning":"a change, alteration","meaningCN":"变化；改动"},{"word":"mutabilis","structure":"mutabilis, mutabile (adj.)","meaning":"changeable","meaningCN":"可变的"},{"word":"immutabilis","structure":"immutabilis, immutabile (adj.)","meaning":"unchangeable","meaningCN":"不可变的"}]}},{"word":"mutate","ipa_uk":"/mjuːˈteɪt/","ipa_us":"/mjuːˈteɪt/","definition_zh":"突变；使突变；改变形态；（语言学）发生元音换音","definition_en":"to undergo or cause a genetic change, or more generally to change form or character","core_image":"病毒在宿主里复制出新的版本，外壳上的标记一次比一次略有不同","scene":"病毒在宿主里不断复制，每隔几代就出现新的版本。Viruses mutate quickly enough to escape older vaccines.","sceneCN":"这里 mutate 指「发生遗传突变」（第 1 个义项：遗传物质发生改变）；句意为病毒突变得足够快，能逃过较旧的疫苗。可辨识物件：病毒示意球、宿主细胞、复制箭头、新旧外壳标记。","pos":[{"tag":"vi.","zh":"突变；发生遗传改变"},{"tag":"vt.","zh":"使突变；诱发突变"},{"tag":"v.","zh":"改变形态；转变（一般义）"},{"tag":"v.","zh":"发生元音换音（语言学）"}],"collocations":[{"phrase":"mutate rapidly","zh":"迅速突变"},{"phrase":"mutate into","zh":"突变成……"},{"phrase":"mutate a gene","zh":"使基因突变"},{"phrase":"mutate a virus","zh":"使病毒突变"},{"phrase":"mutate beyond recognition","zh":"变得面目全非"},{"phrase":"mutate under pressure","zh":"在压力下突变"}],"forms":[{"label":"三单（he/she/it）","form":"mutates"},{"label":"过去式","form":"mutated"},{"label":"过去分词","form":"mutated"},{"label":"现在分词","form":"mutating"},{"label":"名词（突变）","form":"mutation"},{"label":"名词（突变体）","form":"mutant"}],"derivatives":[{"word":"mutation","pos":"n.","zh":"突变；变化"},{"word":"mutant","pos":"n./adj.","zh":"突变体；突变的"},{"word":"mutational","pos":"adj.","zh":"突变的"},{"word":"mutable","pos":"adj.","zh":"可变的"}],"senses":[{"no":"01","title":"Undergo a genetic change","titleCN":"发生遗传突变","definition":"to undergo a change in genetic material","definitionCN":"遗传物质发生改变","example":"Viruses mutate quickly enough to escape older vaccines.","exampleCN":"病毒突变得足够快，能逃过较旧的疫苗。","why":"The core sense is intransitive: the material changes itself, and no outside agent is named.","whyCN":"核心义是不及物的：物质自身发生改变，不点明外部施事者。"},{"no":"02","title":"Cause a genetic change","titleCN":"使发生遗传改变","definition":"to induce or create a change in genetic material","definitionCN":"诱发或造成遗传物质的改变","example":"Researchers mutate one base to test its function.","exampleCN":"研究者使一个碱基突变，以检验其功能。","why":"The transitive use adds an experimenter: the change is made on purpose, often one site at a time.","whyCN":"及物用法加上实验者：改变是有意作出的，常常一次一个位点。"},{"no":"03","title":"Change form or appearance","titleCN":"改变形态或外观","definition":"to change in form, often gradually or beyond recognition","definitionCN":"形态发生改变，常为逐渐或面目全非","example":"The story mutated with every retelling.","exampleCN":"这个故事每复述一次就变一次。","why":"The general sense treats form like sequence: small substitutions accumulate until the thing is recognizably different.","whyCN":"一般义把形态当作序列：小的替换累积起来，直到事物明显不同。"},{"no":"04","title":"Change into something else","titleCN":"转变成另一事物","definition":"to develop into a different kind of thing","definitionCN":"发展成另一种事物","example":"The protest mutated into a national movement.","exampleCN":"这场抗议演变成全国性运动。","why":"With into, the verb names a threshold: what began as one thing now counts as another.","whyCN":"与 into 连用时，这个动词命名一个门槛：起初是一回事，如今算作另一回事。"},{"no":"05","title":"Undergo vowel mutation","titleCN":"发生元音换音","definition":"in historical linguistics, to change a vowel under the influence of a following sound","definitionCN":"在历史语言学中，指元音在后接音影响下改变","example":"Old English mutated the vowel before a high front vowel.","exampleCN":"古英语在高前元音前使元音发生换音。","why":"Philology used the verb for sound change before biology borrowed it, and the linguistic sense remains technical.","whyCN":"语文学在生物学借用之前就用这个动词指语音变化，语言学义至今仍是技术性的。"},{"no":"06","title":"Mutate a pathogen deliberately","titleCN":"有意使病原体突变","definition":"to alter a pathogen in the laboratory, often to weaken it","definitionCN":"在实验室中改变病原体，常为削弱它","example":"Scientists mutate a strain to weaken it for a vaccine.","exampleCN":"科学家使一个毒株突变，以削弱它用于疫苗。","why":"This sense is closer to engineering than to accident: the change is directed toward a goal.","whyCN":"这个义项更接近工程而非偶然：改变被导向一个目标。"},{"no":"07","title":"Mutate rapidly or slowly","titleCN":"以快或慢的速度突变","definition":"to change at a particular rate under given conditions","definitionCN":"在特定条件下以某种速率改变","example":"These bacteria mutate faster under antibiotic pressure.","exampleCN":"这些细菌在抗生素压力下突变得更快。","why":"Rate adverbs turn the verb into a measurable process, which is how mutation becomes a parameter.","whyCN":"速率副词把这个动词变成可测量的过程，突变由此成为参数。"},{"no":"08","title":"Transform a plan or idea","titleCN":"使计划或观念变形","definition":"to change a plan, idea or institution until it differs greatly from the original","definitionCN":"使计划、观念或制度改变到与原初大不相同","example":"The plan mutated beyond recognition after the review.","exampleCN":"计划在评审之后变得面目全非。","why":"The figurative use carries a warning: change without a clear limit can destroy the original purpose.","whyCN":"比喻用法带有警示：没有明确界限的改变可能毁掉原初目的。"}],"etymology":{"intro":{"en":"Mutate comes from Latin mutare 'to change'; English may have formed it from the past participle mutatus or as a back-formation from mutation, and both routes are hypotheses. It is first recorded in 1818 for general change, long before genetics.","cn":"mutate 来自拉丁 mutare「改变」；英语可能由过去分词 mutatus 构成，也可能是从 mutation 逆构，两条路径都属假说。这个词在 1818 年首次记录为一般变化义，远早于遗传学。"},"items":[{"era":"LATIN MUTARE","en":"Mutare 'to change' is the source of mutation, mutable and mutate. Its deeper origin is not established beyond Latin, so any pre-Latin root is a reconstruction.","cn":"mutare「改变」是 mutation、mutable 与 mutate 的来源。它在拉丁语之外的更深来源未得到确证，因此任何拉丁语之前的词根均属重构。"},{"era":"LATIN MUTATUS","en":"The past participle mutatus 'changed' supplied the stem behind the English verb pattern in -ate.","cn":"过去分词 mutatus「已改变的」提供了英语 -ate 动词模式背后的词干。"},{"era":"ENGLISH BORROWING","en":"Mutate appeared in English in 1818 meaning 'to change'; the exact sense development is not fully documented, and the relationship to Latin mutatus is a hypothesis.","cn":"mutate 在 1818 年以「改变」义出现在英语中；义项发展并无完整文献，且它与拉丁 mutatus 的关系属于假说。"},{"era":"BIOLOGICAL SENSE","en":"The genetic sense is recorded from 1913 and twentieth-century genetics made 'undergo mutation' the dominant sense, first of organisms and later of viruses and cells.","cn":"遗传义从 1913 年起有记录；20 世纪的遗传学使「发生突变」成为主导义，先用于生物体，后用于病毒与细胞。"},{"era":"LINGUISTIC SENSE","en":"Philologists used mutate for vowel change before the biological sense spread, and the sense survives in historical grammar.","cn":"在生物学义传播之前，语文学家已用 mutate 指元音变化，这一义在历史语法中存留。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (pre-Latin origin and sense dates): mutare has no established deeper etymology, and the dates of the biological and linguistic senses are approximate.","cn":"来源不确定（拉丁语之前词源与义项年代）：mutare 没有已确立的更深词源，生物学义与语言学义的年代都只是约数。"}]},"similar":{"note":{"en":"Group one separates mutate from its family and from a near sound-alike; group two separates it from verbs of changing and transforming.","cn":"第一组把 mutate 与其词族及一个音近词分开；第二组把它与「改变」「转变」类动词区分。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mutation","ipa":"/mjuːˈteɪʃən/","tag":"same family, the noun","definition":"The change or the process; mutate is the act of undergoing or causing it.","definitionCN":"指改变或过程；mutate 是发生或导致改变的动作。"},{"word":"mutant","ipa":"/ˈmjuːtənt/","tag":"same family, the carrier","definition":"An organism carrying a change; it names the result rather than the process.","definitionCN":"携带改变的生物体；命名结果而非过程。"},{"word":"mutable","ipa":"/ˈmjuːtəbl/","tag":"same root, a capacity","definition":"Able to change; the adjective describes a possibility, not an event.","definitionCN":"能够改变；形容词描述可能性，而非事件。"},{"word":"mute","ipa":"/mjuːt/","tag":"different root","definition":"From Latin mutus 'silent', not mutare: unable or unwilling to speak. The resemblance is only in sound.","definitionCN":"来自拉丁 mutus「沉默的」，并非 mutare：指不能或不愿说话。相似仅在读音。"}]},{"heading":"NEAR MEANING","entries":[{"word":"change","ipa":"/tʃeɪndʒ/","tag":"the general verb","definition":"The broad everyday verb; mutate is narrower and often implies form or sequence.","definitionCN":"宽泛的日常动词；mutate 更窄，常暗示形态或序列。"},{"word":"alter","ipa":"/ˈɔːltə/","tag":"make different in part","definition":"To make a partial change, often deliberate; mutate can be unintended and can go further.","definitionCN":"作部分改变，常为有意；mutate 可以无意，且程度可能更深。"},{"word":"transform","ipa":"/trænsˈfɔːm/","tag":"change thoroughly","definition":"To change form completely; mutate stresses repeated or gradual change, especially of sequences.","definitionCN":"彻底改变形态；mutate 强调反复或逐渐的改变，尤指序列。"},{"word":"evolve","ipa":"/ɪˈvɒlv/","tag":"change over generations","definition":"To develop gradually, especially by selection; mutate names the origin of variation, not the whole process.","definitionCN":"逐渐发展，尤经选择；mutate 命名变异来源，而非整个过程。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"mutare 'to change' + -ate: to make or become changed.","cn":"mutare「改变」+ -ate：使改变或发生改变。"},{"en":"The family runs mutate, mutation, mutant and mutable.","cn":"同族词包括 mutate、mutation、mutant 与 mutable。"},{"en":"Viruses mutate; researchers mutate a site; stories mutate in retelling.","cn":"病毒会突变；研究者使位点突变；故事在复述中变形。"},{"en":"Mutation is the noun; mutant is the carrier.","cn":"mutation 是名词；mutant 是携带者。"},{"en":"Linguistic mutate refers to vowel change, an older sense.","cn":"语言学中的 mutate 指元音换音，是更早的义项。"}],"abstract":[{"en":"Picture a photocopier that never makes an exact copy.","cn":"想象一台永远不能完全准确复印的复印机。"},{"en":"Picture a rumour growing a new detail at every retelling.","cn":"想象一个传闻每复述一次就长出一个新细节。"},{"en":"Picture a path worn wider by feet until it becomes a road.","cn":"想象一条被踩得越来越宽、最终变成道路的小径。"}]},"examples":[{"en":"The virus mutates slowly enough for the vaccine to remain useful.","cn":"这种病毒突变够慢，疫苗仍能发挥作用。"},{"en":"The team mutated the binding site to see what changed.","cn":"团队使结合位点突变，观察发生了什么变化。"},{"en":"The old ceremony mutated into a street festival.","cn":"这个古老仪式演变成了街头节日。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"mut（改变）+ ate（动词尾）——使改变 → 突变；名词是 mutation。","word":"mutate"},"root":"拉丁 mutare「改变」← 过去分词 mutatus；mutare 在拉丁语之外的更深来源不确定，相关原始印欧语词根均属重构形式。","sensesIntro":{"en":"Eight senses follow a changing copy: genetic change, induced change, changed form, change into another kind, vowel shift, weakened pathogen, measurable rate and a transformed plan.","cn":"八个义项沿一份不断改变的副本展开：遗传改变、诱发改变、形态改变、变成另一类、元音换音、被削弱的病原体、可测速率与变形的计划。"},"semanticMap":{"core":{"en":"CORE IMAGE: a virus copying itself, each shell slightly different from the last.","cn":"核心意象：病毒不断复制自身，外壳一次比一次略有不同。"},"chain":["CHANGE","COPY WITH ERROR","GENETIC CHANGE","INDUCED CHANGE","CHANGE INTO","BEYOND RECOGNITION"],"branches":[{"senses":"S1 · S7","en":"GENETIC CHANGE AT A RATE: the material changes itself, fast or slow.","cn":"以某速率发生的遗传改变：物质自身改变，可快可慢。"},{"senses":"S2 · S6","en":"INDUCED CHANGE: an experimenter or vaccine maker directs the change.","cn":"诱发改变：实验者或疫苗制作者引导改变。"},{"senses":"S3 · S4","en":"FORM AND THRESHOLD: appearance shifts, and a thing becomes another kind.","cn":"形态与门槛：外观移动，事物成为另一类。"},{"senses":"S5","en":"VOWEL SHIFT: historical grammar uses the verb for sound change.","cn":"元音换音：历史语法用这个动词指语音变化。"},{"senses":"S8","en":"BEYOND RECOGNITION: a plan or idea changes until its purpose is lost.","cn":"面目全非：计划或观念改变到失去原初目的。"}]},"affixes":{"intro":{"en":"Mutate is a Latin verb whose stem also builds the noun, the carrier and the adjective; prefixes extend the same root to exchange and unchangeability.","cn":"mutate 是拉丁动词，其词干还构成名词、携带者与形容词；前缀把同一词根扩展到「交换」与「不可变」。"},"latinIntro":{"en":"Latin mutare gives mutate, mutation, mutant and mutable; com- builds commutation, in- builds immutable, trans- builds transmutation. All share the changing root.","cn":"拉丁 mutare 衍生 mutate、mutation、mutant 与 mutable；com- 构成 commutation，in- 构成 immutable，trans- 构成 transmutation。它们共享「改变」词根。"},"items":[{"word":"mutare","structure":"mutare (Latin verb, first conjugation)","meaning":"to change","meaningCN":"改变","example":"The root names the act of changing.","exampleCN":"这个词根命名改变的动作。"},{"word":"mutatus","structure":"mutatus (Latin past participle)","meaning":"changed","meaningCN":"已改变的","example":"The participle supplied the verb stem.","exampleCN":"这个分词提供了动词词干。"},{"word":"-ate","structure":"-ate (English verb suffix from Latin -atus)","meaning":"to make or become","meaningCN":"使……；成为……","example":"The suffix forms a verb from the stem.","exampleCN":"这个后缀从词干构成动词。"},{"word":"mutate","structure":"mutare + -ate","meaning":"to change; to undergo mutation","meaningCN":"改变；突变","example":"Viruses mutate quickly.","exampleCN":"病毒突变很快。"},{"word":"mutation","structure":"mutare + -tion","meaning":"a change; a genetic change","meaningCN":"变化；突变","example":"A mutation can be neutral.","exampleCN":"突变可以是中性的。"},{"word":"mutant","structure":"mutare + -ant","meaning":"an organism carrying a change","meaningCN":"突变体","example":"The mutant lacked wings.","exampleCN":"这个突变体没有翅膀。"},{"word":"mutational","structure":"mutation + -al","meaning":"relating to a mutation","meaningCN":"突变的","example":"Mutational load was measured.","exampleCN":"突变负荷被测量。"},{"word":"mutable","structure":"mutare + -able","meaning":"able to change","meaningCN":"可变的","example":"The sequence is mutable.","exampleCN":"序列是可变的。"},{"word":"immutable","structure":"in- 'not' + mutable","meaning":"not able to change","meaningCN":"不可变的","example":"The rule is immutable.","exampleCN":"这条规则不可改变。"},{"word":"commute","structure":"com- 'together' + mutare","meaning":"to exchange; to travel regularly","meaningCN":"交换；通勤","example":"She commutes by train.","exampleCN":"她乘火车通勤。"},{"word":"transmute","structure":"trans- 'across' + mutare","meaning":"to change into another form","meaningCN":"转变；变形","example":"The old dream was to transmute lead into gold.","exampleCN":"古老的梦想是把铅变成金。"}],"latinEntries":[{"word":"mutare","structure":"muto, mutare, mutavi, mutatum (verb, first conjugation)","meaning":"to change, alter","meaningCN":"改变；变更"},{"word":"mutatio","structure":"mutatio, mutationis (f., third declension)","meaning":"a change, alteration","meaningCN":"变化；改动"},{"word":"mutabilis","structure":"mutabilis, mutabile (adj.)","meaning":"changeable","meaningCN":"可变的"},{"word":"immutabilis","structure":"immutabilis, immutabile (adj.)","meaning":"unchangeable","meaningCN":"不可变的"}]}}]);
